    return $result->{files}{$fsm_name};
}

sub assert_lower_rejected {
    my ($source, $fsm_name, $label, $diagnostic_re) = @_;

    my $ok = eval {
        lower_source($source, $fsm_name);
        1;
    };
    my $diagnostic = $@;

