        command => ['./bin/fsmgen', '--emit-schedule-json', $path],
    );

    ok(!$success, 'CLI schedule-report command fails closed');
    is(join('', @{$stdout_buf || []}), '', 'CLI does not emit successful schedule JSON on rejected conflict');
