                cycles         => undef,
                count_kind     => 'runtime_scalar',
                count_source   => 'second_cycles',
                entry_state    => 'main_wait_2',
                exit_state     => 'main_drive_3',
                counter_signal => 'main_wait_2_cnt',
                counter_width  => 3,
            },
        ],
        'dynamic wait report exposes both consecutive runtime waits',
