        owner_transaction   => 'run',
        context             => 'transaction_body',
        members             => [qw(reader writer)],
        target_transactions => [qw(capture emit)],
        signals             => [qw(reader_capture_start writer_emit_start)],
        schedule            => 'same_cycle_external_trigger_batch',
