subtest 'actor constants transaction port widths lower like literal widths' => sub {
    my $source = <<'ISF';
(actor constant_transaction_port_widths
  (clock clk)
  (constants
    (DATA_W 8))
  (interface
    (input start)
    (input req_addr (width 8))
    (output done)
    (output resp (width 8)))
  (transaction child
    (ports
      (input addr (width DATA_W))
      (output data (width DATA_W)))
    (on child_start)
    (update data addr)
    (complete child_done))
  (transaction parent
    (on start)
    (do child
      (bind
        (input addr req_addr)
        (output data resp)))
    (complete done)))
ISF

    my $actor = parse_source($source, 'constant-transaction-port-widths.isf');
    is(transaction_port_width($actor, 'child', 'inputs', 'addr'), 8, 'input port width resolves from actor constant');
    is(transaction_port_width($actor, 'child', 'outputs', 'data'), 8, 'output port width resolves from actor constant');

    my $scheduler = FSM::Scheduler::ISF->new();
    my $lowered = $scheduler->lower($actor);
    my $fsm = $lowered->{files}{'constant_transaction_port_widths.fsm'};

    like($fsm, qr/\(\+constants\s+\(DATA_W 8\)\s+\)/s, 'scheduled .fsm preserves actor constant declaration');
    like($fsm, qr/\(\+size[\s\S]*\(isf_port_child_addr 8\)[\s\S]*\(isf_port_child_data 8\)/, 'scheduled .fsm uses resolved transaction port widths');
    like($fsm, qr/\(= \(isf_port_child_addr req_addr\)\)/, 'do binding drives resolved input port');
    like($fsm, qr/\(= \(resp> isf_port_child_data\) <child_done\)/, 'do binding reads resolved output port');

    my $report = decode_json($scheduler->report($actor));
    is_deeply(
        [map { $_->{width} } @{$report->{transaction_port_bindings} || []}],
        [8, 8],
        'schedule report binding widths use the resolved transaction port width',
    );

    assert_fsm_reaches_hdl($fsm, 'constant_transaction_port_widths', qr/\breg\s+\[7:0\]\s+isf_port_child_addr\b/, 'HDL addr width is resolved');
    assert_fsm_reaches_hdl($fsm, 'constant_transaction_port_widths', qr/\breg\s+\[7:0\]\s+isf_port_child_data\b/, 'HDL data width is resolved');
};

