        top => 'ahb_interconnect_output_arbitration_one_window_tb',
        pass => qr/PASS one-window mapped_zero mapped_nonzero wait success error replacement unmapped/,
        ial0_checks => [
            [
                qr/\(<\(! \(& \(! \(== HTRANS 2'b00\)\) \(< HADDR 4\)\)\)\s+\(= \(HSEL_REGS> 0\)\)\s+\(= \(HADDR_REGS> 0\)\)/s,
