my $provider_source_rel = "$test_rel/source/provider.vhd";
my $generated_source_rel = "$test_rel/source/generated.vhd";
my $case = 0;
my @stage_rel;

END {
    for my $stage (@stage_rel) {
        my $absolute = repo_path($stage);
        remove_tree($absolute)
