    close $fh or die "cannot close $path: $!";
    return $bytes;
}

sub dies_like {
    my ($code, $pattern, $name) = @_;
    my $ok = eval { $code->(); 1 };
    my $error = $@;
    ok(!$ok, $name) or diag('call unexpectedly succeeded');
    like($error, $pattern, "$name reports the closed rejection")
        unless $ok;
