subtest 'closed invocation rejects caller evidence selection' => sub {
    for my $argument ('foreign-root', '--source', '--evidence') {
        my $run = run_verifier($script, $argument);
        isnt($run->{status}, 0, "$argument rejects");
        like(
            $run->{stderr},
            qr/^usage: scripts\/verify_vial_regression_promotion_evidence_transport[.]pl/m,
            "$argument reports the closed invocation",
        );
        is($run->{stdout}, '', "$argument emits no result");
        cmp_ok(bytes::length($run->{stderr}), '<=', 4_096,
            "$argument diagnostic is bounded");
    }
};

subtest 'copied hostile transport mutations fail closed' => sub {
    make_path(repo_path($fixture_root, 'scripts'));
    copy($script, $fixture_script)
        or die "cannot copy evidence-transport verifier: $!\n";
    chmod 0755, $fixture_script
        or die "cannot make copied verifier executable: $!\n";
    copy_tree($bundle, $fixture_bundle);

    my $baseline = run_verifier($fixture_script);
    is($baseline->{status}, 0, 'copied baseline verifies')
        or diag($baseline->{stderr});
    my $manifest_bytes = read_raw($fixture_manifest);
    my $payload = repo_path(
        $fixture_bundle,
        'payload/regression-promotion-corpus-v1/complete/corpus-manifest.json',
    );
    my $payload_bytes = read_raw($payload);

    reject_manifest_mutation(
        'extra manifest key',
        sub { $_[0]{foreign} = 1 },
        qr/transport manifest keys changed/,
    );
    reject_manifest_mutation(
        'manifest schema',
        sub { $_[0]{schema} =~ s/[.]v1\z/.v2/ },
        qr/transport manifest schema changed/,
    );
    reject_manifest_mutation(
        'entry order',
        sub {
            my $first = $_[0]{entries}[0];
            $_[0]{entries}[0] = $_[0]{entries}[1];
            $_[0]{entries}[1] = $first;
        },
        qr/transport manifest entry order changed/,
    );
    reject_manifest_mutation(
        'unsafe source path',
        sub { $_[0]{entries}[0]{source_relative_path} = '../evidence.json' },
        qr/transport source path is unsafe/,
    );
    reject_manifest_mutation(
        'destination mapping',
        sub { $_[0]{entries}[0]{destination_relative_path} .= '.foreign' },
        qr/transport source\/destination mapping changed/,
    );
    reject_manifest_mutation(
        'entry byte count',
        sub { ++$_[0]{entries}[0]{bytes} },
        qr/transport manifest aggregate byte count changed/,
    );
    reject_manifest_mutation(
        'entry digest',
        sub { substr($_[0]{entries}[0]{sha256}, 0, 1, '0') },
        qr/transport manifest content identity changed/,
    );
    reject_manifest_mutation(
        'bundle identity',
        sub { substr($_[0]{bundle_identity}, -1, 1, '0') },
        qr/transport manifest content identity changed/,
    );
    reject_manifest_mutation(
        'source seal',
        sub { ++$_[0]{source_seals}{corpus}{file_count} },
        qr/transport manifest source seals changed/,
    );

    write_raw($fixture_manifest, substr($manifest_bytes, 0, -1) . ' ');
    reject_current(
        'noncanonical manifest',
        qr/transport manifest is not canonical newline JSON/,
    );
    write_raw($fixture_manifest, $manifest_bytes);

    write_raw($payload, substr($payload_bytes, 0, -1) . ' ');
    reject_current(
        'noncanonical payload',
        qr/evidence payload is not canonical newline JSON/,
    );
    write_raw($payload, $payload_bytes);

    my $payload_document = $json->decode($payload_bytes);
    $payload_document->{schema} =~ s/[.]v1\z/.v2/;
    my $schema_mutation = $json->encode($payload_document) . "\n";
    is(bytes::length($schema_mutation), bytes::length($payload_bytes),
        'payload schema mutation preserves the admitted byte count');
    write_raw($payload, $schema_mutation);
    reject_current(
        'payload schema',
        qr/evidence payload SHA-256 changed/,
    );
    write_raw($payload, $payload_bytes);

    write_raw($payload, $payload_bytes . 'x');
    reject_current(
        'payload byte count',
        qr/evidence payload byte count changed/,
    );
    write_raw($payload, $payload_bytes);

    my $extra = repo_path($fixture_bundle, 'payload/foreign.json');
    write_raw($extra, "{}\n");
    reject_current('extra payload', qr/evidence transport file census changed/);
    unlink($extra) or die "cannot remove copied extra payload: $!\n";

    my $held = repo_path($scratch, 'held-payload.json');
    rename($payload, $held) or die "cannot hold copied payload: $!\n";
    reject_current('missing payload', qr/evidence transport file census changed/);
    rename($held, $payload) or die "cannot restore copied payload: $!\n";

    rename($payload, $held) or die "cannot hold copied payload: $!\n";
    symlink($fixture_manifest, $payload)
        or die "cannot create copied payload symlink: $!\n";
    reject_current('payload symlink', qr/evidence transport contains a symlink/);
    unlink($payload) or die "cannot remove copied payload symlink: $!\n";
    rename($held, $payload) or die "cannot restore copied payload: $!\n";

    rename($payload, $held) or die "cannot hold copied payload: $!\n";
    link($held, $payload) or die "cannot create copied payload hardlink: $!\n";
    reject_current('payload hardlink', qr/evidence transport contains an aliased file/);
    unlink($payload) or die "cannot remove copied payload hardlink: $!\n";
    rename($held, $payload) or die "cannot restore copied payload: $!\n";

    rename($payload, $held) or die "cannot hold copied payload: $!\n";
    mkfifo($payload, 0600) or die "cannot create copied payload FIFO: $!\n";
    reject_current('payload FIFO', qr/evidence transport contains a non-regular node/);
    unlink($payload) or die "cannot remove copied payload FIFO: $!\n";
    rename($held, $payload) or die "cannot restore copied payload: $!\n";

    my $restored = run_verifier($fixture_script);
    is($restored->{status}, 0, 'copied baseline verifies after every restoration')
        or diag($restored->{stderr});
    is($restored->{stdout}, $baseline->{stdout},
        'copied verification identity is restored exactly');
};

done_testing();

sub reject_manifest_mutation {
    my ($label, $mutate, $diagnostic) = @_;
    my $original = read_raw($fixture_manifest);
    my $document = $json->decode($original);
    $mutate->($document);
    write_raw($fixture_manifest, $json->encode($document) . "\n");
    reject_current($label, $diagnostic);
    write_raw($fixture_manifest, $original);
}

sub reject_current {
    my ($label, $diagnostic) = @_;
    my $run = run_verifier($fixture_script);
    isnt($run->{status}, 0, "$label rejects");
    like($run->{stderr}, $diagnostic, "$label reports its failing boundary");
    is($run->{stdout}, '', "$label emits no verification result");
    cmp_ok(bytes::length($run->{stderr}), '<=', 4_096,
        "$label diagnostic is bounded");
}

sub run_verifier {
    my ($executable, @arguments) = @_;
    my $error = gensym;
    my $pid = open3(
        my $input,
        my $output,
        $error,
        $^X,
        $executable,
        @arguments,
    );
    close $input;
    local $/;
    my $stdout = <$output> // '';
    my $stderr = <$error> // '';
    close $output;
    close $error;
    waitpid($pid, 0) == $pid or die "cannot wait for verifier\n";
    return {
        status => $? == -1 ? -1 : $? >> 8,
        signal => $? & 127,
        stdout => $stdout,
        stderr => $stderr,
    };
}

sub copy_tree {
    my ($source, $destination) = @_;
    find({
        no_chdir => 1,
        wanted => sub {
            my $path = $File::Find::name;
            die "copied fixture source contains a symlink\n" if -l($path);
            my $relative = File::Spec->abs2rel($path, $source);
            my $target = $relative eq '.'
                ? $destination
                : repo_path($destination, $relative);
            if (-d($path)) {
                make_path($target);
                return;
            }
            die "copied fixture source contains a non-file\n" unless -f($path);
            copy($path, $target) or die "cannot copy hostile fixture path: $!\n";
        },
    }, $source);
}

sub tree_census {
    my ($base) = @_;
    my @entries;
    find({
        no_chdir => 1,
        wanted => sub {
            my $path = $File::Find::name;
            my @stat = lstat($path);
            die "cannot stat verifier test path\n" unless @stat;
            my $relative = File::Spec->abs2rel($path, $base);
            $relative = '' if $relative eq '.';
            $relative =~ s{\\}{/}g;
            my $entry = {
                relative_path => $relative,
                device => $stat[0],
                inode => $stat[1],
                mode => $stat[2],
                links => $stat[3],
                owner => $stat[4],
                bytes => $stat[7],
                type => -l _ ? 'symlink'
                    : -d _ ? 'directory'
                    : -f _ ? 'file' : 'other',
            };
            $entry->{sha256} = sha256_hex(read_raw($path)) if -f _;
            push @entries, $entry;
        },
    }, $base);
    return [sort {
        $a->{relative_path} cmp $b->{relative_path}
    } @entries];
}

sub repo_path {
    my ($base, @parts) = @_;
    return File::Spec->catfile($base, map { split m{/} } @parts);
}

sub read_raw {
    my ($path) = @_;
    open my $fh, '<:raw', $path or die "cannot read verifier test path\n";
    local $/;
    my $bytes = <$fh> // '';
    close $fh or die "cannot close verifier test path\n";
    return $bytes;
}

sub write_raw {
    my ($path, $bytes) = @_;
    open my $fh, '>:raw', $path or die "cannot write verifier test path\n";
    print {$fh} $bytes or die "cannot write verifier test path\n";
    close $fh or die "cannot close verifier test path\n";
}

source_snapshots.t/1801-vial-v2-source-projections.t:
#!/usr/bin/env perl

use strict;
use warnings;

use Digest::SHA qw(sha256_hex);
use File::Spec;
use FindBin;
use JSON::PP ();
use Test::More;

use lib File::Spec->catdir($FindBin::Bin, '..', 'perl');

use FSM::VIAL::Parser;
use FSM::VIAL::SemanticReport;
use FSM::VIAL::SourceProjection;
use FSM::VIAL::Tool qw(execute_vial_tool_request vial_tool_capabilities);

my $repo_root = File::Spec->catdir($FindBin::Bin, '..');
my $source_name = 'vial/ahb_subordinate_base_output_arbitration.vial';
my $v1_source = slurp_raw(File::Spec->catfile($repo_root, split m{/}, $source_name));
my $v2_source = to_v2_normal($v1_source);
my $json = JSON::PP->new->canonical->utf8;

sub slurp_raw {
    my ($path) = @_;
    open my $fh, '<:raw', $path or die "Cannot read $path: $!";
    local $/;
    my $text = <$fh>;
    close $fh or die "Cannot close $path: $!";
    return $text;
}

sub to_v2_normal {
    my ($source) = @_;
    my $converted = $source;
    $converted =~ s/\(version 1\)/\(version 2\)/
        or die 'version-1 selector was not found';
    $converted =~ s/\n    \(fixtures/\n    (intents)\n    (fixtures/
        or die 'fixtures section was not found';
    return $converted;
}

sub changed {
    my ($source, $before, $after, $label) = @_;
    my $changed = $source;
    my $count = ($changed =~ s/\Q$before\E/$after/);
    die "$label mutation did not match exactly once" unless $count == 1;
    return $changed;
}

sub contains_parser_node {
    my ($value) = @_;
    return 0 unless ref($value);
    if (ref($value) eq 'HASH') {
        return 1 if exists($value->{node_kind})
            || exists($value->{atom_kind}) || exists($value->{raw});
        return scalar grep { contains_parser_node($value->{$_}) } keys %{$value};
    }
    return scalar grep { contains_parser_node($_) } @{$value}
        if ref($value) eq 'ARRAY';
    return 1;
}

sub check_v2_failure {
    my ($label, $source, $code, $message, $path, $catalog, $location_source) = @_;
    my $first = FSM::VIAL::Parser->check_source({
        text => $source,
        source_name => $source_name,
        source_catalog => $catalog || {},
    });
    my $second = FSM::VIAL::Parser->check_source({
        source_catalog => $catalog || {},
        source_name => $source_name,
        text => $source,
    });
    ok(!$first->{ok}, "$label fails closed");
    is_deeply($second, $first, "$label diagnostic is deterministic");
    is(scalar(@{$first->{diagnostics}}), 1, "$label returns one primary diagnostic");
    my $diagnostic = $first->{diagnostics}[0];
    is($diagnostic->{schema}, 'fsmgen.vial_diagnostic.v2', "$label uses the v2 diagnostic identity");
    is($diagnostic->{schema_version}, 2, "$label uses diagnostic schema version two");
    is($diagnostic->{code}, $code, "$label uses $code");
    like($diagnostic->{message}, $message, "$label explains the rejected boundary");
    like($diagnostic->{semantic_path}, $path, "$label retains a stable semantic path");
    is_deeply(
        [sort keys %{$diagnostic}],
        [sort qw(schema schema_version severity code phase message semantic_path source_location notes)],
        "$label diagnostic is closed",
    );
    is($diagnostic->{source_location}{source_name}, $location_source || $source_name,
        "$label location stays repository-relative");
    return $diagnostic;
}

sub v1_tool_request {
    my ($source) = @_;
    return {
        schema => 'fsmgen.vial_tool_request.v1',
        schema_version => 1,
        action => 'check',
        vial_source => {
            source_id => $source_name,
            source_kind_hint => 'vial',
            text => $source,
            encoding => 'utf-8',
            origin => 'memory',
            display_name => $source_name,
            canonical_id => undef,
            relative_path => $source_name,
            metadata => {},
        },
        hial_source => undef,
        options => {
            source_style => 'auto',
            output_style => undef,
            fixture_id => undef,
            scenario_ids => [],
            execution_profile => undef,
            backend_profile => undef,
            replay_manifest => undef,
            native_extension_catalogs => [],
            artifact_policy => undef,
            quiet => JSON::PP::false,
        },
    };
}

subtest 'version-1 semantic and formatting identities remain byte-exact' => sub {
    my $ir = FSM::VIAL::Parser->parse_source({
        text => $v1_source,
        source_name => $source_name,
    });
    my $report = FSM::VIAL::SemanticReport->build($ir);
    my $normal = FSM::VIAL::SourceProjection->format_source({
        text => $v1_source,
        source_name => $source_name,
        output_style => 'normal',
    })->{text};
    my $terse = FSM::VIAL::SourceProjection->format_source({
        text => $v1_source,
        source_name => $source_name,
        output_style => 'terse',
    })->{text};

    is(sha256_hex($json->encode($ir->as_hashref)),
        'a83dbb89ecf5113168db2bd92a80697c0a3bf181771cbc7a0f564a6afd0f8750',
        'v1 private SemanticIR bytes retain the pre-v2 identity');
    is(sha256_hex($json->encode($report)),
        'af17c2dc659d3039501f91d0945d829d92b651569418ee624593c7aa2ec74264',
        'v1 semantic report bytes retain the pre-v2 identity');
    is(FSM::VIAL::SourceProjection->semantic_projection_sha256($ir),
        '8e517e29bbc39108369d9d5ddbf03633e7b48290d215d0a1d04a23c0eb79447c',
        'v1 semantic projection retains the pre-v2 identity');
    is(sha256_hex($normal),
        '6a9d93ba16d72f19dde3c1153a57b7255dedcbe1be83e98e87b86b54dd2139de',
        'v1 normal formatting retains the pre-v2 bytes');
    is(sha256_hex($terse),
        'b8087ea490ffb3a812cc5563e0f4188c85887ed016a7730f2ba4568991ded898',
        'v1 terse formatting retains the pre-v2 bytes');
    is_deeply(
        [sort keys %{$report}],
        [sort qw(schema_version language language_version profile root_source sources packages required_capabilities unresolved_bridge_refs diagnostics)],
        'v1 report gains no v2 schema field or shape change');
};

subtest 'normal-v2 and terse-v2 are one typed source meaning' => sub {
    my $normal = FSM::VIAL::SourceProjection->format_source({
        text => $v2_source,
        source_name => $source_name,
        output_style => 'normal',
    });
    my $terse = FSM::VIAL::SourceProjection->format_source({
        text => $v2_source,
        source_name => $source_name,
        output_style => 'terse',
    });
    is($normal->{input_style}, 'normal', 'the explicit v2 root is detected as normal');
    like($normal->{text}, qr/\A\(vial\n  \(version 2\)/, 'normal-v2 keeps the explicit version form');
    like($normal->{text}, qr/^    \(intents\)$/m, 'normal-v2 keeps the mandatory empty intents section');
    like($terse->{text}, qr/\A\(vial 2\n  \(package/, 'terse-v2 keeps the integer version discriminator');
    unlike($terse->{text}, qr/^    \(intents\b/m, 'terse-v2 omits the empty intents wrapper');
    unlike($terse->{text}, qr/^    \((?:imports|types|transactions|models|scoreboards|fixtures)\b/m,
        'terse-v2 omits every unchanged empty or declaration-family wrapper');

    my $normal_ir = FSM::VIAL::Parser->parse_source({
        text => $normal->{text}, source_name => $source_name,
    });
    my $terse_ir = FSM::VIAL::Parser->parse_source({
        text => $terse->{text}, source_name => $source_name,
    });
    is($normal_ir->schema_version, 2, 'normal-v2 constructs semantic schema version two');
    is($normal_ir->language_version, 2, 'normal-v2 retains language version two');
    is($normal_ir->profile, 'core_directed_single_clock_v2', 'normal-v2 selects only the base v2 profile');
    is_deeply(
        $normal_ir->as_hashref->{required_capabilities},
        [qw(vial.profile.core_directed_single_clock_v2 vial.semantic_ir.v2 vial.source.v2)],
        'the v2 base SemanticIR requires only its three sorted semantic capabilities');
    is_deeply($normal_ir->as_hashref->{packages}[0]{intent_families}, [],
        'the base v2 package has a typed empty intent-family collection');
    ok(!contains_parser_node($normal_ir->as_hashref),
        'v2 SemanticIR contains no lexer token or parser-form node');

    my $normal_digest = FSM::VIAL::SourceProjection->semantic_projection_sha256($normal_ir);
    is(FSM::VIAL::SourceProjection->semantic_projection_sha256($terse_ir), $normal_digest,
        'normal-v2 and terse-v2 reparses have one source-span-free meaning');
    is(FSM::VIAL::SourceProjection->format_source({
        text => $terse->{text}, source_name => $source_name, output_style => 'normal',
    })->{text}, $normal->{text}, 'terse-v2 formats back to the same canonical normal-v2 bytes');
    is(FSM::VIAL::SourceProjection->format_source({
        text => $terse->{text}, source_name => $source_name, output_style => 'terse',
    })->{text}, $terse->{text}, 'terse-v2 formatting is byte-idempotent');

    my $v1_ir = FSM::VIAL::Parser->parse_source({ text => $v1_source, source_name => $source_name });
    is(FSM::VIAL::SourceProjection->compatibility_projection_sha256($normal_ir),
        FSM::VIAL::SourceProjection->compatibility_projection_sha256($v1_ir),
        'empty-intents v2 and v1 have one exact base compatibility projection');

    my $intent_location = $normal_ir->source_location_for('/packages/0/intent_families');
    is($intent_location->{source_name}, $source_name, 'inserted v2 collection retains authored source identity');
