sub repo_path {
    my ($relative) = @_;
    return File::Spec->catfile($repo_root, split m{/}, $relative);
}

sub slurp {
    my ($path) = @_;
    open my $fh, '<:raw', $path or die "Cannot read $path: $!";
    local $/;
    my $text = <$fh>;
    close $fh or die "Cannot close $path: $!";
    return $text;
}

sub marked_vial {
    my ($text, $name) = @_;
    my ($body) = $text =~ m{
        <!--\ lifecycle-\Q$name\E-example:start\ -->\s*
        ```vial\s*\n(.*?)\n```\s*
        <!--\ lifecycle-\Q$name\E-example:end\ -->
    }xs;
    die "selected $name lifecycle example was not found" unless defined $body;
    return $body;
}

sub changed {
    my ($source, $before, $after, $label) = @_;
    my $copy = $source;
    my $count = ($copy =~ s/\Q$before\E/$after/);
    die "$label mutation did not match exactly once" unless $count == 1;
    return $copy;
}

sub condition_shape_errors {
    my ($condition, $path) = @_;
    return ("$path is not one plain object")
        unless ref($condition) eq 'HASH';
    my @error;
    my @keys = sort keys %{$condition};
    push @error, "$path has the wrong keys"
        unless join("\0", @keys)
            eq join("\0", sort qw(domain_id kind operands reference_id));
    push @error, "$path kind is not scalar"
        if !defined($condition->{kind}) || ref($condition->{kind});
    push @error, "$path reference_id is not scalar-or-null"
        if defined($condition->{reference_id}) && ref($condition->{reference_id});
    push @error, "$path domain_id is not scalar-or-null"
        if defined($condition->{domain_id}) && ref($condition->{domain_id});
    if (ref($condition->{operands}) ne 'ARRAY') {
        push @error, "$path operands is not one array";
        return @error;
    }
    for my $index (0 .. $#{$condition->{operands}}) {
        push @error, condition_shape_errors(
            $condition->{operands}[$index], "$path/operands/$index",
        );
    }
    return @error;
}

sub check_source {
    my ($text) = @_;
    return FSM::VIAL::Parser->check_source({
        text => $text, source_name => $source_name, source_catalog => {},
    });
}

sub parse_source {
    my ($text) = @_;
    return FSM::VIAL::Parser->parse_source({
        text => $text, source_name => $source_name, source_catalog => {},
    });
}

sub build_plan {
    my ($text) = @_;
    my $built = FSM::VIAL::PlanBuilder->build({
        semantic_ir => parse_source($text),
        hial_source => {
            source_id => $hial_name, format => 'ppif', text => $hial_source,
        },
        fixture_id => 'base_output_arbitration', scenario_ids => [],
        execution_profile => 'core_directed_single_clock_execution_v2',
        replay_manifest => undef, native_extension_catalog => [],
    });
    die 'lifecycle plan did not build: ' . $json->encode($built->{diagnostics})
        unless $built->{ok};
    return $built;
}

sub check_failure {
    my ($text, $code, $message, $label) = @_;
    my $first = check_source($text);
    my $second = check_source($text);
    ok(!$first->{ok}, "$label is rejected");
    is_deeply($first, $second, "$label rejection is deterministic");
    is(scalar(@{$first->{diagnostics}}), 1,
        "$label returns one primary diagnostic");
    is($first->{diagnostics}[0]{code}, $code,
        "$label has the exact diagnostic code");
    like($first->{diagnostics}[0]{message}, $message,
        "$label explains its violated rule");
    is($first->{semantic_report}, undef,
        "$label returns no partial semantic report");
}

sub contains_parser_node {
    my ($value) = @_;
    return 0 unless ref($value);
    return 0 if eval { $value->isa('JSON::PP::Boolean') };
    return 1 if ref($value) ne 'HASH' && ref($value) ne 'ARRAY';
    return scalar(grep { contains_parser_node($_) } values %{$value})
        if ref($value) eq 'HASH';
    return scalar(grep { contains_parser_node($_) } @{$value});
}

sub source_envelope {
    my ($source_id, $text, $kind) = @_;
    return {
        source_id => $source_id, source_kind_hint => $kind, text => $text,
        encoding => 'utf-8', origin => 'memory', display_name => $source_id,
        canonical_id => undef, relative_path => $source_id, metadata => {},
    };
}

sub request_v2 {
    my (%override) = @_;
    my $action = delete($override{action}) || 'check';
    return {
        schema => 'fsmgen.vial_tool_request.v2', schema_version => 2,
        action => $action,
        vial_source => source_envelope($source_name, $selected_source, 'vial'),
        hial_source => ($action eq 'plan' || $action eq 'run')
            ? source_envelope($hial_name, $hial_source, 'ppif') : undef,
        options => {
            source_style => 'auto',
            output_style => $action eq 'format' ? 'terse' : undef,
            fixture_id => ($action eq 'plan' || $action eq 'run')
                ? 'base_output_arbitration' : undef,
            scenario_ids => [],
            execution_profile => ($action eq 'plan' || $action eq 'run')
                ? 'core_directed_single_clock_execution_v2' : undef,
            backend_profile => undef, replay_manifest => undef,
            native_extension_catalogs => [],
            artifact_policy => ($action eq 'plan' || $action eq 'run')
                ? {mode => 'virtual', artifact_root => undef} : undef,
            quiet => JSON::PP::false,
        },
        %override,
    };
}

sub environment {
    my ($sink) = @_;
    return {source_catalog => {}, artifact_sink => $sink || []};
}

sub clone {
    return $json->decode($json->encode($_[0]));
}

sub seal_source_map {
    my ($map) = @_;
    my $identity = clone($map);
    $identity->{source_map_id} = undef;
    $map->{source_map_id} = 'source-map/'
        . sha256_hex($json->encode($identity));
}

sub dies_like {
    my ($code, $pattern, $label) = @_;
    my $ok = eval { $code->(); 1 };
    my $error = $@;
    ok(!$ok, "$label is rejected");
    like($error, $pattern, "$label has the exact failure reason");
}

source_snapshots.t/1816-rust-proxy-integration.t:
#!/usr/bin/env perl
use strict;
use warnings;

use Cwd qw(abs_path);
use File::Basename qw(dirname);
use File::Path qw(make_path remove_tree);
use File::Spec;
use JSON::PP qw(decode_json encode_json);
use Test::More;
use lib 'perl', 't/lib';
use FSM::ProjectDataLocality qw(repository_root);
use FSM::Test::ProjectDataLocality;

# Execute only the extracted construction/assertion/retirement control, with
# inert builder and process observations. No original test or compiler runs.
my $root = repository_root();
open my $source_fh, '<', 't/1669-task-acceptance-fixture-runtime.t' or die $!;
my $source = do { local $/; <$source_fh> };
close $source_fh or die $!;
my ($body) = $source =~ /(subtest 'Rust parity rejects unresolved.*?)(?=subtest 'legacy RAM-guard)/s;
my ($retire) = $source =~ /(sub retire_rust_proxy_workspace \{.*?)(?=sub capture_error)/s;
my ($writer) = $source =~ /(sub write_executable \{.*?)(?=sub slurp)/s;
die 'original integration boundaries are missing' unless $body && $retire && $writer;

{
    package RustProxyIntegrationModel;
    our ($root, $scenario, @assertions, @diagnostics, @preparations, @watchers, @workspaces,
         @prepared_results, @events);
    sub ok { push @assertions, [$_[0] ? 1 : 0, $_[1]]; return $_[0]; }
    sub is { return ok(defined($_[0]) && defined($_[1]) && $_[0] eq $_[1], $_[2]); }
    sub fail { return ok(0, $_[0]); }
    sub diag {
        push @diagnostics, @_;
        for my $message (@_) {
            next if ref($message) || $message !~ /^Rust proxy preparation: (.*)\z/s;
            my $receipt = eval { JSON::PP::decode_json($1) };
            my $mode = ref($receipt) eq 'HASH' ? $receipt->{mode} : 'invalid';
            push @events, ['receipt', $mode];
        }
    }
    sub explain { return @_; }
    sub subtest { $_[1]->(); }
    sub cleanup { return {leader_started => 1, leader_reaped => 1, group_gone => 1}; }
    sub prepare_rust_proxy {
        my ($workspace, $mode, @extra) = @_;
        die 'unexpected preparation arguments' if @extra || ref($workspace)
            || ($mode ne 'proxy_nonzero' && $mode ne 'proxy_decoy');
        push @preparations, [$workspace, $mode];
        push @workspaces, $workspace;
        push @events, ['prepare', $mode];
        my $result = {
            schema => 'fsmgen.test.rust_proxy_fixture.v1', ok => 0,
            status => 'timed_out', failure_stage => 'compile',
            diagnostic => "controlled preparation failure\n",
            implementation => $scenario eq 'perl' ? 'perl' : 'native',
            selection_reason => 'controlled_selection',
            executable => undef, sources => [], compilation => undef,
            compilation_argv => undef,
        };
        if ($scenario eq 'prepare_failure') {
            push @prepared_results, {mode => $mode, prepared => {%$result}};
            return $result;
        }
        my $bin = "$workspace/rust-tools";
        mkdir($bin, 0700) or die $!;
        open my $fh, '>', "$bin/rustup" or die $!;
        print {$fh} "inert $mode fixture\n" or die $!;
        close $fh or die $!;
        chmod 0500, "$bin/rustup" or die $!;
        $result->{ok} = 1;
        $result->{status} = 'success';
        $result->{failure_stage} = undef;
        $result->{diagnostic} = 'controlled fixture prepared';
        $result->{executable} = File::Spec->abs2rel("$bin/rustup", $root);
        # Opaque test identities exercise lossless transfer, not native custody.
        $result->{sources} = [{path => $result->{executable}, device => 7, inode => 11,
                              size_bytes => 23, sha256 => 'a' x 64}];
        if ($scenario ne 'perl') {
            $result->{compilation} = {ok => 1, status => 'success', cleanup => cleanup()};
            $result->{compilation_argv} = ['controlled-clang', '-o', $result->{executable}];
            $result->{compilation}{cleanup}{group_gone} = 0 if $scenario eq 'compiler_group';
        }
        push @prepared_results, JSON::PP::decode_json(JSON::PP::encode_json({mode => $mode, prepared => $result}));
        return $result;
    }
    sub supervise_process {
        my %args = @_;
        my ($perl, $include, $test_include, $probe, $bin) = @{$args{argv}};
        die 'changed wrapper argv' unless @{$args{argv}} == 5
            && $perl eq Cwd::abs_path($^X) && $include eq '-Iperl' && $test_include eq '-It/lib'
            && $probe eq File::Basename::dirname($bin) . '/rust-tool-resolution';
        die 'changed wrapper policy' unless $args{cwd} eq $root
            && $args{bounds}{timeout_seconds} == 20 && $args{bounds}{capture_limit_bytes} == 65_536
            && $args{schema} eq 'fsmgen.test.rust_tool_resolution_probe.v1'
            && $args{stage} eq 'probe' && $args{containment} eq 'rust_tool_resolution_probe_group';
        my $mode = -d "$bin/cargo" ? 'directory' : $preparations[-1][1];
        die 'proxy canonical identity changed' if $mode ne 'directory'
            && (!-l "$bin/cargo" || Cwd::abs_path("$bin/cargo") ne "$bin/rustup");
        push @watchers, [$mode, \%args];
        push @events, ['watcher', $mode];
        push @workspaces, File::Basename::dirname($bin);
        my $cleanup = cleanup();
        $cleanup->{leader_started} = 0 if $mode eq 'directory';
        $cleanup->{leader_reaped} = 0 if $mode eq 'directory';
        my $status = $mode eq 'proxy_nonzero' ? 'nonzero_exit' : 'invocation_error';
        my $stage = $mode eq 'proxy_decoy' ? 'tool_admission' : 'tool_resolution';
        my $result = {ok => 0, status => $status, failure_stage => $stage,
                      stages => [{stage => $stage, cleanup => $cleanup}]};
        my $outer = {ok => 1, cleanup => cleanup()};
        if ($mode ne 'directory') {
            $cleanup->{group_gone} = 0 if $scenario eq 'inner_group';
            $cleanup->{leader_reaped} = 0 if $scenario eq 'inner_unreaped';
            delete $cleanup->{leader_started} if $scenario eq 'missing_cleanup';
            $cleanup->{leader_started} = undef if $scenario eq 'undefined_cleanup';
            $cleanup->{group_gone} = 'unknown' if $scenario eq 'nonboolean_cleanup';
            $outer->{cleanup}{group_gone} = 0 if $scenario eq 'outer_group';
            $result->{stages} = [] if $scenario eq 'empty_stages';
            $result->{status} = 'success' if $scenario eq 'wrong_status';
            push @{$result->{stages}}, {stage => 'cargo_build', cleanup => cleanup()}
                if $scenario eq 'unexpected_build';
        }
        $outer->{stdout} = $scenario eq 'bad_json' && $mode ne 'directory'
            ? '{broken' : JSON::PP::encode_json($result);
        return $outer;
    }
}

my $case = 0;
for my $scenario (qw(native perl prepare_failure compiler_group inner_group inner_unreaped
                     missing_cleanup undefined_cleanup nonboolean_cleanup outer_group
                     empty_stages bad_json wrong_status unexpected_build)) {
    subtest $scenario => sub {
        $RustProxyIntegrationModel::root = $root;
        $RustProxyIntegrationModel::scenario = $scenario;
        @RustProxyIntegrationModel::assertions = ();
        @RustProxyIntegrationModel::diagnostics = ();
        @RustProxyIntegrationModel::preparations = ();
        @RustProxyIntegrationModel::watchers = ();
        @RustProxyIntegrationModel::workspaces = ();
        @RustProxyIntegrationModel::prepared_results = ();
        @RustProxyIntegrationModel::events = ();
        my $package = 'RustProxyIntegrationCase' . ++$case;
        my $aliases = join "\n", map { "*$_ = \\&RustProxyIntegrationModel::$_;" }
            qw(ok is fail diag explain subtest prepare_rust_proxy supervise_process);
        my $program = "package $package; BEGIN { $aliases }\n" . <<'PRELUDE';
use Cwd qw(abs_path);
use File::Basename qw(dirname);
use File::Path qw(make_path remove_tree);
use File::Spec;
use File::Temp ();
use JSON::PP qw(decode_json);
use FSM::ProjectDataLocality qw(ensure_project_artifact_dir);
my $repo_root = $RustProxyIntegrationModel::root;
my $perl = abs_path($^X);
PRELUDE
        my $finished = eval "$program\n$body\n$retire\n$writer\n1;";
        my $error = $@;
        my %workspaces = map { $_ => 1 } @RustProxyIntegrationModel::workspaces;
        my @retained = grep { -d $_ } keys %workspaces;
        # These paths had only inert observations; this control owns their cleanup.
        remove_tree($_) for @retained;
        ok($finished, 'isolated original control executes') or diag $error;
        my @failed = grep { !$_->[0] } @RustProxyIntegrationModel::assertions;
        my $success = $scenario eq 'native' || $scenario eq 'perl';
        is(scalar(@failed) == 0 ? 1 : 0, $success ? 1 : 0, 'independent outcome distinguishes hostile inputs');
        my $retains = !$success && $scenario ne 'wrong_status' && $scenario ne 'unexpected_build';
        is(scalar(@retained), $retains ? 1 : 0, 'only unproved lifecycle retains its mode workspace');
        is(scalar(@RustProxyIntegrationModel::preparations), $retains ? 1 : 2,
            'each attempted proxy mode is prepared once without fallback or retry');
        is(scalar(@RustProxyIntegrationModel::watchers), $scenario eq 'prepare_failure' ? 1 : $retains ? 2 : 3,
            'preparation failure cannot launch its wrapper or advance to another mode');
        my @receipts = map { /^Rust proxy preparation: (.*)\z/s ? $1 : () }
            grep { !ref($_) } @RustProxyIntegrationModel::diagnostics;
        my @expected_receipts = map { JSON::PP->new->ascii->canonical->encode($_) }
            @RustProxyIntegrationModel::prepared_results;
        is_deeply(\@receipts, \@expected_receipts,
            'every preparation retains its complete canonical mode-linked receipt');
        my @expected_events = (['watcher', 'directory']);
        for my $mode ($retains ? ('proxy_nonzero') : qw(proxy_nonzero proxy_decoy)) {
            push @expected_events, ['prepare', $mode], ['receipt', $mode];
            push @expected_events, ['watcher', $mode] unless $scenario eq 'prepare_failure';
        }
        is_deeply(\@RustProxyIntegrationModel::events, \@expected_events,
            'receipt follows preparation and precedes any wrapper launch');
        ok(!grep(-e $_, keys %workspaces), 'controlled fixture cleanup leaves no workspace');
    };
}
done_testing();

source_snapshots.t/1832-process-coordinator-admission.t:
#!/usr/bin/env perl
use strict;
use warnings;
use Test::More;
use Scalar::Util qw(refaddr);
use FindBin;
use lib "$FindBin::Bin/../perl", "$FindBin::Bin/lib";
use FSM::Test::ProjectDataLocality;
use FSM::Support::ProcessSupervisor::Admission ();

# Model-only test. No fabricated numeric process identity reaches a syscall.
my $class = 'FSM::Support::ProcessSupervisor::Admission';
my $now = '100000000000';
no warnings 'redefine';
local *FSM::Support::ProcessSupervisor::Admission::_now_ns = sub { $now };
local *FSM::Support::ProcessSupervisor::GatedPair::prepare = sub { die 'native preparation forbidden' };
local *FSM::Support::ProcessSupervisor::GatedPair::start = sub { die 'native start forbidden' };
sub ledger { return FSM::Support::ProcessSupervisor::Admission::prepare(
    started_ns => '99000000000', timeout_seconds => 20) }
sub rejects {
    my ($code, $pattern, $label) = @_;
    my $ok = eval { $code->(); 1 };
    ok(!$ok && $@ =~ $pattern, $label) or diag($@ || 'unexpected acceptance');
}
sub active {
    my ($ledger, $grant) = @_;
    $ledger->begin_prepare($grant);
    $ledger->prepared($grant, 15);
    $ledger->begin_start($grant);
    $ledger->activate($grant, 7);
}
sub nested {
    my ($ledger, $parent, %extra) = @_;
    return $ledger->reserve_job(parent => $parent, started_ns => $now,
        timeout_seconds => 30, %extra);
}
sub settle {
    my ($ledger, $grant) = @_;
    $ledger->cancel($grant);
    $ledger->release_resources($grant, children => 0, descriptors => 0);
    $ledger->finish($grant);
}

subtest 'original timing and retained one-use transitions' => sub {
    my $l = ledger(); my $r = $l->root;
    is_deeply($l->describe($r), {id => 1, parent => 0, depth => 1,
        started_ns => '99000000000', timeout_seconds => '20', deadline_ns => '119000000000',
        phase => 'reserved', accepting => 1, children => 0, descriptors => 0,
        reserved_children => 2, reserved_descriptors => 16}, 'root retains literal original timing and peak charges');
    is_deeply($l->usage, {jobs => 1, children => 0, descriptors => 0,
        reserved_children => 2, reserved_descriptors => 16,
        charged_children => 2, charged_descriptors => 16}, 'unallocated capacity is distinct from actual effects');
    rejects(sub { nested($l, $r) }, qr/parent is not active/, 'unstarted parent cannot admit');
    rejects(sub { $l->begin_start($r) }, qr/expected prepared/, 'fork cannot precede preparation');
    $l->begin_prepare($r);
    rejects(sub { $l->begin_prepare($r) }, qr/expected reserved/, 'preparation is single-use');
    $l->prepared($r, 15);
    is($l->usage->{reserved_descriptors}, 0, 'prepared effects replace their reservation');
    is($l->usage->{descriptors}, 15, 'actual prepared descriptors remain charged');
    rejects(sub { $l->prepared($r, 15) }, qr/expected preparing/, 'cannot replay preparation completion');
    rejects(sub { $l->release_resources($r, children => 0, descriptors => 0) }, qr/only after launch/, 'future forks keep their full child reservation');
    $l->begin_start($r);
    rejects(sub { $l->begin_start($r) }, qr/expected prepared/, 'start grant is single-use');
    $l->activate($r, 7);
    is_deeply($l->usage, {jobs => 1, children => 2, descriptors => 7,
        reserved_children => 0, reserved_descriptors => 0,
        charged_children => 2, charged_descriptors => 7}, 'ready effects have no outstanding allocation credit');
    my $c = nested($l, $r);
    is_deeply([@{$l->describe($c)}{qw(id parent depth started_ns deadline_ns)}],
        [2, 1, 2, '100000000000', '119000000000'], 'nested deadline clips to original ancestor');
    active($l, $c);
    my $g = nested($l, $c, timeout_seconds => 2);
    is($l->describe($g)->{deadline_ns}, '102000000000', 'shorter child wall is never extended');
    $l->describe($g)->{deadline_ns} = '999999999999';
    is($l->describe($g)->{deadline_ns}, '102000000000', 'projection mutation grants no renewed wall');
    $now = '102000000000';
    rejects(sub { $l->begin_prepare($g) }, qr/deadline expired/, 'inclusive expiry prevents allocation');
    $now = '100000000000';
};

subtest 'deadline validation and expiry after retained preparation' => sub {
    for my $case (
        ['100000000001', 20, qr/future/], ['99000000000', 1, qr/expired/],
        ['099000000000', 20, qr/noncanonical/], ['99000000000', 0, qr/positive/],
    ) {
        rejects(sub { FSM::Support::ProcessSupervisor::Admission::prepare(
            started_ns => $case->[0], timeout_seconds => $case->[1]) }, $case->[2], 'invalid original invocation rejects');
    }
    my $l = ledger(); my $r = $l->root;
    $l->begin_prepare($r); $now = '119000000000';
    $l->prepared($r, 15);
    rejects(sub { $l->begin_start($r) }, qr/expired/, 'effects can be recorded after expiry but cannot start');
    is($l->usage->{charged_descriptors}, 15, 'expiry does not erase retained effects');
    settle($l, $r); $l->retire($r);
    $now = '100000000000';
    $l = ledger(); $r = $l->root; active($l, $r);
    rejects(sub { nested($l, $r, started_ns => '98000000000') }, qr/precedes its parent/, 'child cannot predate logical parent');
    my $c = nested($l, $r, timeout_seconds => 1);
    $l->begin_prepare($c); $l->prepared($c, 15); $l->begin_start($c);
    $now = '101000000000';
    rejects(sub { $l->activate($c, 7) }, qr/expired/, 'handoff cannot activate an expired grant');
    $l->cancel($c);
    is($l->usage->{reserved_children}, 2, 'interrupted start retains possible child effects until owner reconciles');
    settle($l, $c); $l->retire($c);
    $now = '119000000000';
    rejects(sub { nested($l, $r) }, qr/expired/, 'expired ancestor cannot admit a fresh child');
    $now = '18446744073709551615';
    rejects(sub { FSM::Support::ProcessSupervisor::Admission::prepare(
        started_ns => $now, timeout_seconds => 1) }, qr/exceeds wire range/, 'u64 deadline cannot overflow');
    $now = '100000000000';
};

subtest 'grant identity, creator custody and monotonic retirement' => sub {
    my $l = ledger(); my $r = $l->root; my $other = ledger();
    rejects(sub { $other->describe($r) }, qr/foreign, copied/, 'job grant belongs to one ledger');
    my $copy = bless {%$r}, ref($r);
    rejects(sub { $l->begin_prepare($copy) }, qr/foreign, copied/, 'copied grant cannot allocate');
    rejects(sub { $l->describe(1) }, qr/invalid job grant/, 'wire identity alone grants no authority');
    my $clone = bless {%$l}, ref($l);
    rejects(sub { $clone->root }, qr/copied ledger/, 'copied owner cannot share authority');
    { local $l->{owner_pid} = $$ + 1;
      rejects(sub { $l->root }, qr/inherited ledger/, 'inherited-owner model rejects before native operations'); }
    active($l, $r);
    my $a = nested($l, $r); active($l, $a);
    my $b = nested($l, $a); my $sibling = nested($l, $r);
    $l->cancel($a);
    is($l->describe($b)->{phase}, 'closing', 'cancellation revokes entire retained subtree');
    is($l->describe($sibling)->{phase}, 'reserved', 'unrelated branch retains its state');
    rejects(sub { $l->begin_prepare($b) }, qr/revoked/, 'cancel after record before allocation forbids preparation');
    rejects(sub { nested($l, $a) }, qr/revoked/, 'cancelled parent cannot admit');
    rejects(sub { $l->finish($a) }, qr/resources remain/, 'finish cannot forget resources');
    $l->release_resources($a, children => 0, descriptors => 0);
    rejects(sub { $l->release_resources($a, children => 1, descriptors => 0) }, qr/out of range|noncanonical/, 'released child capacity cannot be reclaimed');
    rejects(sub { $l->finish($a) }, qr/descendant outcome/, 'parent waits for retained descendant outcome');
    settle($l, $b);
    rejects(sub { $l->finish($a) }, qr/descendant outcome/, 'closed child still owns delivery slot');
    is($l->usage->{jobs}, 4, 'result pending still consumes job capacity');
    $l->retire($b); $l->finish($a); $l->retire($a);
    rejects(sub { $l->describe($b) }, qr/retired job grant/, 'retired job grant is stale');
    my $later = nested($l, $r);
    is($l->describe($later)->{id}, 5, 'retirement never recycles a wire identity');
    is_deeply([map { $l->describe($_)->{id} } @{$l->grants}], [1, 4, 5], 'owner can recover every still-retained grant');
    $l->cancel($r);
    settle($l, $_), $l->retire($_) for ($later, $sibling);
    settle($l, $r); $l->retire($r);
    is($l->usage->{jobs}, 0, 'child-first delivery retirement empties the ledger');
    rejects(sub { $l->reserve_descriptors(1) }, qr/root is retired/, 'retired run cannot reacquire resources');
};

subtest 'independent inclusive capacity census and closed outcome pressure' => sub {
    my $l = ledger(); my @jobs = ($l->root); active($l, $jobs[0]);
    for (2 .. 8) { push @jobs, nested($l, $jobs[-1]); active($l, $jobs[-1]); }
    is_deeply([@{$l->usage}{qw(jobs children charged_children descriptors)}],
        [8, 16, 16, 56], 'eight retained pairs independently account for sixteen children');
    is($l->describe($jobs[-1])->{depth}, 8, 'inclusive logical depth is eight');
    rejects(sub { nested($l, $jobs[-1]) }, qr/depth exhausted/, 'ninth logical level rejects');
    rejects(sub { nested($l, $jobs[0]) }, qr/job capacity exhausted/, 'ninth job rejects even at shallow depth');
    settle($l, $jobs[-1]);
    is($l->usage->{children}, 14, 'exact declared closure releases its two child charges');
    rejects(sub { nested($l, $jobs[0]) }, qr/job capacity exhausted/, 'zero-resource outcome does not reopen job slot');
    $l->retire(pop @jobs);
    my $next = nested($l, $jobs[0]);
    is($l->describe($next)->{id}, 9, 'settled delivery reopens capacity with a fresh identity');

    my $d = ledger(); my $r = $d->root;
    my $external = $d->reserve_descriptors(112);
    is($d->usage->{charged_descriptors}, 128, 'root peak plus external reservations reaches inclusive descriptor bound');
    rejects(sub { $d->reserve_descriptors(1) }, qr/capacity exhausted/, 'one excess descriptor rejects before allocation');
    is(refaddr($d->descriptor_grants->[0]), refaddr($external), 'lost-return descriptor reservation is recoverable');
    my $forged = bless {}, ref($external);
    rejects(sub { $d->release_descriptors($forged, 0) }, qr/foreign, copied/, 'copied descriptor grant rejects');
    rejects(sub { $l->release_descriptors($external, 0) }, qr/foreign, copied/, 'descriptor grant cannot move to another owner');
    $d->descriptors_prepared($external, 111);
    is_deeply([@{$d->usage}{qw(descriptors reserved_descriptors charged_descriptors)}],
        [111, 16, 127], 'external effects are separate from job preparation credit');
    rejects(sub { $d->descriptors_prepared($external, 111) }, qr/already prepared/, 'external preparation cannot replay');
    rejects(sub { $d->release_descriptors($external, 112) }, qr/out of range/, 'external usage cannot grow without fresh credit');
    active($d, $r);
    rejects(sub { nested($d, $r) }, qr/descriptor capacity/, 'job admission includes external actual descriptors');
    $d->release_descriptors($external, 0);
    rejects(sub { $d->release_descriptors($external, 0) }, qr/retired descriptor/, 'released descriptor grant is stale');
    rejects(sub { $d->reserve_descriptors(0) }, qr/positive/, 'empty descriptor grant rejects');
    rejects(sub { $d->reserve_descriptors(129) }, qr/out of range/, 'single reservation beyond the bound rejects');
    my $cleanup = $d->reserve_descriptors(2);
    settle($d, $r);
    rejects(sub { $d->retire($r) }, qr/run descriptor/, 'run cannot retire while endpoint resources are charged');
    my $scratch = $d->reserve_descriptors(1);
    $d->release_descriptors($scratch, 0); $d->release_descriptors($cleanup, 0); $d->retire($r);
    is($d->usage->{charged_descriptors}, 0, 'bounded cleanup credit also retires exactly');
};

subtest 'identity exhaustion is final even after retirement' => sub {
    my $l = ledger(); my $r = $l->root; active($l, $r);
    $l->{next_id} = 4_294_967_295; # model seam; never a native PID or PGID
    my $last = nested($l, $r);
    is($l->describe($last)->{id}, 4_294_967_295, 'last u32 identity is usable');
    settle($l, $last); $l->retire($last);
    rejects(sub { nested($l, $r) }, qr/identity exhausted/, 'u32 exhaustion never wraps or reuses');
    is($l->usage->{jobs}, 1, 'exhaustion publishes no partial record or resource charge');
};

done_testing;

source_snapshots.t/1871-semantic-introspection-mcp-vial.t:
#!/usr/bin/env perl
use strict;
use warnings;
use Cwd qw(abs_path);
use FindBin;
use IPC::Cmd ();
use JSON::PP qw(decode_json encode_json);
use Test::More;
use lib "$FindBin::Bin/../perl";
use FSM::ProjectDataLocality qw(create_project_tempdir);
use FSM::Support::CapabilityManifest qw(build_capability_manifest);
use FSM::Support::SemanticIntrospectionMCPAdapter;
use FSM::VIAL::Tool qw(check_vial_source_file vial_tool_capabilities vial_tool_capabilities_v2);

my $root = abs_path("$FindBin::Bin/..");
my $workspace = create_project_tempdir(purpose => 'mcp-vial-query');
my $manifest = build_capability_manifest();
my $runner_calls = 0;
sub adapter {
    return FSM::Support::SemanticIntrospectionMCPAdapter->new(
        repo_root => $root, workspace_root => $_[0], manifest_builder => sub { $manifest },
        runner => sub { ++$runner_calls; die 'VIAL must not use hardware runner'; });
}
my $repo_adapter = adapter($root);
my $local = adapter($workspace);
sub request {
    my ($adapter, $method, $params) = @_;
    return $adapter->handle_jsonrpc_request({jsonrpc => '2.0', id => 1, method => $method, params => $params});
}
sub checked_tool {
    my ($adapter, $kind, $args, $expected) = @_;
    my $response = request($adapter, 'tools/call', {name => $kind eq 'check' ? 'fsmgen_check' : 'fsmgen_semantic_introspect', arguments => $args});
    ok(!$response->{error}, "$kind VIAL query returns an MCP result") or return;
    my $result = $response->{result};
    is_deeply(decode_json($result->{content}[0]{text}), $result->{structuredContent}, 'text and structured content agree');
    my $payload = $result->{structuredContent};
    is_deeply($payload->{report}, $expected, 'complete native VIAL report is preserved, including semantic paths');
    is($payload->{query_kind}, $kind, 'requested query kind remains explicit');
    is($result->{isError} ? 1 : 0, $expected->{success} ? 0 : 1, 'tool failure flag follows native public result');
    is($payload->{adapter_provenance}{api_entrypoint}, 'FSM::VIAL::Tool::check_vial_source_file', 'provenance names actual public producer');
    ok(!defined($payload->{adapter_provenance}{command_shape}), 'provenance does not invent hardware argv');
    is_deeply($payload->{report}{artifacts}, [], 'MCP check publishes no artifact');
    unlike(encode_json($payload), qr/\Q$root\E|\Q$workspace\E/, 'result contains no machine-local workspace root');
    return $payload;
}
sub write_source {
    my ($name, $text) = @_;
    open my $fh, '>:raw', "$workspace/$name" or die $!;
    print {$fh} $text; close $fh or die $!;
}
sub read_source {
    open my $fh, '<:raw', $_[0] or die $!;
    local $/; my $text = <$fh>; close $fh or die $!; return $text;
}

subtest 'VIAL capability and catalog discovery preserve native contracts' => sub {
    for my $version (1, 2) {
        my $expected = $version == 1 ? vial_tool_capabilities() : vial_tool_capabilities_v2();
        my $response = request($repo_adapter, 'tools/call', {name => 'fsmgen_capability_query', arguments => {section => "vial_tooling_v$version"}});
        ok(!$response->{error}, "v$version capabilities are queryable");
        is_deeply($response->{result}{structuredContent}{payload}, $expected, 'capability tool preserves native versioned record');
        $response = request($repo_adapter, 'resources/read', {uri => "fsmgen://vial/$version/capabilities"});
        ok(!$response->{error}, "v$version capability resource exists");
        is_deeply(decode_json($response->{result}{contents}[0]{text}), $expected, 'resource preserves complete native capability record') if $response->{result};
    }
    my @catalog = grep { ($_->{relpath} // '') =~ /\.vial\z/ } @{$manifest->{support_accounting}{catalog_entries}};
    my $discovery = $repo_adapter->call_tool('fsmgen_discover_sources', {file_kind => 'vial', limit => 100})->{structuredContent};
    ok(@catalog, 'native catalog contains VIAL sources');
    is($discovery->{matched_count}, scalar(@catalog), 'VIAL discovery derives full native catalog count');
    my @visible = @catalog; splice @visible, 100 if @visible > 100;
    is_deeply([map { [$_->{source_id}, $_->{support}{id}] } @{$discovery->{sources}}], [map { [$_->{relpath}, $_->{id}] } @visible], 'bounded discovery keeps catalog identities and order');
    is_deeply($manifest->{semantic_introspection}{source_query_kinds}{vial}, [qw(check semantic inspection)], 'native applicability includes separate inspection and excludes scheduling');
    my $tools = $repo_adapter->list_tools()->{tools};
    for my $tool (grep { $_->{name} =~ /\Afsmgen_(?:check|semantic_introspect)\z/ } @$tools) {
        is_deeply($tool->{inputSchema}{properties}{language_version}{enum}, [1, 2], 'tool declares explicit version choices');
    }
};

subtest 'actual native v1 v2 and lifecycle results match MCP tools and resources' => sub {
    for my $case ([1, 'vial/ahb_subordinate_base_output_arbitration.vial'],
                  [2, 'vial/ahb_subordinate_base_output_arbitration_v2.vial'],
                  [2, 'vial/ahb_subordinate_base_output_arbitration_lifecycle_v2.vial']) {
        my ($version, $source) = @$case;
        my ($ok, $error, $all, $stdout) = IPC::Cmd::run(command => ["$root/bin/fsmgen", 'vial', 'check', '--json', '--language-version', $version, $source]);
        ok($ok, "$source native query succeeds");
        my $expected = decode_json(join('', @{$stdout || []}));
        for my $kind (qw(check semantic)) {
            checked_tool($repo_adapter, $kind, {source_id => $source, language_version => $version}, $expected);
            my $uri = "fsmgen://vial/$version/source/$source/$kind";
            my $response = request($repo_adapter, 'resources/read', {uri => $uri});
            ok(!$response->{error}, 'versioned source resource succeeds');
            is_deeply(decode_json($response->{result}{contents}[0]{text})->{report}, $expected, 'resource preserves full native result') if $response->{result};
            if ($version == 1) {
                $response = request($repo_adapter, 'resources/read', {uri => "fsmgen://source/$source/$kind"});
                ok(!$response->{error}, 'unversioned VIAL resource defaults to v1');
                is_deeply(decode_json($response->{result}{contents}[0]{text})->{report}, $expected, 'default result is native v1') if $response->{result};
            }
        }
    }
    my $v2 = 'vial/ahb_subordinate_base_output_arbitration_lifecycle_v2.vial';
    my $default = check_vial_source_file({workspace_root => $root, source_id => $v2});
    ok(!$default->{success}, 'native default does not infer v2 from the filename');
    checked_tool($repo_adapter, 'semantic', {source_id => $v2}, $default);
    my $encoded = $v2; $encoded =~ s{/}{%2F}g;
    my $response = request($repo_adapter, 'resources/read', {uri => "fsmgen://vial/2/source/$encoded/check"});
    ok(!$response->{error}, 'versioned resource accepts percent-encoded source separators');
    is_deeply(decode_json($response->{result}{contents}[0]{text})->{report},
        check_vial_source_file({workspace_root => $root, source_id => $v2, language_version => 2}),
        'encoded resource retains the same full public result') if $response->{result};
};

subtest 'imported invalid and unsafe inputs preserve public refusal and path authority' => sub {
    for my $version (1, 2) {
        my $source = read_source("$root/vial/ahb_subordinate_base_output_arbitration" . ($version == 2 ? '_v2' : '') . '.vial');
        my $import = $source; $import =~ s/package ahb_subordinate_base_output_arbitration/package imported/ or die 'package marker absent';
        $source =~ s/\(imports\)/(imports (import shared "part.vial"))/ or die 'imports marker absent';
        write_source('root.vial', $source); write_source('part.vial', $import);
        my $expected = check_vial_source_file({workspace_root => $workspace, source_id => 'root.vial', language_version => $version});
        ok($expected->{success}, 'independent filesystem facade accepts imported source');
        checked_tool($local, 'semantic', {source_path => "$workspace/root.vial", language_version => $version}, $expected);
        is(read_source("$workspace/root.vial"), $source, 'root source is unchanged');
        is(read_source("$workspace/part.vial"), $import, 'imported source is unchanged');
        write_source('invalid.vial', '(');
        write_source('oversize.vial', ' ' x (vial_tool_capabilities()->{limits}{source_bytes} + 1));
        for my $id (qw(invalid.vial oversize.vial missing.vial linked.vial)) {
            if ($id eq 'linked.vial' && !-l "$workspace/$id") { symlink "$workspace/root.vial", "$workspace/$id" or die $!; }
            $expected = check_vial_source_file({workspace_root => $workspace, source_id => $id, language_version => $version});
            ok(!$expected->{success}, 'native input is refused');
            checked_tool($local, 'check', {source_id => $id, language_version => $version}, $expected);
        }
    }
    symlink $workspace, "$workspace/aliased" or die $!;
    for my $id ('aliased/root.vial', '../outside.vial') {
        my $expected = check_vial_source_file({workspace_root => $workspace, source_id => $id, language_version => 2});
        ok(!$expected->{success}, 'public facade rejects directory symlink or workspace escape');
        checked_tool($local, 'semantic', {source_id => $id, language_version => 2}, $expected);
    }
    my $linked_import = read_source("$workspace/root.vial");
    $linked_import =~ s/"part.vial"/"linked.vial"/ or die 'import marker absent';
    write_source('root.vial', $linked_import);
    my $expected = check_vial_source_file({workspace_root => $workspace, source_id => 'root.vial', language_version => 2});
    ok(!$expected->{success}, 'symlink import is unavailable to the public source catalog');
    checked_tool($local, 'semantic', {source_id => 'root.vial', language_version => 2}, $expected);
    opendir my $dir, $workspace or die $!;
    is_deeply([sort grep { $_ ne '.' && $_ ne '..' } readdir $dir], [sort qw(root.vial part.vial invalid.vial oversize.vial linked.vial aliased)], 'MCP creates no workspace artifact');
    closedir $dir or die $!;
};

subtest 'version selection is closed and never widens query authority' => sub {
    for my $args ({source_id => 'vial/x.vial', language_version => 3},
                  {source_id => 'vial/x.vial', language_version => JSON::PP::true},
                  {source_id => 'vial/x.vial', language_version => undef},
                  {source_id => 'fsm/ahb_lite_subordinate.fsm', language_version => 1},
                  {source_id => 'vial/x.vial', action => 'run'}, {source_id => []}) {
        my $response = request($repo_adapter, 'tools/call', {name => 'fsmgen_check', arguments => $args});
        is($response->{error}{code}, -32602, 'invalid selector/shape/action is invalid params before producer execution');
    }
    for my $uri ('fsmgen://vial/3/capabilities', 'fsmgen://vial/0/source/x.vial/check',
