    for my $case ([1,'vial/ahb_subordinate_base_output_arbitration.vial'],[2,'vial/ahb_subordinate_base_output_arbitration_v2.vial'],[2,'vial/ahb_subordinate_base_output_arbitration_lifecycle_v2.vial']) {
