        for my $query (['check',[qw(--strict --check --json)],'fsmgen_check'],
                       ['semantic',[qw(--strict --emit-semantic-json)],'fsmgen_semantic_introspect'],
                       ['schedule',['--emit-schedule-json'],'fsmgen_schedule_preview']) {
            my ($kind,$flags,$tool)=@$query;
