  my $scheduler=FSM::Scheduler::ISF->new;
  my $ir=$scheduler->{ir}->build_module($actor);
  my $child=$ir->{children}{worker};
  is_deeply($child->{actor_storage_reads},[],'local name does not request an actor storage read');
  is_deeply($child->{actor_storage_writes},[],'local output does not request an actor storage write');
  is_deeply($child->{declared_storage},[],'child does not copy actor storage');
  is($child->{signal_widths}{$signal},4,'local width wins over actor width');
  is($child->{storage_roles}{$signal},'transaction_port','local port role survives cleanup');
  is($child->{signal_type_refs}{$signal},$name =~ /^typed_/ ? 'local_t' : undef,'local type is independent of actor type');
  ok(!exists($child->{reset_values}{$signal}),'actor reset does not leak into the local port');
  my ($port)=grep {$_->{name} eq $signal} @{$child->{ports}};
  is($port->{direction},$output ? 'output' : 'input','local direction is retained');
  my $files=$scheduler->lower($actor)->{files};
  for my $file (sort keys %$files) {
   my $path=write_file("$dir/$file",$files->{$file});
   my $result=$capture->([$^X,'bin/fsmgen','--strict','--check','--json',$path],'');
   is($result->{exit_code},0,"$file strict replay") or diag($result->{stdout},$result->{stderr});
  }
  my $relative=File::Spec->abs2rel($source,$root);
  for my $query (['check',[qw(--strict --check --json)],'fsmgen_check'],
                 ['semantic',[qw(--strict --emit-semantic-json)],'fsmgen_semantic_introspect'],
                 ['schedule',['--emit-schedule-json'],'fsmgen_schedule_preview']) {
   my ($kind,$flags,$tool)=@$query;
   my $native=$capture->([$^X,'bin/fsmgen',@$flags,$relative],'');
   is($native->{exit_code},0,"native $kind succeeds") or diag($native->{stdout},$native->{stderr});
   my $report=FSM::Test::SourceQueryRunner::normalize_repository_paths($json->decode($native->{stdout}),$root);
   my $request={jsonrpc=>'2.0',id=>1,method=>'tools/call',params=>{name=>$tool,arguments=>{source_id=>$relative}}};
   my $response=$api->handle_jsonrpc_request($request);
   is_deeply($response->{result}{structuredContent}{report},$report,"complete native/API $kind parity");
   my $wire=$capture->([$^X,'bin/fsmgen-mcp','--workspace-root','.'],$json->encode($request)."\n");
   is_deeply($json->decode($wire->{stdout}),$response,"complete newline/API $kind parity") or diag($wire->{stdout},$wire->{stderr});
   if ($kind eq 'semantic') {
    is_deeply([sort map {$_->{name}} @{$report->{semantic}{signal_analysis}{inputs}}],
     [sort qw(clk rst_n start data owner_we owner_data),($domain ? qw(aux_clk aux_rst) : ())],'exact public inputs');
    is_deeply([sort map {$_->{name}} @{$report->{semantic}{signal_analysis}{outputs}}],
     [qw(child_seen done owner_seen)],'exact public outputs');
   }
  }
  my $owner_clock=$domain ? 'aux_clk' : 'clk';
  my $extra=$domain ? 'logic aux_clk=0,aux_rst=0;always #7 aux_clk=~aux_clk;' : '';
  my $initial_reset=$domain ? 'aux_rst=1;' : '';
  my $release_reset=$domain ? 'aux_rst=0;' : '';
  my $independent_reset=$domain ? <<'SV' : '';
  aux_rst=1;#1;if(child_seen!==13) $fatal(1,"owner reset changed local child output");
  aux_rst=0;repeat(2) @(negedge aux_clk);
  if(owner_seen!==19) $fatal(1,"owner reset value lost");
  write_owner(91);
SV
  my $owner_after_core_reset=$domain ? 91 : $owner_reset;
  my $activate_data=$trigger ? 'data=payload' : 'data=3';
  my $later_data=$trigger ? 'data=3' : 'data=payload';
  # Generated call outputs are completion-qualified buses. All exercised payloads
  # are nonzero; observe their valid window instead of requiring an idle hold.
  my $result_check=($generated_do || $trigger) ? 'seen_payload' : '(child_seen===payload)';
  my $hdl=FSM::Pipeline::HDLGenerator->new(quiet=>1)->generate_hdl_from_file($source)->{hdl_code};
  simulate($dir,$hdl,<<"SV");
module tb;
 logic clk=0,rst_n=1,start=0,owner_we=0;
 logic [3:0] data=0;logic [7:0] owner_data=0;
 wire [3:0] child_seen;wire [7:0] owner_seen;wire done;
 $extra
 always #5 clk=~clk;
 child_shadow_top dut(.*);
 task write_owner(input integer value);
  @(negedge $owner_clock);owner_we=1;owner_data=value;
  @(negedge $owner_clock);owner_we=0;
  repeat(2) @(negedge $owner_clock);
  if(owner_seen!==value) \$fatal(1,"actor register update lost");
 endtask
 task activate(input integer payload);
  integer pulses;bit seen_payload;
  pulses=0;seen_payload=0;
  @(negedge clk);$activate_data;start=1;
  @(negedge clk);start=0;$later_data;
  for(integer cycle=0;cycle<18;cycle++) begin
   @(posedge clk);#1;if(done) pulses++;
   if(child_seen===payload) seen_payload=1;
   @(negedge clk);
  end
  if(pulses!=1 || !($result_check)) \$fatal(1,"local payload/completion lost: payload=%d seen=%d pulses=%d",payload,child_seen,pulses);
 endtask
 initial begin
  #2;rst_n=0;$initial_reset
  #20;rst_n=1;$release_reset
  repeat(3) @(negedge $owner_clock);
  if(child_seen!==0 || owner_seen!==$owner_reset) \$fatal(1,"local/actor reset identities merged");
  write_owner(53);activate(7);
  if(owner_seen!==53) \$fatal(1,"local child write changed actor storage");
  write_owner(91);activate(13);
  if(owner_seen!==91) \$fatal(1,"repeated local call changed actor storage");
  $independent_reset
  rst_n=0;#1;if(child_seen!==0) \$fatal(1,"local reset lost");
  rst_n=1;repeat(3) @(negedge $owner_clock);
  if(owner_seen!==$owner_after_core_reset) \$fatal(1,"core reset changed wrong owner");
  activate(5);
  \$display("CHILD_SHADOW_PASS");\$finish;
 end
 initial begin #10000;\$fatal(1,"shadowing timeout");end
endmodule
SV
 };
}
done_testing();
sub simulate {
 my ($dir,$hdl,$tb)=@_;
 SKIP: {
  skip 'qualified Verilator runtime unavailable',3 unless can_run('verilator') && darwin_verilator_runtime_qualified();
  my $sv=write_file("$dir/dut.sv",$hdl);my $test=write_file("$dir/tb.sv",$tb);my $obj="$dir/obj";
  my $compile=run_verilator_compile(['verilator','--binary','--timing','--assert','-Wno-fatal','--top-module','tb','--Mdir',$obj,$sv,$test]);
  ok($compile->{ok},'independent child shadowing HDL compiles') or diag($compile->{diagnostic},$compile->{stderr});
  if (!$compile->{ok}) {fail('runtime compilation failed');fail('runtime observations absent');}
  else {my $run=run_generated_binary(["$obj/Vtb"]);
   ok($run->{ok},'local payload and actor register remain independent') or diag($run->{diagnostic},$run->{stdout},$run->{stderr});
   like($run->{stdout},qr/CHILD_SHADOW_PASS/,'runtime observations complete');}
 }
}
sub write_file {my ($path,$text)=@_;open my $fh,'>',$path or die $!;print {$fh} $text;close $fh or die $!;return $path;}

source_snapshots.t/1922-isf-terminal-synchronization.t:
#!/usr/bin/env perl
use strict;
use warnings;
use Test::More;
use Cwd qw(abs_path);
use File::Spec;
use File::Temp qw(tempdir);
use IPC::Cmd qw(can_run);
use JSON::PP ();
use lib 'perl', 't/lib';
use FSM::Test::ProjectDataLocality;
use FSM::Test::SourceQueryRunner;
use FSM::Test::VerilatorRuntime qw(darwin_verilator_runtime_qualified run_verilator_compile run_generated_binary);
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Pipeline::HDLGenerator;
use FSM::Support::SemanticIntrospectionMCPAdapter;

my $workspace = tempdir(CLEANUP => 1);
my $root = abs_path('.');
my $capture = \&FSM::Test::SourceQueryRunner::_capture;
my $json = JSON::PP->new->canonical;
my $api = FSM::Support::SemanticIntrospectionMCPAdapter->new(repo_root => $root, workspace_root => $root);

for my $kind (qw(all any)) {
    for my $pending (0, 1, 2) {
        subtest "$kind with $pending pending children" => sub {
            my $dir = "$workspace/${kind}_$pending";
            mkdir $dir or die $!;
            my $worker = $pending ? '(transaction worker (wait 3) (complete done))' : '';
            my $spawns = join ' ', map { "(spawn worker as w$_)" } 0 .. $pending - 1;
            my $source = write_file("$dir/source.isf", <<"ISF");
(actor terminal_sync
 (clock clk) (reset (rst_n async active_low))
 (interface (input start) (output marker (width 8) (reset 0)))
 (storage (var activations (width 8) (reset 0)))
 (rule observe 1 (marker activations))
 $worker
 (transaction main (on start) (set activations (+ activations 1))
  $spawns (await_$kind done)))
ISF
            my $actor = FSM::Adapter::ISF->new->parse_file($source);
            my $scheduler = FSM::Scheduler::ISF->new;
            my $ir = $scheduler->{ir}->build_module($actor);
            my ($join) = grep { $_->{kind} eq "sync_$kind" } @{$ir->{states}};
            is_deeply($join->{transitions}, [{target => $join->{name}}],
                'terminal synchronization has an explicit hold continuation');
            is_deeply($join->{done_ports}, [map { "w${_}_done" } 0 .. $pending - 1],
                'authored pending-set metadata is retained');
            my @warnings;
            my $lowered;
            { local $SIG{__WARN__} = sub { push @warnings, @_ };
              $lowered = $scheduler->lower($actor); }
            is_deeply(\@warnings, [], 'lowering emits no missing-target warning');
            for my $file (sort keys %{$lowered->{files}}) {
                my $path = write_file("$dir/$file", $lowered->{files}{$file});
                my $result = $capture->([$^X, 'bin/fsmgen', '--strict', '--check', '--json', $path], '');
                is($result->{exit_code}, 0, "$file strict replay")
                    or diag($result->{stdout}, $result->{stderr});
                is($result->{stderr}, '', "$file replay has clean stderr");
            }
            qualify_reports($source, $pending);
            my $hdl = FSM::Pipeline::HDLGenerator->new(quiet => 1)
                ->generate_hdl_from_file("$dir/terminal_sync.fsm")->{hdl_code};
            simulate($dir, $hdl, $pending);
        };
    }
}

done_testing();

sub qualify_reports {
    my ($source, $pending) = @_;
    my $relative = File::Spec->abs2rel($source, $root);
    for my $query (
        ['check', [qw(--strict --check --json)], 'fsmgen_check'],
        ['semantic', [qw(--strict --emit-semantic-json)], 'fsmgen_semantic_introspect'],
        ['schedule', ['--emit-schedule-json'], 'fsmgen_schedule_preview'],
    ) {
        my ($kind, $flags, $tool) = @$query;
        my $native = $capture->([$^X, 'bin/fsmgen', @$flags, $relative], '');
        is($native->{exit_code}, 0, "native $kind succeeds")
            or diag($native->{stdout}, $native->{stderr});
        is($native->{stderr}, '', "native $kind has clean stderr");
        my $report = FSM::Test::SourceQueryRunner::normalize_repository_paths(
            $json->decode($native->{stdout}), $root);
        my $request = {jsonrpc => '2.0', id => 1, method => 'tools/call',
            params => {name => $tool, arguments => {source_id => $relative}}};
        my $response = $api->handle_jsonrpc_request($request);
        is_deeply($response->{result}{structuredContent}{report}, $report,
            "complete native/API $kind parity");
        my $wire = $capture->([$^X, 'bin/fsmgen-mcp', '--workspace-root', '.'],
            $json->encode($request) . "\n");
        is($wire->{exit_code}, 0, "newline $kind exits successfully");
        is($wire->{stderr}, '', "newline $kind has clean stderr");
        is_deeply($json->decode($wire->{stdout}), $response,
            "complete newline/API $kind parity") or diag($wire->{stdout}, $wire->{stderr});
        if ($kind eq 'semantic') {
            is_deeply([sort map { $_->{name} } @{$report->{semantic}{signal_analysis}{inputs}}],
                $pending ? [qw(clk rst_n start)] : ['start'], 'exact public data inputs');
            is_deeply([sort map { $_->{name} } @{$report->{semantic}{signal_analysis}{outputs}}],
                ['marker'], 'exact public outputs');
            if (!$pending) {
                is_deeply($report->{semantic}{explicit_system_contract},
                    {clock => 'clk', reset => 'rst_n', reset_active_level => 0,
                     reset_keyword => 'areset', reset_kind => 'async'},
                    'standalone clock/reset remain in the separate system contract');
            }
        }
    }
}

sub simulate {
    my ($dir, $hdl, $pending) = @_;
    SKIP: {
        skip 'qualified Verilator runtime unavailable', 3
            unless can_run('verilator') && darwin_verilator_runtime_qualified();
        my $ports = join "\n", map { "logic w${_}_done=0; wire w${_}_start; int starts_$_=0;" } 0 .. $pending - 1;
        my $count = join "\n", map { "if(!rst_n) starts_$_=0; else if(w${_}_start) starts_$_++;" } 0 .. $pending - 1;
        my $check = join "\n", map { "if(starts_$_!=1) \$fatal(1,\"unexpected child $_ activation count: %0d\",starts_$_);" } 0 .. $pending - 1;
        my $pulses = join "\n", map {
            "@(negedge clk); w${_}_done=1; tick; @(negedge clk); w${_}_done=0; repeat(7) tick;"
        } 0 .. $pending - 1;
        my $tb = <<"SV";
module tb;
 logic clk=0, rst_n=1, start=0;
 wire [7:0] marker;
 $ports
 always #5 clk=~clk;
 terminal_sync dut(.*);
 always @(posedge clk) begin $count end
 task tick; @(posedge clk); #1; endtask
 task activation;
  @(negedge clk); start=1;
  @(negedge clk); start=0;
  repeat(8) tick;
  if(marker!==8'd1) \$fatal(1,"activation did not enter exactly once");
  $check
  // Non-overlapping external completion pulses exercise the parent's public
  // handoff contract; no completion may invent a return-to-entry edge.
  $pulses
  repeat(8) tick;
  @(negedge clk); start=1;
  repeat(5) tick;
  @(negedge clk); start=0;
  repeat(8) tick;
  if(marker!==8'd1) \$fatal(1,"terminal synchronization unexpectedly rearmed");
  $check
 endtask
 initial begin
  #2; rst_n=0; #10; rst_n=1;
  activation;
  @(negedge clk); rst_n=0; repeat(3) tick;
  if(marker!==0) \$fatal(1,"reset did not restore owner output");
  @(negedge clk); rst_n=1;
  activation;
  \$display("TERMINAL_SYNC_HOLD_PASS"); \$finish;
 end
 initial begin #10000; \$fatal(1,"test timeout"); end
endmodule
SV
        my $sv = write_file("$dir/dut.sv", $hdl);
        my $test = write_file("$dir/tb.sv", $tb);
        my $obj = "$dir/obj";
        my $compile = run_verilator_compile(['verilator', '--binary', '--timing', '--assert', '-Wno-fatal',
            '--top-module', 'tb', '--Mdir', $obj, $sv, $test]);
        ok($compile->{ok}, 'independent compiler accepts terminal synchronization')
            or diag($compile->{diagnostic}, $compile->{stderr});
        if (!$compile->{ok}) { fail('runtime compile failed'); fail('runtime observation absent'); }
        else {
            my $run = run_generated_binary(["$obj/Vtb"]);
            ok($run->{ok}, 'terminal hold and reset reactivation pass')
                or diag($run->{diagnostic}, $run->{stdout}, $run->{stderr});
            like($run->{stdout}, qr/TERMINAL_SYNC_HOLD_PASS/, 'all terminal observations completed');
        }
    }
}

sub write_file {
    my ($path, $text) = @_;
    open my $fh, '>', $path or die "open $path: $!";
    print {$fh} $text;
    close $fh or die "close $path: $!";
    return $path;
}

source_snapshots.t/1929-isf-wait-carrier-grammar.t:
#!/usr/bin/env perl
use strict;
use warnings;
use Test::More;
use Cwd qw(abs_path);
use File::Spec;
use File::Temp qw(tempdir);
use JSON::PP;
use lib 'perl', 't/lib';
use FSM::Test::ProjectDataLocality;
use FSM::Test::SourceQueryRunner;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Support::SemanticIntrospectionMCPAdapter;

my $work = tempdir(CLEANUP => 1);
my $root = abs_path('.');
my $json = JSON::PP->new->canonical;
my $api = FSM::Support::SemanticIntrospectionMCPAdapter->new(repo_root => $root, workspace_root => $root);
my $capture = \&FSM::Test::SourceQueryRunner::_capture;
my $ordinal = 0;

for my $expr ('(~ cycles)', '(&& cycles bias)', '(|| cycles bias)', '(concat cycles)',
    '(+ cycles (~ bias))', '(+ cycles (concat bias))') {
    subtest "unsupported count $expr" => sub {
        my $source = source($expr);
        my $actor = FSM::Adapter::ISF->new->parse_source($source, 'wait_grammar.isf');
        eval {FSM::Scheduler::ISF->new->lower($actor)};
        like($@, qr/runtime dynamic wait count expression .*must use a supported expression operator shape/,
            'wait validation rejects before emitting an invalid carrier');
        qualify_reports(write_file("$work/bad_" . $ordinal++ . '.isf', $source), 0);
    };
}

for my $expr ('(! cycles)', map {"($_ cycles bias)"} qw(+ - * / % & | ^ == != < <= > >= << >> concat)) {
    subtest "supported count $expr" => sub {
        my $source = source($expr);
        my $actor = FSM::Adapter::ISF->new->parse_source($source, 'wait_grammar.isf');
        my $scheduler = FSM::Scheduler::ISF->new;
        my $files = $scheduler->lower($actor)->{files};
        my $report = $json->decode($scheduler->report($actor));
        is($report->{transaction_waits}[0]{count_source}, $expr, 'authored count expression unchanged');
        is($report->{transaction_waits}[0]{count_kind}, 'runtime_expression', 'count remains a runtime snapshot');
        my $path = write_file("$work/good_" . $ordinal++ . '.fsm', $files->{'wait_grammar.fsm'});
        my $check = $capture->([$^X, 'bin/fsmgen', '--strict', '--check', '--json', $path], '');
        is($check->{exit_code}, 0, 'scheduled carrier passes strict public replay') or diag($check->{stdout}, $check->{stderr});
        qualify_reports(write_file("$work/control.isf", $source), 1) if $expr eq '(+ cycles bias)';
    };
}
done_testing;

sub source {
    my ($expr) = @_;
    return "(actor wait_grammar (clock clk) (reset (rst_n async active_low)) "
        . "(interface (input start) (input cycles (width 4)) (input bias (width 4)) (output done)) "
        . "(transaction main (on start) (wait $expr) (complete done)))\n";
}

sub write_file {
    my ($path, $text) = @_;
    open my $fh, '>', $path or die $!;print $fh $text;close $fh;
    return $path;
}

sub qualify_reports {
    my ($path, $success) = @_;
    my $relative = File::Spec->abs2rel($path, $root);
    for my $query (
        ['check', [qw(--strict --check --json)], 'fsmgen_check'],
        ['semantic', [qw(--strict --emit-semantic-json)], 'fsmgen_semantic_introspect'],
        ['schedule', ['--emit-schedule-json'], 'fsmgen_schedule_preview'],
    ) {
        my ($kind, $flags, $tool) = @$query;
        my $native = $capture->([$^X, 'bin/fsmgen', @$flags, $relative], '');
        if ($kind eq 'schedule' && !$success) {
            # Only check/semantic have public failure-report schemas. Schedule
            # refusals retain the documented message-only adapter boundary.
            isnt($native->{exit_code}, 0, 'native schedule rejects the unsupported wait');
            is($native->{stdout}, '', 'failed schedule emits no success report');
            like($native->{stderr}, qr/must use a supported expression operator shape/, 'native schedule locates wait refusal');
            my $request = {jsonrpc => '2.0', id => 1, method => 'tools/call',
                params => {name => $tool, arguments => {source_id => $relative}}};
            my $response = $api->handle_jsonrpc_request($request);
            is($response->{error}{code}, -32000, 'failed schedule uses adapter error contract');
            ok(!exists($response->{error}{data}), 'schedule error remains message-only');
            like($response->{error}{message}, qr/failed without a matching public failure report/, 'schedule failure cannot masquerade as a successful preview');
            my $wire = $capture->([$^X, 'bin/fsmgen-mcp', '--workspace-root', '.'], $json->encode($request) . "\n");
            is($wire->{exit_code}, 0, 'schedule refusal does not break newline protocol');
            is_deeply($json->decode($wire->{stdout}), $response, 'complete newline/API schedule refusal parity');
            next;
        }
        is($native->{exit_code}, $success ? 0 : 1, "native $kind exit agrees with source admission");
        my $report = eval {$json->decode($native->{stdout})};
        ok($report, "native $kind returns structured report") or diag($native->{stdout}, $native->{stderr}, $@);
        next unless $report;
        $report = FSM::Test::SourceQueryRunner::normalize_repository_paths($report, $root);
        if (!$success) {
            like($json->encode($report), qr/must use a supported expression operator shape/, "$kind locates wait grammar refusal");
            unlike($json->encode($report), qr/Error parsing FSM with adapter/, "$kind fails before carrier parsing");
        }
        my $request = {jsonrpc => '2.0', id => 1, method => 'tools/call',
            params => {name => $tool, arguments => {source_id => $relative}}};
        my $response = $api->handle_jsonrpc_request($request);
        is_deeply($response->{result}{structuredContent}{report}, $report, "complete native/API $kind parity");
        is($response->{result}{isError} ? 1 : 0, $success ? 0 : 1, "API $kind exposes admission status");
        my $wire = $capture->([$^X, 'bin/fsmgen-mcp', '--workspace-root', '.'], $json->encode($request) . "\n");
        is($wire->{exit_code}, 0, "newline $kind protocol exits successfully");
        is_deeply($json->decode($wire->{stdout}), $response, "complete newline/API $kind parity");
    }
}

source_snapshots.t/1933-isf-caller-formal-binding-scope.t:
#!/usr/bin/env perl
use strict;
use warnings;
use Test::More;
use Storable qw(dclone);
use Cwd qw(abs_path);
use File::Temp qw(tempdir);
use File::Spec;
use JSON::PP;
use lib 'perl', 't/lib';
use FSM::Test::ProjectDataLocality;
use FSM::Test::SourceQueryRunner;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Scheduler::ISF::LoweringIR;
use FSM::Support::SemanticIntrospectionMCPAdapter;

my $lowerer = FSM::Scheduler::ISF::LoweringIR->new;
my $json = JSON::PP->new->canonical;
my $root = abs_path('.');
my $work = tempdir(CLEANUP => 1);
my $capture = \&FSM::Test::SourceQueryRunner::_capture;

sub source {
    my (%args) = @_;
    my $actor_decl = $args{actor_kind} eq 'storage'
        ? '(storage (var value (width 8) (reset 19)))'
        : '';
    my $actor_port = $args{actor_kind} =~ /\A(?:input|output)\z/
        ? "($args{actor_kind} value (width 8))" : '';
    my $formal = $args{formal} // '(ports (input value (width 4)))';
    my $callee = $args{callee} // '(ports (input payload (width 4)))';
    my $body = $args{body} // '(do worker (bind (input payload value)))';
    return "(actor binding_scope (clock clk) (reset (rst_n async active_low))\n"
        . "(interface (input start) (input observed (width 4)) (output done) $actor_port)\n"
        . "$actor_decl (transaction caller $formal (on start) $body (complete done))\n"
        . "(transaction worker $callee (on worker_start) (complete worker_done)))\n";
}

sub parse {
    return FSM::Adapter::ISF->new->parse_source($_[0], 'binding_scope.isf');
}
sub admission {
    my ($actor) = @_;
    my $ok = eval {$lowerer->_validate_transaction_port_bindings($actor); 1};
    return ($ok, $@);
}
sub rejects {
    my ($actor, $pattern, $label) = @_;
    my ($ok, $error) = admission($actor);
    ok(!$ok, "$label rejected");
    like($error, $pattern, "$label diagnostic");
}

for my $actor_kind (qw(input output storage)) {
    for my $formal_kind (qw(input output)) {
        subtest "$formal_kind caller formal shadows actor $actor_kind" => sub {
            for my $actual ('value', '(+ value observed)') {
                my $actor = parse(source(actor_kind => $actor_kind,
                    formal => "(ports ($formal_kind value (width 4)))",
                    body => "(do worker (bind (input payload $actual)))"));
                my $before = dclone($actor);
                my ($ok, $error) = admission($actor);
                ok($ok, "$actual reads caller width and role") or diag($error);
                is_deeply($actor, $before, 'validation preserves source declarations');
                my ($worker) = grep {$_->{name} eq 'worker'} @{$actor->{transactions}};
                $worker->{ports}{inputs}[0]{width} = 8;
                rejects($actor, qr/width (?:8 does not match actor signal 'value' width 4|4 does not match transaction port width 8)/,
                    "$actual does not borrow wider actor width");
            }
            my $actor = parse(source(actor_kind => $actor_kind,
                formal => "(ports ($formal_kind value (width 4)))",
                callee => '(ports (output result (width 4)))',
                body => '(do worker (bind (output result value)))'));
            my ($ok, $error) = admission($actor);
            ok($ok, 'output actual targets the caller variable') or diag($error);
            my ($worker) = grep {$_->{name} eq 'worker'} @{$actor->{transactions}};
            $worker->{ports}{outputs}[0]{width} = 8;
            rejects($actor, qr/width 8 does not match actor signal 'value' width 4/,
                'output actual keeps caller width');
        };
    }
}

subtest 'actor restrictions and sibling scope are preserved' => sub {
    my $input = parse(source(actor_kind => 'input', formal => '',
        callee => '(ports (output result (width 8)))',
        body => '(do worker (bind (output result value)))'));
    rejects($input, qr/targets actor input 'value'.*read-only/, 'actor input write');
    my $output = parse(source(actor_kind => 'output', formal => '',
        callee => '(ports (input payload (width 8)))'));
    rejects($output, qr/reads actor output 'value'.*readback/, 'actor output read');
    my $unknown = parse(source(actor_kind => 'none', formal => '',
        callee => '(ports (input value (width 4)))',
        body => '(do worker (bind (input value value)))'));
    rejects($unknown, qr/unknown actor signal 'value'/, 'callee formal is not caller variable');
    my $rule = parse(source(actor_kind => 'output'));
    $rule->{transactions}[0]{clauses} = [];
    $rule->{rules} = [{name => 'dispatch', actions => [['trigger', 'worker', ['bind', ['input', 'payload', 'value']]]]}];
    rejects($rule, qr/Rule 'dispatch'.*reads actor output 'value'/, 'rule never borrows transaction formal');
};

subtest 'callee contract and live-site pruning are unchanged' => sub {
    for my $case (
        ['(do worker (bind (output payload value)))', qr/uses role 'output'.*declares 'input'/, 'wrong direction'],
        ['(do worker (bind (input missing value)))', qr/unknown transaction port 'missing'/, 'unknown callee port'],
        ['(do worker)', qr/requires '\(bind/, 'missing binding'],
        ['(do worker (bind (input payload value) (input payload value)))', qr/duplicate binding/, 'duplicate binding'],
        ['(do worker (bind (input payload value (timing live))))', qr/requested timing 'live'.*activation_region/, 'wrong timing'],
    ) {
        rejects(parse(source(actor_kind => 'storage', body => $case->[0])), $case->[1], $case->[2]);
    }
    my ($ok, $error) = admission(parse(source(actor_kind => 'storage',
        body => '(repeat 0 (do worker (bind (input missing nonexistent))))')));
    ok($ok, 'static-zero binding endpoints stay pruned') or diag($error);
    rejects(parse(source(actor_kind => 'storage',
        body => '(repeat 1 (do worker (bind (input missing nonexistent))))')),
        qr/unknown transaction port 'missing'/, 'live repeat checks endpoints');
};

subtest 'physical storage and caller formal remain separate' => sub {
    my $actor = parse(source(actor_kind => 'storage'));
    my $ok = eval {FSM::Scheduler::ISF->new->lower($actor); 1};
    ok($ok, 'production accepts independent caller formal storage') or diag($@);
    is($@, '', 'actor storage no longer creates a physical merge conflict');
};

subtest 'direct actor-pin shadows emit separate private storage' => sub {
    for my $kind (qw(input output)) {
        for my $width (4, 8) {
            for my $role (qw(input output)) {
                my $text = source(actor_kind => $kind,
                    callee => "(ports ($role payload (width 4)))",
                    body => "(do worker (bind ($role payload value)))");
                $text =~ s/\($kind value \(width 8\)\)/($kind value (width $width))/;
                my $actor = parse($text);
                my $lowered = FSM::Scheduler::ISF->new->lower($actor);
                my $fsm = $lowered->{files}{'binding_scope.fsm'};
                like($fsm, qr/\(isf_port_caller_value\w* 4\)/,
                    "$kind width $width $role binding uses private caller storage");
                like($fsm, qr/\(value $width\)/, 'actor pin keeps its original width');
                my $file = write_file("$work/alias_${kind}_${width}_${role}.isf", $text);
                my $check = $capture->([$^X, 'bin/fsmgen', '--strict', '--check', '--json', $file], '');
                is($check->{exit_code}, 0, 'native strict check admits separated identities')
                    or diag($check->{stdout}, $check->{stderr});
            }
        }
    }
};

subtest 'generated interfaces and zero-pruned targets keep their separate paths' => sub {
    for my $case (
        ['generated', '(spawn worker as w0 (bind (input value observed))) (await_all done)'],
        ['pruned', '(repeat 0 (do worker (bind (input value observed))))'],
    ) {
        my ($name, $body) = @$case;
        my $text = source(actor_kind => 'input', formal => '',
            callee => '(ports (input value (width 4)))', body => $body);
        $text =~ s/\(input value \(width 8\)\)/(input value (width 4))/;
        my $actor = parse($text);
        my $lowered = FSM::Scheduler::ISF->new->lower($actor);
        ok($lowered, "$name target avoids direct merge gate");
        if ($name eq 'generated') {
            like($lowered->{files}{'worker.fsm'}, qr/\(value 4\)/, 'generated public formal keeps its name and width');
        } else {
            unlike($lowered->{files}{'binding_scope.fsm'}, qr/worker_idle/, 'zero-pruned target has no physical states');
        }
        my $file = write_file("$work/$name.isf", $text);
        my $check = $capture->([$^X, 'bin/fsmgen', '--strict', '--check', '--json', $file], '');
        is($check->{exit_code}, 0, "$name source strict-checks") or diag($check->{stdout}, $check->{stderr});
    }
};

subtest 'unshadowed source, carriers and complete public reports' => sub {
    my $text = source(actor_kind => 'none',
        body => '(sample observed as value) (do worker (bind (input payload value (timing snapshot))))');
    my $actor = parse($text);
    my $lowered = FSM::Scheduler::ISF->new->lower($actor);
    for my $name (sort keys %{$lowered->{files}}) {
        next unless $name =~ /\.fsm\z/;
        my $file = write_file("$work/$name", $lowered->{files}{$name});
        my $result = $capture->([$^X, 'bin/fsmgen', '--strict', '--check', '--json', $file], '');
        is($result->{exit_code}, 0, "$name strict carrier replay") or diag($result->{stdout}, $result->{stderr});
    }
    my $file = write_file("$work/binding_scope.isf", $text);
    my $relative = File::Spec->abs2rel($file, $root);
    my $api = FSM::Support::SemanticIntrospectionMCPAdapter->new(repo_root => $root, workspace_root => $root);
    for my $query (
        [[qw(--strict --check --json)], 'fsmgen_check'],
        [[qw(--strict --emit-semantic-json)], 'fsmgen_semantic_introspect'],
        [['--emit-schedule-json'], 'fsmgen_schedule_preview'],
    ) {
        my ($flags, $tool) = @$query;
        my $native = $capture->([$^X, 'bin/fsmgen', @$flags, $relative], '');
        is($native->{exit_code}, 0, "$tool native success") or diag($native->{stdout}, $native->{stderr});
        my $expected = FSM::Test::SourceQueryRunner::normalize_repository_paths($json->decode($native->{stdout}), $root);
        my $request = {jsonrpc => '2.0', id => 1, method => 'tools/call', params => {
            name => $tool, arguments => {source_id => $relative}}};
        my $response = $api->handle_jsonrpc_request($request);
        is_deeply($response->{result}{structuredContent}{report}, $expected, "$tool complete native/API parity");
        my $wire = $capture->([$^X, 'bin/fsmgen-mcp', '--workspace-root', '.'], $json->encode($request)."\n");
        is($wire->{exit_code}, 0, "$tool protocol success");
        is_deeply($json->decode($wire->{stdout}), $response, "$tool complete newline/API parity");
    }
};
done_testing;

sub write_file {
    my ($path, $text) = @_;
    open my $fh, '>', $path or die "open $path: $!";
    print {$fh} $text or die "write $path: $!";
    close $fh or die "close $path: $!";
    return $path;
}

