use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Storable qw(dclone);
use Digest::SHA qw(sha256_hex);
use Cwd qw(abs_path);
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Test::SourceQueryRunner;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Scheduler::ISF::DomainSource qw(_domain_actor_for_scheduled_artifact);
use FSM::Support::CapabilityManifest qw(build_capability_manifest);
use FSM::Support::SemanticIntrospectionMCPAdapter;

my $json = JSON::PP->new->canonical;
my $root = abs_path('.');
my $work = tempdir(CLEANUP => 1);
my $audit = 'docs/audits/storage-word-access-20260930';
my $baseline = $json->decode(read_file("$audit/baseline.json"));
my $parser = FSM::Adapter::ISF->new;
my $scheduler = FSM::Scheduler::ISF->new;
my $api = FSM::Support::SemanticIntrospectionMCPAdapter->new(repo_root => $root, workspace_root => $root);
my @unchanged = (qw(bin/fsmgen bin/fsmgen-mcp perl/FSM/Support/SemanticIntrospectionMCPAdapter.pm
    perl/FSM/Support/CapabilityManifest.pm perl/FSM/Support/RegressionCorpus.pm
    perl/FSM/Support/ISFPublicInterfaceContract.pm perl/FSM/Support/ISFRecordPortContexts.pm
    perl/FSM/Scheduler/ISF/LoweringIR.pm perl/FSM/Scheduler/ISF/Emitter/JSON.pm
    t/lib/FSM/Test/SourceQueryRunner.pm), "$audit/baseline.json", sort glob("$audit/*.isf"));
my $bytes_before = {map {$_ => sha256_hex(read_file($_))} @unchanged};

my @tokens = qw(ro rw wo w1c w0c rc rs warl wpri reserved);

subtest 'source relocation preserves decoded primitive kinds and later copies' => sub {
    my $literal = '{"integer":8,"negative":-3,"fraction":1.25,"numeric_text":"8","flag":true,"null":null,"source":"old.isf","nested":[4,"4","prefix old.isf suffix"]}';
    my $expected = $json->decode('{"integer":8,"negative":-3,"fraction":1.25,"numeric_text":"8","flag":true,"null":null,"source":"new.isf","nested":[4,"4","prefix new.isf suffix"]}');
    my $input = $json->decode($literal);
    my $got = relocate($input, 'old.isf', 'new.isf');
    same($got, $expected, 'complete decoded primitive/path output matches independent literal');
    same(dclone($got), $expected, 'complete later detached copy retains every primitive kind');
    same($input, $json->decode($literal), 'complete original literal input remains unchanged');
    same(dclone($input), $json->decode($literal), 'original caller also remains copy-stable');
};

subtest 'word and field facts stay independent for both scalar spellings' => sub {
    for my $kind (qw(var variable)) {
        for my $token (@tokens) {
            my $source = source("($kind value_reg (width 8) (access $token)"
                . ' (fields (field low (bits 1 0) (access wo)) (field high (bits 7 2))))');
            my $actor = $parser->parse_source($source, 'word.isf');
            is($actor->{storage}[0]{access}, $token, "$kind retains word $token");
            my $report = report($actor);
            my $entry = storage($report, 'value_reg');
            is($entry->{access}, $token, 'schedule reports the authored word fact');
            is($entry->{fields}[0]{access}, 'wo', 'field fact does not need to match word');
            ok(!exists $entry->{fields}[1]{access}, 'word fact is not inherited by an unstated field');
            my $without = $source;
            $without =~ s/\(access \Q$token\E\)//;
            my $control = $parser->parse_source($without, 'word.isf');
            my $expected = report($control);
            storage($expected, 'value_reg')->{access} = $token;
            same($report, $expected, 'access is the only schedule difference');
            same($scheduler->lower($actor)->{files}, $scheduler->lower($control)->{files},
                'complete scheduled artifacts unchanged');
            $entry->{access} = 'changed';
            is($actor->{storage}[0]{access}, $token, 'report does not mutate source');
        }
    }
    my $actor = $parser->parse_source(source('(var value_reg (width 8) (access ro))'), 'word.isf');
    ok(!exists storage(report($actor), 'value_reg')->{fields}, 'word access does not invent fields');
};

subtest 'malformed access, unsupported carriers and non-tokens fail contextually' => sub {
    for my $case (
        ['(access sometimes)', qr/unknown access token 'sometimes'/],
        ['(access RO)', qr/unknown access token 'RO'/],
        ['(access 0)', qr/unknown access token '0'/],
        ['(access)', qr/access requires/],
        ['(access ())', qr/access requires/],
        ['(access (ro))', qr/access requires/],
        ['(access ro rw)', qr/access requires/],
        ['(access ro) (access ro)', qr/duplicate 'access'/],
    ) {
        for my $kind (qw(var variable)) {
            my $ok = eval { $parser->parse_source(source("($kind value_reg (width 8) $case->[0])"), 'bad.isf'); 1 };
            ok(!$ok, "$kind $case->[0] rejected");
            like($@, qr/storage 'value_reg'/, 'diagnostic names storage');
            like($@, $case->[1], 'diagnostic explains malformed or unknown token');
        }
    }
    for my $entry ('(bank value_reg (width 8) (depth 2) (access ro))',
                   '(var value_reg (type byte_t) (access rw))') {
        my $ok = eval { $parser->parse_source(source($entry), 'bad.isf'); 1 };
        ok(!$ok, 'unsupported carrier rejected');
        like($@, qr/storage .*'value_reg'.*access.*(?:bank|width|typed)/, 'carrier boundary names storage and access');
    }
};

subtest 'supplied controls and new word forms preserve all hardware products' => sub {
    for my $case (qw(baseline-good whole-word-field register-access register-access-with-fields unknown-token)) {
        my $path = "$audit/$case.isf";
        my $failure = $case eq 'unknown-token';
        my $control = exists $baseline->{$case} ? $case : 'baseline-good';
        for my $query (qw(check semantic schedule)) {
            my $actual = public_query($path, $query, $failure);
            next if $failure;
            my $expected = dclone($baseline->{$control}{queries}{$query}{report});
            $expected = relocate($expected, "$audit/$control.isf", $path);
            if ($query eq 'schedule' && $case eq 'register-access') {
                storage($expected, 'status')->{access} = 'ro';
            } elsif ($query eq 'schedule' && $case eq 'register-access-with-fields') {
                storage($expected, 'control')->{access} = 'rw';
            }
            # T1984 independently qualifies the subsequently added declarations.
            my $ports = $query eq 'schedule' ? delete $actual->{interface_ports}
                : delete $actual->{source}{interface_ports};
            is(ref($ports), 'ARRAY', 'additive declared interface metadata is explicit');
            same($actual, $expected, "$case $query exact previous product plus only authored access");
        }
        for my $flags ([qw(--check --json)], ['--emit-semantic-json']) {
            my $r = capture([$^X, 'bin/fsmgen', @$flags, $path]);
            is($r->{exit_code}, $failure ? 1 : 0, 'default mode keeps the same admission outcome');
            my $report = $json->decode($r->{stdout});
            is(!!$report->{success}, !$failure, 'default report outcome');
            like($json->encode($report->{diagnostics}), qr/storage 'status'.*sometimes/, 'default failure names storage and token') if $failure;
        }
        next if $failure;
        my $actor = $parser->parse_file($path);
        same($scheduler->lower($actor)->{files}, $baseline->{$control}{scheduled_files},
            'complete actual scheduled carrier equals pre-change control');
        for my $language (qw(systemverilog verilog)) {
            my $output = "$work/$case-$language." . ($language eq 'verilog' ? 'v' : 'sv');
            my $r = capture([$^X, 'bin/fsmgen', '--language', $language, '--output', $output, $path]);
            is($r->{exit_code}, 0, "$case $language emission succeeds");
            is($r->{stderr}, '', 'HDL emission stderr clean');
            is(without_date(read_file($output)), without_date($baseline->{$control}{generated}{$language}{hdl}),
                'complete HDL and reset behavior unchanged except date banner');
        }
    }
};

subtest 'metadata follows domain storage ownership without changing carriers' => sub {
    my $text = <<'ISF';
(actor access_domains
 (clock-domains (domain core (clock clk) (reset rst_n) :default)
                (domain aux (clock aux_clk) (reset aux_rst_n)))
 (interface (input start) (output done) (input aux_start (domain aux)) (output aux_done (domain aux)))
 (storage (var core_reg (width 8) (access ro))
          (variable aux_reg (width 8) (domain aux) (access w1c)))
 (transaction main (on start) (set core_reg 1) (complete done))
 (transaction other (domain aux) (on aux_start) (set aux_reg 2) (complete aux_done)))
ISF
    my $actor = $parser->parse_source($text, 'domains.isf');
    my $ir = $scheduler->{ir}->build_module($actor);
    my %expected = (core => ['core_reg', 'ro'], aux => ['aux_reg', 'w1c']);
    for my $domain (@{$ir->{domain_partition}{domains}}) {
        my $selected = _domain_actor_for_scheduled_artifact($actor, $domain, $ir->{domain_partition}{default_domain});
        my ($name, $access) = @{$expected{$domain->{name}}};
        same([map { [$_->{name}, $_->{access}] } @{$selected->{storage}}], [[$name, $access]],
            'domain source selects only its independently authored fact');
        is(storage(report($selected), $name)->{access}, $access, 'domain report retains access');
    }
    my $without = $text; $without =~ s/\(access (?:ro|w1c)\)//g;
    my $control = $parser->parse_source($without, 'domains.isf');
    same($scheduler->lower($actor)->{files}, $scheduler->lower($control)->{files}, 'all domain FSM files unchanged');
    my $path = "$work/domains.isf"; write_file($path, $text); $path =~ s/^\Q$root\E\///;
    my $schedule = public_query($path, 'schedule', 0);
    my $expected_report = report($control);
    for my $domain (@{$expected_report->{clock_domains}}) {
        my ($name, $access) = @{$expected{$domain->{name}}};
        storage($domain, $name)->{access} = $access;
    }
    same($schedule, $expected_report, 'word access is the only domain report difference');
    same($schedule->{inferred_storage}, [], 'top owns no domain storage metadata');
    same([map { $_->{storage} } @{$schedule->{clock_domains}}],
        [['core_reg'], ['aux_reg']], 'existing domain storage-name lists are preserved');
};

subtest 'non-token and carrier refusals retain complete public diagnostics' => sub {
    my @cases = (
        ['duplicate', '(var value_reg (width 8) (access ro) (access rw))', qr/storage 'value_reg'.*duplicate 'access'/],
        ['malformed', '(var value_reg (width 8) (access (ro)))', qr/storage 'value_reg'.*access requires/],
        ['bank', '(bank value_reg (width 8) (depth 2) (access ro))', qr/storage 'value_reg'.*access.*bank/],
        ['typed', '(var value_reg (type byte_t) (access ro))', qr/storage 'value_reg'.*access.*typed/],
    );
    for my $case (@cases) {
        my $path = "$work/$case->[0].isf";
        write_file($path, source($case->[1]));
        $path =~ s/^\Q$root\E\///;
        public_query($path, $_, 1, $case->[2]) for qw(check semantic schedule);
        my $default = capture([$^X, 'bin/fsmgen', '--check', '--json', $path]);
        is($default->{exit_code}, 1, 'default check also refuses malformed/carrier form');
        like($default->{stdout}, $case->[2], 'default diagnostic retains contextual cause');
    }
};

subtest 'public discovery and supported fixture expose the report contract' => sub {
    my $manifest = build_capability_manifest();
    same($manifest->{embedding}{isf_public_interface}{schedule_report_storage_optional_keys},
        [qw(role type type_kind width fields access)], 'exact optional storage keys advertised');
    like($manifest->{embedding}{isf_public_interface}{schedule_report_storage_width_shape},
        qr/word.*access.*independent/s, 'metadata independence is discoverable');
    my $native = capture([$^X, 'bin/fsmgen', '--capability-manifest']);
    is($native->{exit_code}, 0, 'native capabilities succeed');
    same($json->decode($native->{stdout}), $manifest, 'full native/in-process capabilities agree');
    my $request = {jsonrpc => '2.0', id => 1, method => 'tools/call', params => {
        name => 'fsmgen_capability_query', arguments => {section => 'embedding'}}};
    my $response = $api->handle_jsonrpc_request($request);
    same($response->{result}{structuredContent}{payload}, $manifest->{embedding}, 'API embedding contract agrees');
    my $wire = capture([$^X, 'bin/fsmgen-mcp', '--workspace-root', '.'], $json->encode($request)."\n");
    is($wire->{exit_code}, 0, 'newline capability succeeds');
    same($json->decode($wire->{stdout}), $response, 'complete newline capability agrees');
    for my $query (qw(check semantic schedule)) {
        my $report = public_query('isf/storage_word_access.isf', $query, 0);
        if ($query eq 'schedule') {
            is(storage($report, 'status')->{access}, 'ro', 'fixture word access survives');
            is(storage($report, 'control')->{access}, 'rw', 'fixture word access with fields survives');
        } else {
            ok($report->{support_accounting}{matched}, 'public fixture is support-accounted');
        }
    }
};

same({map {$_ => sha256_hex(read_file($_))} @unchanged}, $bytes_before,
    'complete named public producer and immutable baseline/source bytes remain unchanged');

done_testing();

sub source {
    return '(actor access_word (types (type byte_t (bits 8))) (clock clk) (reset rst_n)'
        . ' (interface (input start) (output done)) (storage ' . $_[0] . ')'
        . ' (transaction main (on start) (set value_reg 1) (complete done)))';
}
sub report { $json->decode($scheduler->report($_[0])) }
sub storage { my ($r,$name)=@_; my ($v)=grep {$_->{name} eq $name} @{$r->{inferred_storage}}; return $v }
sub capture { FSM::Test::SourceQueryRunner::_capture($_[0], $_[1] // '') }
sub normalize { FSM::Test::SourceQueryRunner::normalize_repository_paths($_[0], $root) }
sub read_file { open my $fh, '<', $_[0] or die "$_[0]: $!"; local $/; return <$fh> }
sub write_file { open my $fh, '>', $_[0] or die $!; print {$fh} $_[1] or die $!; close $fh or die $! }
sub without_date { my $v=shift; $v =~ s/^\/\/ Date:[^\n]*\n//mg; return $v }
sub relocate {
    my ($v,$old,$new)=@_;
    return {map {$_ => relocate($v->{$_},$old,$new)} keys %$v} if ref($v) eq 'HASH';
    return [map {relocate($_,$old,$new)} @$v] if ref($v) eq 'ARRAY';
    return $v if !defined($v) || ref($v);
    my $inspect = $v;
    my $text = "$inspect";
    return $text =~ s/\Q$old\E/$new/g ? $text : $v;
}
sub public_query {
    my ($path,$query,$failure,$diagnostic)=@_;
    $diagnostic //= qr/storage 'status'.*sometimes/;
    my %flags=(check=>[qw(--strict --check --json)],semantic=>[qw(--strict --emit-semantic-json)],schedule=>['--emit-schedule-json']);
    my %tools=(check=>'fsmgen_check',semantic=>'fsmgen_semantic_introspect',schedule=>'fsmgen_schedule_preview');
    my $r=capture([$^X,'bin/fsmgen',@{$flags{$query}},$path]);
    is(!!$r->{exit_code},!!$failure,"$query native outcome");
    my $request={jsonrpc=>'2.0',id=>1,method=>'tools/call',params=>{name=>$tools{$query},arguments=>{source_id=>$path}}};
    my $response=$api->handle_jsonrpc_request($request);
    my $wire=capture([$^X,'bin/fsmgen-mcp','--workspace-root','.'],$json->encode($request)."\n");
    is($wire->{exit_code},0,'newline transport succeeds');
    is($wire->{stderr},'','newline stderr clean');
    same($json->decode($wire->{stdout}),$response,'complete API/newline equality');
    if ($failure && $query eq 'schedule') {
        is($r->{stdout},'','refused schedule has no report');
        like($r->{stderr},$diagnostic,'schedule failure retains contextual cause');
        ok($response->{error},'API retains schedule failure envelope');
        return;
    }
    is($r->{stderr},'','machine report stderr clean');
    my $report=normalize($json->decode($r->{stdout}));
    same($report,$response->{result}{structuredContent}{report},'complete native/API equality');
    same($json->decode($response->{result}{content}[0]{text}),$response->{result}{structuredContent},'textual content equals structured content');
    is(!!$response->{result}{isError},!!$failure,'API error flag retains outcome');
    like($json->encode($report->{diagnostics}),$diagnostic,'failure retains contextual cause') if $failure;
    return $report;
}

sub same { is($json->encode($_[0]), $json->encode($_[1]), $_[2]) }

source_snapshots.t/1983-isf-interface-port-metadata.t:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Storable qw(dclone);
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Adapter::ISF;
use FSM::Support::ISFInterfacePortMetadata qw(
    capture_interface_port_metadata snapshot_interface_port_metadata
    interface_port_metadata_contract
);

my $parser = FSM::Adapter::ISF->new;
my $json = JSON::PP->new->canonical;
my $actor = $parser->parse_source(<<'ISF', 'port-metadata.isf');
(actor port_metadata
  (types
    (type byte (bits 8))
    (type frame_t
      (record
        (subtype (bits 4))
        (payload (record
          (count (signed (four_state (bits 3))))
          (lanes (list (two_state bit) (bits 2))))))))
  (clock clk) (reset rst)
  (interface (output unused (width 2)) (input start)
             (input data (type byte)) (output done))
  (storage (var frame (type frame_t)))
  (transaction main (on start) (complete done)))
ISF

subtest 'declared scalar ports retain ordering and alias facts' => sub {
    my $expected = [
        {name => 'start', direction => 'input', width => 1},
        {name => 'data', direction => 'input', width => 8, type => 'byte', type_kind => 'bits'},
        {name => 'unused', direction => 'output', width => 2},
        {name => 'done', direction => 'output', width => 1},
    ];
    my $before = dclone($actor);
    my $actual = capture_interface_port_metadata($actor->{interface});
    is_deeply($actual, $expected, 'input order followed by output order, including unused declarations');
    is_deeply($json->decode($json->encode($actual)), $expected, 'closed result is JSON-safe');
    $actual->[1]{width} = 99;
    is_deeply($actor, $before, 'projection does not share parser objects');
    my $domain_interface = dclone($actor->{interface});
    $domain_interface->{inputs}[1]{domain} = 'aux';
    my $scoped = capture_interface_port_metadata($domain_interface, 'core');
    is_deeply([map { $_->{domain} } @$scoped], [qw(core aux core core)],
        'explicit domains override the declared default');
    is_deeply(capture_interface_port_metadata({inputs => [{name => 'data-lane', width => 2}], outputs => []}),
        [{name => 'data-lane', direction => 'input', width => 2}],
        'metadata preserves nonempty opaque port names without inventing source restrictions');
};

my $fields = [
    {path => 'subtype', width => 4, lsb => 6, msb => 9, signed => 0},
    {path => 'payload.count', width => 3, lsb => 3, msb => 5, signed => 1, state_model => 'four_state'},
    {path => 'payload.lanes[0]', width => 1, lsb => 2, msb => 2, signed => 0, state_model => 'two_state'},
    {path => 'payload.lanes[1]', width => 2, lsb => 0, msb => 1, signed => 0},
];
my $record_interface = {
    inputs => [{name => 'packet', width => 10, type => 'frame_t', type_spec => $actor->{storage}[0]{type_spec}}],
    outputs => [],
};
my $record = [{name => 'packet', direction => 'input', width => 10,
    type => 'frame_t', type_kind => 'record', fields => $fields}];

sub stringify_numeric_properties {
    my ($value) = @_;
    if (ref($value) eq 'HASH') {
        for my $key (keys %$value) {
            if ($key =~ /\A(?:width|lsb|msb|signed)\z/ && !ref($value->{$key})) {
                $value->{$key} = "$value->{$key}";
            } else {
                stringify_numeric_properties($value->{$key});
            }
        }
    } elsif (ref($value) eq 'ARRAY') {
        stringify_numeric_properties($_) for @$value;
    }
}

subtest 'capture and snapshot detach before first numeric read on valid and refused facts' => sub {
    for my $case (
        ['capture',\&capture_interface_port_metadata,$record_interface],
        ['snapshot',\&snapshot_interface_port_metadata,$record],
    ) {
        my ($name,$produce,$template) = @$case;
        my $value=dclone($template);
        stringify_numeric_properties($value);
        my $before=$json->encode($value);
        my $actual=$produce->($value);
        is($json->encode($value),$before,"$name preserves original scalar kinds on its first read");
        is_deeply($actual,$record,"$name still returns the same independently expected numeric layout");
        $actual->[0]{fields}[0]{width}=99;
        is($json->encode($value),$before,"$name output mutation cannot reach source facts");
        $value=dclone($template);
        stringify_numeric_properties($value);
        if ($name eq 'capture') {
            push @{$value->{outputs}}, {name=>'invalid',width=>'bad'};
        } else {
            push @$value,undef;
        }
        $before=$json->encode($value);
        my $ok=eval {$produce->($value);1};
        my ($line)=split /\n/,$@;
        ok(!$ok,"$name rejects a malformed suffix after valid numeric facts");
        like($line // '',qr/\AInvalid ISF interface port metadata:/,"$name retains a classified first diagnostic");
        is($json->encode($value),$before,"$name refused first read cannot mutate valid prefix facts");
    }
};

subtest 'resolved record preparation preserves independently expected leaf ranges' => sub {
    my $before = dclone($record_interface);
    my $actual = capture_interface_port_metadata($record_interface);
    is_deeply($actual, $record, 'nested record/list leaves have authored order and exact packed ranges');
    $actual->[0]{fields}[0]{lsb} = 0;
    is_deeply($record_interface, $before, 'nested type objects remain detached');
    my $copy = snapshot_interface_port_metadata($record);
    $copy->[0]{fields}[1]{state_model} = 'two_state';
    is($record->[0]{fields}[1]{state_model}, 'four_state', 'snapshot does not share nested fields');
    my $ok = eval { $parser->parse_source(
        '(actor refused (types (type packet_t (record (flag bit))))'
        . ' (interface (output packet (type packet_t)) (output done))'
        . ' (transaction main (set packet.flag 1) (complete done)))', 'field-refused.isf'); 1 };
    ok(!$ok, 'record output field writer remains deferred');
    like($@, qr/record output field writes are not yet admitted/,
        'existing authored-field refusal remains precise');
};

subtest 'imported scalar and record aliases retain qualified identity' => sub {
    my $work = tempdir(CLEANUP => 1);
    write_file("$work/shared.fsm", '(?pkg:shared (+types (type byte (bits 8))'
        . ' (type packet_t (record (code (bits 2)) (flag bit)))))');
    my $path = "$work/imported.isf";
    write_file($path, '(actor imported (imports (package shared)) (clock clk) (reset rst)'
        . ' (interface (input data (type shared.byte)) (output done))'
        . ' (storage (var packet (type shared.packet_t))) (transaction main (complete done)))');
    my $parsed = $parser->parse_file($path);
    my $ports = capture_interface_port_metadata($parsed->{interface});
    is_deeply($ports->[0], {name => 'data', direction => 'input', width => 8,
        type => 'shared.byte', type_kind => 'bits'}, 'imported scalar alias is not flattened to an anonymous width');
    my $prepared = capture_interface_port_metadata({inputs => [{name => 'packet', width => 3,
        type => 'shared.packet_t', type_spec => $parsed->{storage}[0]{type_spec}}], outputs => []});
    is($prepared->[0]{type}, 'shared.packet_t', 'record producer retains imported alias');
    is_deeply($prepared->[0]{fields}, [
        {path => 'code', width => 2, lsb => 1, msb => 2, signed => 0},
        {path => 'flag', width => 1, lsb => 0, msb => 0, signed => 0},
    ], 'independent imported layout oracle');
};

subtest 'unknown and known empty metadata stay distinct' => sub {
    is(capture_interface_port_metadata(undef), undef, 'absent declarations are unknown');
    is(snapshot_interface_port_metadata(undef), undef, 'unknown snapshot remains null');
    is_deeply(capture_interface_port_metadata({inputs => [], outputs => []}), [], 'known empty declarations remain empty');
    is_deeply(snapshot_interface_port_metadata([]), [], 'known empty snapshot remains empty');
    my $contract = interface_port_metadata_contract();
    is_deeply($contract->{entry_keys}, [qw(name direction width)], 'required entry keys match decision 0113');
    is_deeply($contract->{optional_entry_keys}, [qw(type type_kind domain fields)], 'optional entry keys match the selected schema');
    is_deeply($contract->{field_keys}, [qw(path width lsb msb signed)], 'scalar field key family is explicit');
    is_deeply($contract->{type_kind_values}, [qw(bit bits record)], 'list roots remain outside the selected contract');
    $contract->{entry_keys}[0] = 'changed';
    is(interface_port_metadata_contract()->{entry_keys}[0], 'name', 'discovery values are detached');
};

subtest 'closed snapshots reject malformed and contradictory metadata' => sub {
    my @bad = ({}, [undef], [{}]);
    for my $change (
        sub { delete $_[0][0]{name} }, sub { $_[0][0]{extra} = [] },
        sub { $_[0][0]{name} = '' }, sub { $_[0][0]{direction} = 'inout' },
        sub { $_[0][0]{width} = 0 }, sub { $_[0][0]{width} = 'bad' },
        sub { $_[0][0]{domain} = [] }, sub { $_[0][0]{domain} = 'bad-domain' },
        sub { $_[0][0]{type} = [] }, sub { $_[0][0]{type} = 'bad-alias' },
        sub { $_[0][0]{type_kind} = 'list' },
        sub { delete $_[0][0]{type} }, sub { delete $_[0][0]{fields} },
        sub { $_[0][0]{fields} = [] }, sub { $_[0][0]{fields}[0]{extra} = 1 },
        sub { $_[0][0]{fields}[0]{path} = [] }, sub { $_[0][0]{fields}[1]{path} = 'subtype' },
        sub { $_[0][0]{fields}[0]{msb} = 8 }, sub { $_[0][0]{fields}[0]{lsb} = 5 },
        sub { $_[0][0]{fields}[0]{lsb} = 'bad' }, sub { $_[0][0]{fields}[0]{width} = 'bad' },
        sub { $_[0][0]{fields}[-1]{lsb} = 1; $_[0][0]{fields}[-1]{width} = 1 },
        sub { $_[0][0]{fields}[0]{signed} = 2 }, sub { $_[0][0]{fields}[0]{state_model} = 'unknown' },
        sub { push @{$_[0]}, dclone($_[0][0]) },
    ) {
        my $value = dclone($record);
        $change->($value);
        push @bad, $value;
    }
    push @bad, [{name => 'out', direction => 'output', width => 1},
        {name => 'in', direction => 'input', width => 1}];
    push @bad, [{name => 'scalar', direction => 'input', width => 'bad'}],
        [{name => 'scalar', direction => 'input', width => 8, type => 'byte', type_kind => 'unknown'}];
    for my $index (0 .. $#bad) {
        my $bad = $bad[$index];
        rejects(sub { snapshot_interface_port_metadata($bad) }, "malformed snapshot $index", $bad);
    }
};

subtest 'producer rejects inconsistent resolved declarations without warnings' => sub {
    my @bad = ({}, {inputs => [undef], outputs => []});
    for my $change (
        sub { $_[0]{inputs}[0]{name} = undef }, sub { $_[0]{inputs}[0]{width} = 'bad' },
        sub { $_[0]{inputs}[0]{width} = 9 }, sub { delete $_[0]{inputs}[0]{type_spec} },
        sub { $_[0]{inputs}[0]{type_spec}{width} = 9 },
        sub { $_[0]{inputs}[0]{type_spec}{member_order} = ['subtype', 'subtype'] },
        sub { $_[0]{inputs}[0]{type_spec}{members}{subtype}{state_model} = [] },
        sub { $_[0]{inputs}[0]{type_spec}{members}{subtype}{signed} = [] },
        sub { delete $_[0]{inputs}[0]{type} },
        sub { $_[0]{inputs}[0]{type_spec} = {kind => 'list', width => 1, items => [{kind => 'bit', width => 1}]} },
    ) {
        my $value = dclone($record_interface);
        $change->($value);
        push @bad, $value;
    }
    my $cycle = {kind => 'record', width => 1, member_order => ['loop'], members => {}};
    $cycle->{members}{loop} = $cycle;
    push @bad, {inputs => [{name => 'cycle', width => 1, type => 'cycle_t', type_spec => $cycle}], outputs => []};
    for my $bad (@bad) { rejects(sub { capture_interface_port_metadata($bad) }, 'invalid producer input'); }
    delete $cycle->{members}{loop};
};

done_testing();

sub rejects {
    my ($operation, $label, $value) = @_;
    my @warnings;
    local $SIG{__WARN__} = sub { push @warnings, @_ };
    my $ok = eval { $operation->(); 1 };
    diag($json->encode($value)) if $ok && defined $value;
    ok(!$ok, "$label fails closed");
    like($@, qr/Invalid ISF interface port metadata:/, 'contextual bounded diagnostic');
    is_deeply(\@warnings, [], 'invalid metadata does not emit incidental Perl warnings');
}

sub write_file {
    my ($path, $text) = @_;
    open my $fh, '>', $path or die $!;
    print {$fh} $text or die $!;
    close $fh or die $!;
}

source_snapshots.t/1986-isf-record-port-value-gates.t:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use Carp qw(confess);
use Storable qw(dclone);
use JSON::PP;
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Adapter::ISF;
use FSM::Package::PayloadTypeSupport;
use FSM::Support::ISFRecordPortValues qw(
    record_value_scope record_value_reference validate_record_port_copy
);

my $parser = FSM::Adapter::ISF->new;
my $actor = $parser->parse_source(<<'ISF', 'record-value-controls.isf');
(actor controls
  (types
    (type frame (record (flag bit) (data (bits 7))))
    (type alias frame)
    (type renamed (record (tag bit) (data (bits 7))))
    (type reordered (record (data (bits 7)) (flag bit)))
    (type signed_data (record (flag bit) (data (signed (bits 7)))))
    (type four (record (flag bit) (data (four_state (bits 7)))))
    (type two (record (flag bit) (data (two_state (bits 7)))))
    (type bit_kind (record (flag (bits 1)) (data (bits 7))))
    (type nested (record (header (bits 2))
      (body (record (count (signed (four_state (bits 3))))
        (lanes (list (two_state bit) (bits 2)))))))
    (type flat (record (header (bits 2)) (count (signed (four_state (bits 3))))
      (lane0 (two_state bit)) (lane1 (bits 2))))
    (type lanes (list bit (bits 2))))
  (interface (input start) (output done))
  (storage (var a (type frame)) (var b (type alias)) (var c (type renamed))
    (var d (type reordered)) (var e (type signed_data)) (var f (type four))
    (var g (type two)) (var h (type bit_kind)) (var i (type nested))
    (var j (type flat)) (var k (type lanes)))
  (transaction main (on start) (complete done)))
ISF
my %types = map { $_->{type} => $_->{type_spec} } @{$actor->{storage}};
my $scalar = {kind => 'bits', width => 7, signed => 0};

subtest 'validation preserves caller JSON kinds on first touch' => sub {
    my $json = JSON::PP->new->canonical;
    my $string_frame = $json->decode('{"kind":"record","width":"8","signed":0,"member_order":["flag","data"],'
        . '"members":{"flag":{"kind":"bit","width":"1","signed":0},'
        . '"data":{"kind":"bits","width":"7","signed":0}}}');
    my $roots = {packet => {role => 'input', type_spec => $string_frame}};
    my $before = $json->encode($roots);
    record_value_scope(outer => $roots, local => {});
    is($json->encode($roots), $before, 'scope validation retains original typed JSON');
    my $scope = {packet => {role => 'input', type_spec => $json->decode($before)->{packet}{type_spec}}};
    $before = $json->encode($scope);
    record_value_reference(scope => $scope, token => 'packet.data', access => 'read', context => 'first touch');
    is($json->encode($scope), $before, 'reference validation retains original typed JSON');
    my $source = {root => 'packet', role => 'input', path_text => '', width => '8',
        type_spec => $json->decode($before)->{packet}{type_spec}};
    my $target = dclone($source);
    @{$target}{qw(root role)} = ('held', 'storage');
    $before = $json->encode([$source, $target]);
    validate_record_port_copy(source => $source, target => $target, context => 'first touch');
    is($json->encode([$source, $target]), $before, 'copy validation retains original typed JSON');
};

sub scope_for {
    my ($source_type, $target_type, $local) = @_;
    return record_value_scope(outer => {
        packet => {role => 'input', type_spec => $source_type},
        held => {role => 'storage', type_spec => $target_type},
        output => {role => 'output', type_spec => $target_type},
        scalar => {role => 'output', type_spec => $scalar},
    }, local => $local || {});
}
sub reference {
    my ($scope, $token, $access, $whole) = @_;
    return record_value_reference(scope => $scope, token => $token,
        access => $access || 'read', allow_whole => $whole || 0, context => 'control');
}
sub copy {
    my ($scope, $source, $target) = @_;
    return validate_record_port_copy(source => reference($scope, $source, 'read', 1),
        target => reference($scope, $target, 'write', 1), context => 'copy control');
}
sub refuses {
    my ($run, $pattern, $name) = @_;
    my $ok = eval { $run->(); 1 };
    my $diagnostic = diagnostic_line($@);
    ok(!$ok, "$name refuses");
    like($diagnostic, $pattern, "$name names the cause in its diagnostic line");
}
sub diagnostic_line { (split /\n/, $_[0] // '')[0] // '' }
sub wrong_cause_with_pattern_in_stack {
    my ($expected) = @_;
    eval { confess "Deliberately wrong diagnostic\n" };
    return $@;
}

subtest 'diagnostic oracle rejects an expected pattern present only in the stack' => sub {
    my $error = wrong_cause_with_pattern_in_stack(qr/expected_cause_only_in_argument/);
    like($error, qr/expected_cause_only_in_argument/, 'known bad full trace contains the caller pattern');
    is(diagnostic_line($error), 'Deliberately wrong diagnostic', 'oracle selects the actual message');
    unlike(diagnostic_line($error), qr/expected_cause_only_in_argument/,
        'the same false cause cannot satisfy the diagnostic oracle');
};

subtest 'resolved alias identity and allowed root roles' => sub {
    my $scope = scope_for($types{frame}, $types{alias});
    ok(copy($scope, 'packet', 'held'), 'input to owner storage accepts resolved alias equivalence');
    ok(copy($scope, 'held', 'output'), 'prepared storage to output contract accepts identity');
    ok(copy($scope, 'packet', 'output'), 'prepared input to output contract accepts identity');
    my $source = reference($scope, 'packet', 'read', 1);
    my $target = reference($scope, 'packet', 'read', 1);
    refuses(sub { validate_record_port_copy(source => $source, target => $target,
        context => 'forged write') }, qr/forged write cannot write declared input 'packet'/,
        'copy independently enforces target role');
    refuses(sub { reference($scope, 'packet', 'write', 1) }, qr/cannot write declared input 'packet'/,
        'whole input target');
    refuses(sub { reference($scope, 'packet.data', 'write') }, qr/cannot write declared input 'packet.data'/,
        'scalar input target');
    ok(reference($scope, 'output.data', 'write'), 'prepared scalar output target retains allowed role');
    my $before = dclone($actor);
    $scope->{packet}{type_spec}{members}{data}{width} = 99;
    is_deeply($actor, $before, 'prepared scope does not share parser types');
};

subtest 'same packed width does not establish record identity' => sub {
    for my $name (qw(renamed reordered signed_data four two bit_kind)) {
        is($types{$name}{width}, 8, "$name has independently expected equal packed width");
        my $scope = scope_for($types{frame}, $types{$name});
        refuses(sub { copy($scope, 'packet', 'held') }, qr/requires the same resolved record type/,
            "$name copy identity");
    }
    my $scope = scope_for($types{four}, $types{two});
    refuses(sub { copy($scope, 'packet', 'held') }, qr/requires the same resolved record type/,
        'explicit state-model difference');
    for my $name (qw(signed_data four two bit_kind)) {
        ok(FSM::Package::PayloadTypeSupport->payload_compatible_with_type_spec($types{frame}, $types{$name}),
            "$name retains the established payload compatibility contract");
    }
    my $nested_scope = scope_for($types{nested}, $types{flat});
    is($types{nested}{width}, 8, 'independent nested packed width');
    is($types{flat}{width}, 8, 'independent flattened packed width');
    refuses(sub { copy($nested_scope, 'packet', 'held') }, qr/requires the same resolved record type/,
        'nested shape cannot be flattened for copy identity');
    my $swapped = dclone($types{nested});
    @{$swapped->{members}{body}{members}{lanes}{items}} =
        reverse @{$swapped->{members}{body}{members}{lanes}{items}};
    my $list_scope = scope_for($types{nested}, $swapped);
    refuses(sub { copy($list_scope, 'packet', 'held') }, qr/requires the same resolved record type/,
        'nested list item order retains type identity');
};

subtest 'core scalar paths retain exact packed range and property facts' => sub {
    my $scope = scope_for($types{nested}, $types{nested});
    is_deeply(reference($scope, 'packet.body.count'), {
        root => 'packet', role => 'input', path_text => '.body.count',
        type_spec => {kind => 'bits', width => 3, signed => 1, state_model => 'four_state'},
        width => 3, low => 3, high => 5,
    }, 'independent nested signed/four-state leaf range');
    is_deeply(reference($scope, 'packet.body.lanes[0]'), {
        root => 'packet', role => 'input', path_text => '.body.lanes[0]',
        type_spec => {kind => 'bit', width => 1, signed => 0, state_model => 'two_state'},
        width => 1, low => 2, high => 2,
    }, 'independent nested list-item leaf range');
    my $leaf = reference($scope, 'packet.body.count');
    $leaf->{type_spec}{signed} = 0;
    is(reference($scope, 'packet.body.count')->{type_spec}{signed}, 1,
        'leaf results do not share scope facts');
    for my $pair (
        ['packet', qr/requires a scalar value/],
        ['packet.body', qr/requires a scalar leaf/],
        ['packet.body.lanes', qr/requires a scalar leaf/],
        ['packet.unknown', qr/invalid declared path.*unknown_member/],
        ['packet.body.lanes[2]', qr/invalid declared path.*list_index_out_of_range/],
        ['packet.body.count[3]', qr/invalid declared path.*scalar_index_out_of_range/],
        ['packet..count', qr/invalid declared path.*parse_error/],
    ) {
        refuses(sub { reference($scope, $pair->[0]) }, $pair->[1], $pair->[0]);
    }
    refuses(sub { reference($scope, 'held.body', 'write', 1) }, qr/requires a scalar leaf/,
        'whole-value permission does not allow subaggregate writes');
};

subtest 'nearest lexical declarations mask outer type and role facts' => sub {
    my $unresolved = scope_for($types{frame}, $types{frame}, {
        packet => {role => 'local', type_spec => undef},
    });
    is(reference($unresolved, 'packet.data'), undef, 'unresolved local masks the outer record type');
    my $formal = scope_for($types{frame}, $types{frame}, {
        packet => {role => 'output', type_spec => $types{nested}},
    });
    my $leaf = reference($formal, 'packet.body.count', 'write');
    is($leaf->{role}, 'output', 'nearest formal output is writable despite outer input name');
    is($leaf->{width}, 3, 'formal type owns local path width');
    refuses(sub { reference($formal, 'packet.data') }, qr/unknown_member/,
        'formal does not borrow an outer member');
    my $scalar_shadow = scope_for($types{frame}, $types{frame}, {
        packet => {role => 'local', type_spec => $scalar},
    });
    is(reference($scalar_shadow, 'packet', 'write')->{width}, 7,
        'scalar local retains its width and writable role');
    refuses(sub { reference($scalar_shadow, 'packet.data') }, qr/member_on_non_record/,
        'scalar local cannot borrow an outer record');
    is_deeply(reference($scalar_shadow, 'packet[5:3]', 'write'), {
        root => 'packet', role => 'local', path_text => '[5:3]',
        type_spec => {kind => 'bits', width => 3, signed => 0},
        width => 3, low => 3, high => 5,
    }, 'scalar local slice retains core range and writable local role');
    is(reference($scalar_shadow, 'packet[0]')->{width}, 1,
        'scalar local bit index stays scalar');
    my $unresolved_input = scope_for($types{frame}, $types{frame}, {
        packet => {role => 'input', type_spec => undef},
    });
    refuses(sub { reference($unresolved_input, 'packet', 'write') }, qr/cannot write declared input/,
        'an unresolved type cannot erase a known input role');
    is(reference($formal, 'mode.BUSY'), undef, 'unrelated enum roots stay with existing enum validation');
    is(reference($formal, 'shared.CONSTANT'), undef, 'unrelated package roots stay with package validation');
};

subtest 'record copy gates preserve existing scalar and storage-only contracts' => sub {
    my $scope = scope_for($types{frame}, $types{signed_data});
    $scope->{old} = {role => 'storage', type_spec => dclone($types{frame})};
    is(copy($scope, 'old', 'held'), 0, 'different storage-only types use the prior assignment contract');
    is(copy($scope, 'scalar', 'scalar'), 0, 'scalar ports introduce no record copy obligation');
    is(validate_record_port_copy(source => undef, target => undef, context => 'literal'), 0,
        'unrelated literal/expression handling remains with caller');
    refuses(sub { copy($scope, 'scalar', 'output') }, qr/requires declared record roots/,
        'equal/unequal scalar carrier is not a record copy');
    refuses(sub { validate_record_port_copy(source => undef,
        target => reference($scope, 'output', 'write', 1), context => 'expression') },
        qr/requires declared record roots/, 'record target cannot treat an expression as a same-type root');
    $scope->{lanes} = {role => 'storage', type_spec => dclone($types{lanes})};
    is(reference($scope, 'lanes[1]')->{width}, 2, 'existing list storage scalar leaves remain resolvable');
    refuses(sub { copy($scope, 'lanes', 'output') }, qr/requires declared record roots/,
        'root list is not a same-type record copy');
};

subtest 'imported and local aliases with identical resolved records match' => sub {
    my $work = tempdir(CLEANUP => 1);
    open my $file, '>', "$work/shared.fsm" or die $!;
    print {$file} '(?pkg:shared (+types (type frame (record (flag bit) (data (bits 7))))))';
    close $file or die $!;
    my $imported = $parser->parse_source('(actor imported (imports (package shared))'
        . ' (interface (output done)) (storage (var value (type shared.frame)))'
        . ' (transaction main (complete done)))', "$work/imported.isf");
    my $scope = scope_for($imported->{storage}[0]{type_spec}, $types{frame});
    ok(copy($scope, 'packet', 'held'), 'package spelling does not affect resolved identity');
};

subtest 'closed malformed facts fail before comparison or path traversal' => sub {
    for my $pair (
        ['unknown key', sub { $_[0]{extra} = 1 }, qr/unknown facts/],
        ['bad root width', sub { $_[0]{width} = 9 }, qr/width disagrees/],
        ['bad scalar signed', sub { $_[0]{members}{data}{signed} = 2 }, qr/signed property/],
        ['missing signed', sub { delete $_[0]{members}{data}{signed} }, qr/lacks required facts/],
        ['aggregate signed', sub { $_[0]{signed} = 1 }, qr/scalar signed overlay/],
        ['aggregate state', sub { $_[0]{state_model} = 'two_state' }, qr/unknown facts/],
        ['bad state', sub { $_[0]{members}{data}{state_model} = 'unknown' }, qr/state model/],
        ['duplicate order', sub { $_[0]{member_order} = [qw(flag flag)] }, qr/duplicate record member/],
        ['unlisted member', sub { $_[0]{members}{extra} = dclone($scalar) }, qr/inventory disagrees/],
        ['cyclic member', sub { $_[0]{members}{data} = $_[0] }, qr/cyclic resolved type/],
        ['deferred kind', sub { $_[0]{kind} = 'deferred_imported_alias' }, qr/unsupported resolved type kind/],
    ) {
        my $spec = dclone($types{frame});
        $pair->[1]->($spec);
        refuses(sub { scope_for($spec, $types{frame}) }, $pair->[2], $pair->[0]);
    }
    refuses(sub { record_value_scope(outer => {packet => {role => 'inout', type_spec => $types{frame}}},
        local => {}) }, qr/invalid role/, 'unknown role');
    refuses(sub { record_value_scope(outer => {}, local => {}, surprise => 1) }, qr/unknown facts/,
        'unknown scope argument');
    my $scope = scope_for($types{frame}, $types{frame});
    refuses(sub { record_value_reference(scope => $scope, token => 'packet', access => 'read',
        context => 'permission', allow_whole => 2) }, qr/whole-value permission/,
        'nonbinary whole-value permission');
    my $value = reference($scope, 'packet', 'read', 1);
    $value->{width} = 9;
    refuses(sub { validate_record_port_copy(source => $value,
        target => reference($scope, 'held', 'write', 1), context => 'hostile') }, qr/width disagrees/,
        'contradictory copy descriptor');
};

subtest 'output member writes and list-root source carriers remain closed' => sub {
    for my $pair (
        ['output', 'frame', '(set value.flag 1)', qr/record output field writes are not yet admitted/],
        ['input', 'lanes', '(complete done)', qr/interface port 'value' references aggregate type/],
    ) {
        my ($direction, $type, $clause, $pattern) = @$pair;
        my $source = '(actor refused (types (type frame (record (flag bit))) (type lanes (list bit bit)))'
            . " (interface ($direction value (type $type)) (output done))"
            . " (transaction main $clause))";
        refuses(sub { $parser->parse_source($source, 'still-refused.isf') }, $pattern,
            "$direction $type source");
    }
};

done_testing;

source_snapshots.t/1987-isf-record-port-declaration-scope:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use Storable qw(dclone);
use JSON::PP;
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Support::ISFRecordPortScopes qw(
    record_actor_scope record_transaction_scope record_drive_scope
);
use FSM::Support::ISFRecordPortValues qw(record_value_reference);

my $parser = FSM::Adapter::ISF->new;
my $json = JSON::PP->new->canonical;
my $source = <<'ISF';
(actor scopes
  (params (W 8))
  (types (type frame (record (header (bits 2))
      (payload (signed (four_state (bits 6))))))
    (type word (signed (two_state (bits 5)))))
  (interface (input start) (input data (width W)) (output seen (width 8)) (output done))
  (storage (var packet (type frame)) (var backup (type frame)))
  (drive (publish packet) (seen packet))
  (transaction worker (ports (output packet (type word)) (input arg (width W)))
    (local count (width 3) (default 0)) (set packet arg))
  (transaction main (on start) (set seen packet.payload) (complete done)))
ISF
my $actor = $parser->parse_source($source, 'scope-controls.isf');

subtest 'first projection preserves complete fresh copied parsed scalar kinds' => sub {
    my $unread = $source =~ s/\(set seen packet.payload\)/(set seen 0)/r;
    for my $kind (qw(actor transaction drive)) {
        my $fresh = dclone($parser->parse_source($unread, 'first-touch-scope.isf'));
        my $before = $json->encode($fresh);
        record_actor_scope(actor => $fresh) if $kind eq 'actor';
        record_transaction_scope(actor => $fresh, transaction => $fresh->{transactions}[0]) if $kind eq 'transaction';
        record_drive_scope(actor => $fresh, drive => $fresh->{drives}{publish}) if $kind eq 'drive';
        is($json->encode($fresh), $before, "$kind first projection preserves complete actor JSON kinds");
    }
};

sub reference {
    my ($scope, $token, $access) = @_;
    return record_value_reference(scope => $scope, token => $token,
        access => $access || 'read', context => 'scope control');
}
sub refuses {
    my ($run, $pattern, $name) = @_;
    my $ok = eval {$run->(); 1};
    my ($line) = split /\n/, $@;
    ok(!$ok, "$name refuses");
    like($line // '', $pattern, "$name names its first-line cause");
}

subtest 'actual finalized actor declarations retain role and type facts' => sub {
    my $scope = record_actor_scope(actor => $actor);
    is_deeply([sort keys %$scope], [qw(backup data done packet seen start)], 'declared roots only');
    is_deeply($scope->{data}, {role => 'input',
        type_spec => {kind => 'bits', width => 8, signed => 0}},
        'resolved symbolic input retains declared width and role');
    is($scope->{packet}{role}, 'storage', 'record root retains storage role');
    is_deeply(reference($scope, 'packet.payload'), {
        root => 'packet', role => 'storage', path_text => '.payload', width => 6, low => 0, high => 5,
        type_spec => {kind => 'bits', width => 6, signed => 1, state_model => 'four_state'},
    }, 'independent packed leaf witness retains signed/state and range');
    is_deeply([@{reference($scope, 'packet.header')}{qw(width low high)}], [2, 6, 7],
        'first authored member is most significant');
    refuses(sub {reference($scope, 'data', 'write')}, qr/cannot write declared input 'data'/,
        'declared actor input cannot become a write');
    my $conflicting = dclone($actor);
    push @{$conflicting->{storage}}, {kind => 'var', name => 'data', width => 8,
        type => 'frame', type_spec => dclone($actor->{storage}[0]{type_spec})};
    is(record_actor_scope(actor => $conflicting)->{data}{role}, 'input',
        'caller-supplied conflicting storage cannot erase a pin role');
    refuses(sub {$parser->parse_source($source =~ s/backup/data/r, 'conflicting.isf')},
        qr/storage signal 'data' conflicts with interface input port 'data'/,
        'projection does not admit authored actor/storage collisions');
    ok(!exists($scope->{publish}) && !exists($scope->{worker}), 'drive and transaction names are not value declarations');
};

subtest 'actual transaction formals and locals mask outer facts' => sub {
    my $scope = record_transaction_scope(actor => $actor, transaction => $actor->{transactions}[0]);
    is_deeply($scope->{packet}, {role => 'output',
        type_spec => {kind => 'bits', width => 5, signed => 1, state_model => 'two_state'}},
        'formal replaces outer record with its own resolved scalar');
    is_deeply($scope->{arg}, {role => 'input', type_spec => {kind => 'bits', width => 8, signed => 0}},
        'formal symbolic width is finalized');
    is_deeply($scope->{count}, {role => 'local', type_spec => {kind => 'bits', width => 3, signed => 0}},
        'explicit local width has no borrowed alias, reset or state overlay');
    is_deeply([@{reference($scope, 'packet[3:1]')}{qw(width low high)}], [3, 1, 3],
        'formal slice resolves against local scalar width');
    refuses(sub {reference($scope, 'packet.payload')}, qr/member_on_non_record/,
        'shadow cannot borrow outer member');
    refuses(sub {reference($scope, 'arg', 'write')}, qr/cannot write declared input 'arg'/,
        'formal input retains its own role');
};

subtest 'unresolved declarations mask without using parser placeholders' => sub {
    my $unresolved = dclone($actor);
    delete $unresolved->{transactions}[0]{ports}{outputs}[0]{type_spec};
    $unresolved->{transactions}[0]{ports}{outputs}[0]{width} = 1;
    my $scope = record_transaction_scope(actor => $unresolved, transaction => $unresolved->{transactions}[0]);
    is_deeply($scope->{packet}, {role => 'output', type_spec => undef},
        'typed formal placeholder remains unknown');
    is(reference($scope, 'packet.payload'), undef, 'unresolved formal never falls through to outer record');
    my $symbolic = $parser->parse_source($source =~ s/\(width 3\)/\(width W\)/r, 'symbolic-local.isf');
    $scope = record_transaction_scope(actor => $symbolic, transaction => $symbolic->{transactions}[0]);
    is_deeply($scope->{count}, {role => 'local', type_spec => undef},
        'local symbolic width is not finalized by actor port-width resolution');
    refuses(sub {FSM::Scheduler::ISF->new->lower($symbolic)}, qr/requires a '\(width N\)' with a positive integer/,
        'projection does not admit unsupported symbolic locals');
    my $local_shadow = dclone($actor);
    push @{$local_shadow->{transactions}[0]{clauses}}, ['local', 'packet', ['width', 'UNKNOWN']];
    $scope = record_transaction_scope(actor => $local_shadow, transaction => $local_shadow->{transactions}[0]);
    is_deeply($scope->{packet}, {role => 'local', type_spec => undef},
        'explicit unresolved local masks formal and actor type facts');
    my $unknown_input = dclone($actor);
    $unknown_input->{interface}{inputs}[1] = {name => 'data', type => 'unresolved', width => 1};
    $scope = record_actor_scope(actor => $unknown_input);
    is_deeply($scope->{data}, {role => 'input', type_spec => undef},
        'unresolved actor input retains role without its placeholder width');
    refuses(sub {reference($scope, 'data', 'write')}, qr/cannot write declared input 'data'/,
        'unknown type cannot erase known input role');
    my $collision = $parser->parse_source($source =~ s/\(local count/\(local data/r, 'local-collision.isf');
    refuses(sub {FSM::Scheduler::ISF->new->lower($collision)},
        qr/collides with interface port 'data'/, 'projection does not admit explicit local pin collisions');
};

subtest 'drive parameter names mask records without inferred type facts' => sub {
    my $scope = record_drive_scope(actor => $actor, drive => $actor->{drives}{publish});
    is_deeply($scope->{packet}, {role => 'local', type_spec => undef}, 'untyped parameter is unknown');
    is(reference($scope, 'packet.payload'), undef, 'parameter cannot inherit actor record layout');
    is(reference($scope, 'seen')->{width}, 8, 'unshadowed actor output retains actual width');
    $scope = record_drive_scope(actor => $actor, drive => {params => ['data'], body => []});
    is_deeply($scope->{data}, {role => 'local', type_spec => undef}, 'parameter masks actor role as well as type');
};

subtest 'scopes add no inferred declarations and detach from actor facts' => sub {
    my $before = $json->encode($actor);
    my $tx = dclone($actor->{transactions}[1]);
    push @{$tx->{clauses}}, ['set', 'data', 0], ['set', 'invented', 1];
    my $scope = record_transaction_scope(actor => $actor, transaction => $tx);
    is($scope->{data}{role}, 'input', 'assignment does not redefine actor input');
    ok(!exists($scope->{invented}), 'assignment target is not a declaration');
    $scope->{packet}{type_spec}{members}{payload}{width} = 999;
    $scope->{data}{role} = 'local';
    is($json->encode($actor), $before, 'mutating projection leaves complete actor unchanged');
    is(record_actor_scope(actor => $actor)->{packet}{type_spec}{members}{payload}{width}, 6,
        'fresh projection does not reuse mutated output');
};

subtest 'imported alias and prepared record pin keep actual resolved facts' => sub {
    my $work = tempdir(CLEANUP => 1);
    open my $file, '>', "$work/shared.fsm" or die $!;
    print {$file} '(?pkg:shared (+types (type frame (record (header (bits 2)) '
        . '(payload (signed (four_state (bits 6))))))))';
    close $file or die $!;
    my $imported = $parser->parse_source('(actor imported (imports (package shared))'
        . ' (interface (output done)) (storage (var value (type shared.frame)))'
        . ' (transaction main (complete done)))', "$work/imported.isf");
    is_deeply(record_actor_scope(actor => $imported)->{value}{type_spec},
        record_actor_scope(actor => $actor)->{packet}{type_spec}, 'local and imported resolved identity matches');
    my $prepared = dclone($imported);
    $prepared->{interface}{inputs} = [dclone($prepared->{storage}[0])];
    my $scope = record_actor_scope(actor => $prepared);
    is($scope->{value}{role}, 'input', 'supplied resolved record declaration retains input role');
    refuses(sub {reference($scope, 'value.payload', 'write')}, qr/cannot write declared input 'value.payload'/,
        'prepared input leaf cannot become a write');
    refuses(sub {$parser->parse_source('(actor refused (types (type frame (record (x bit))))'
        . ' (interface (output value (type frame)) (output done))'
        . ' (transaction main (set value.x 1) (complete done)))', 'field-refused.isf')},
        qr/record output field writes are not yet admitted/, 'authored record output field writer stays refused');
};

subtest 'scope preparation leaves complete parser and scheduled products unchanged' => sub {
    my $safe = $parser->parse_source($source, 'scope-controls.isf');
    my $before_actor = $json->encode($safe);
    my $before_lowered = $json->encode(FSM::Scheduler::ISF->new->lower(dclone($safe)));
    record_actor_scope(actor => $safe);
    record_transaction_scope(actor => $safe, transaction => $_) for @{$safe->{transactions}};
    record_drive_scope(actor => $safe, drive => $_) for values %{$safe->{drives}};
    is($json->encode($safe), $before_actor, 'complete parsed actor unchanged');
    is($json->encode(FSM::Scheduler::ISF->new->lower(dclone($safe))), $before_lowered,
        'complete scheduled object and actual emitted file bytes unchanged');
};

subtest 'malformed declaration facts fail without accidental fallback' => sub {
    my $bad = dclone($actor);
    $bad->{interface}{outputs}[0]{name} = 'start';
    refuses(sub {record_actor_scope(actor => $bad)}, qr/duplicate port 'start'/, 'duplicate interface role');
    $bad = dclone($actor);
    $bad->{storage}[0]{width} = 9;
    refuses(sub {record_actor_scope(actor => $bad)}, qr/resolved type disagrees with declared width/,
        'mismatched declared packed width');
    refuses(sub {record_drive_scope(actor => $actor, drive => {params => ['bad.name']})},
        qr/drive parameter requires an identifier/, 'invalid parameter root');
    refuses(sub {record_actor_scope(actor => $actor, extra => 1)}, qr/unknown scope argument/,
        'closed helper arguments');
};

done_testing;

source_snapshots.t/1988-isf-record-port-context-gates.t:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use Storable qw(dclone);
use JSON::PP;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Support::ISFRecordPortContexts qw(validate_actor_record_contexts);

my $parser = FSM::Adapter::ISF->new;
my $json = JSON::PP->new->canonical;
my $source = <<'ISF';
(actor contexts
  (types (type frame (record (flag bit) (data (signed (four_state (bits 7))))))
    (type alias frame) (type other (record (flag bit) (data (bits 7)))))
  (enums (mode (IDLE 0) (BUSY 1)))
  (interface (input start) (input scalar (width 8)) (output seen (width 8)) (output done))
  (storage (var packet (type frame)) (var held (type alias)) (var mismatch (type other)))
  (transaction main (on start) (set held packet) (set seen packet.data) (complete done)))
ISF
my $original = $parser->parse_source($source, 'record-context-controls.isf');
my $prepared = dclone($original);
my $port = shift @{$prepared->{storage}};
push @{$prepared->{interface}{inputs}}, {map {$_ => $port->{$_}} qw(name width type type_spec)};

sub transaction {
    my (@clauses) = @_;
    my $actor = dclone($prepared);
    $actor->{transactions}[0]{clauses} = \@clauses;
    return $actor;
}
sub rules {
    my ($guard, @actions) = @_;
    my $actor = transaction();
    $actor->{rules} = [{name => 'copy', when => ['when', $guard], actions => \@actions}];
    return $actor;
}
sub drives {
    my ($params, @body) = @_;
    my $actor = transaction();
    $actor->{drives} = {publish => {params => $params, body => \@body}};
    return $actor;
}
sub accepts {
    my ($actor, $name) = @_;
    my $before = $json->encode($actor);
    my $ok = eval {validate_actor_record_contexts(actor => $actor); 1};
    ok($ok, "$name validates") or diag((split /\n/, $@)[0]);
    is($json->encode($actor), $before, "$name leaves complete actor unchanged");
}
sub refuses {
    my ($actor, $pattern, $name) = @_;
    my $before = $json->encode($actor);
    my $ok = eval {validate_actor_record_contexts(actor => $actor); 1};
    my ($line) = split /\n/, $@;
    ok(!$ok, "$name refuses");
    like($line // '', $pattern, "$name names its first-line cause");
    is($json->encode($actor), $before, "$name leaves complete actor unchanged");
}

subtest 'selected transaction scalar contexts retain scalar leaves' => sub {
    accepts(transaction(['set', 'seen', 'packet.data']), 'set scalar leaf');
    accepts(transaction(['update', 'seen', ['+', 'packet.data[3:1]', 'scalar']]), 'update expression and leaf slice');
    for my $head (qw(when while until)) {
        accepts(transaction([$head, ['==', 'packet.flag', 1], ['set', 'seen', 'packet.data']]), "$head body");
        accepts(transaction([$head, '!packet.flag', ['set', 'seen', 1]]), "$head compact negation");
        accepts(transaction([$head, '1==packet.flag', ['set', 'seen', 1]]), "$head compact comparison");
    }
    accepts(transaction(['repeat', 2, ['when', 'packet.flag', ['set', 'seen', 'packet.data']]]), 'repeat nested body');
    accepts(transaction(['switch', 'packet.data', ['packet.flag', ['set', 'seen', 'packet.data']],
        ['default', ['set', 'seen', 0]]]), 'switch selector and branch values');
};

subtest 'whole record copies consume strict type and declared roles' => sub {
    accepts(transaction(['set', 'held', 'packet']), 'set input to equivalent alias storage');
    accepts(transaction(['update', 'held', 'packet']), 'update whole copy');
    accepts(rules('packet.flag', ['set', 'held', 'packet']), 'rule whole copy');
    accepts(rules(['==', 'packet.flag', 1], ['held', 'packet']), 'rule shorthand whole copy');
    accepts(drives([], ['held', 'packet']), 'named drive whole copy');
    accepts(transaction(['drive', 'inline', ['held', 'packet']]), 'inline drive whole copy');
    for my $head (qw(set update)) {
        refuses(transaction([$head, 'mismatch', 'packet']), qr/requires the same resolved record type/,
            "$head equal-width signed/state mismatch");
        refuses(transaction([$head, 'seen', 'packet']), qr/whole record port copy requires declared record roots/,
            "$head whole record to scalar");
        refuses(transaction([$head, 'held.data', 'packet']), qr/whole record port copy requires declared record roots/,
            "$head whole record to scalar leaf");
    }
};

subtest 'rule and drive scalar reads keep selected scope' => sub {
    accepts(rules('packet.flag', ['set', 'seen', ['+', 'packet.data', 'scalar']]), 'rule scalar guard and RHS');
    accepts(rules(['==', 'packet.data', 3], ['seen', 'packet.data']), 'rule expression guard and shorthand RHS');
    accepts(drives([], ['seen', ['+', 'packet.data', 'scalar']]), 'named drive leaf expression');
    accepts(transaction(['drive', 'inline', ['seen', 'packet.data']]), 'labeled inline drive');
    accepts(transaction(['drive', ['seen', 'packet.data']]), 'unlabeled inline drive');
    my $actor = transaction(['drive', 'publish', ['+', 'packet.data', 'scalar']]);
    $actor->{drives} = {publish => {params => ['value'], body => [['seen', 'value']]}};
    accepts($actor, 'named drive scalar actual');
    accepts(drives(['packet'], ['seen', 'packet']), 'untyped drive parameter masks actor record');
};

subtest 'scalar-only drive parameters reject members without inventing widths' => sub {
    for my $name (qw(packet value)) {
        accepts(drives([$name], ['seen', $name]), "$name bare scalar parameter");
        accepts(drives([$name], ['seen', "${name}[0]"]), "$name scalar slice remains delegated");
        for my $token ("$name.member", "$name.payload.data", "$name.member[0]",
            "${name}[0].member", "${name}[1:0].member") {
            refuses(drives([$name], ['seen', $token]), qr/member_on_non_record/,
                "$token parameter RHS");
            refuses(drives([$name], ['seen', ['+', 1, $token]]), qr/member_on_non_record/,
                "$token nested parameter RHS");
            refuses(drives([$name], [$token, 0]), qr/member_on_non_record/,
                "$token parameter target");
        }
    }
    my $shadow = drives(['packet'], ['seen', 'packet.data']);
    $shadow->{enum_symbols}{local}{packet} = {data => 1};
    refuses($shadow, qr/member_on_non_record/, 'enum cannot lend a masked record layout');
    my $namespaces = drives(['mode', 'shared'], ['seen', 'mode.BUSY'], ['seen', 'shared.LIMIT']);
    $namespaces->{constant_symbols}{packages}{shared} = {LIMIT => 1};
    accepts($namespaces, 'existing local enum and package namespaces retain their owner');
};

subtest 'every selected scalar context rejects whole record ports' => sub {
    for my $value ('packet', '!packet', 'packet==1', '1==packet', ['+', 1, 'packet']) {
        for my $head (qw(when while until)) {
            refuses(transaction([$head, $value, ['set', 'seen', 1]]), qr/requires a scalar value.*whole record port/,
                "$head whole record condition " . $json->encode($value));
        }
        refuses(transaction(['switch', $value, [0, ['set', 'seen', 1]]]),
            qr/requires a scalar value.*whole record port/, 'whole record switch selector');
        refuses(rules($value, ['seen', 1]), qr/requires a scalar value.*whole record port/, 'whole record rule guard');
        my $actor = transaction(['drive', 'publish', $value]);
        $actor->{drives} = {publish => {params => ['value'], body => [['seen', 'value']]}};
        refuses($actor, qr/requires a scalar value.*whole record port/, 'whole record drive actual');
    }
    refuses(transaction(['switch', 'scalar', ['packet', ['set', 'seen', 1]]]),
        qr/switch branch value requires a scalar value/, 'whole record switch branch');
    refuses(transaction(['set', 'seen', ['+', 1, 'packet']]), qr/requires a scalar value.*whole record port/,
        'whole record arithmetic RHS');
    refuses(transaction(['set', 'seen', ['packet.data', 1]]), qr/operator cannot use declared aggregate reference/,
        'leaf reference in expression operator position');
};

subtest 'known input targets and invalid paths fail in each assignment family' => sub {
    for my $target ('packet', 'packet.data') {
        for my $actor (
            transaction(['set', $target, 0]), transaction(['update', $target, 0]),
            rules('start', ['set', $target, 0]), rules('start', [$target, 0]),
            drives([], [$target, 0]), transaction(['drive', 'inline', [$target, 0]]),
            rules('start', ['pulse', $target]),
        ) {
            refuses($actor, qr/cannot write declared input '\Q$target\E'/, "input target $target");
        }
    }
    refuses(transaction(['set', 'seen', 'packet.missing']), qr/invalid declared path 'packet.missing': unknown_member/,
        'unknown declared record member');
    refuses(transaction(['set', 'seen', 'packet.data[7]']), qr/scalar_index_out_of_range/,
        'leaf index outside resolved width');
    my $shadow = transaction(['set', 'seen', 'packet.data']);
    $shadow->{transactions}[0]{ports} = {inputs => [], outputs => [{name => 'packet', width => 3}]};
    refuses($shadow, qr/member_on_non_record/, 'scalar formal prevents outer record lookup');
    $shadow = transaction(['set', 'seen', 'packet.data']);
    $shadow->{transactions}[0]{ports} = {inputs => [], outputs => [{name => 'packet', width => 1, type => 'unresolved'}]};
    accepts($shadow, 'unresolved formal is delegated without outer type borrowing');
};

subtest 'unselected source contexts do not inherit leaf-read permission' => sub {
    for my $clause (
        ['wait', 'packet.data'], ['repeat', 'packet.data', ['set', 'seen', 1]],
        ['on', 'packet.flag'],
    ) {
        refuses(transaction($clause), qr/does not admit record port reference/,
            'unselected ' . $clause->[0]);
    }
};

subtest 'legacy storage and unrelated tokens remain under existing validators' => sub {
    accepts(dclone($original), 'actual admitted record storage and scalar-port source');
    my $actor = transaction(['set', 'held', 'mismatch'], ['set', 'seen', 'mode.BUSY'],
        ['when', ['==', 'shared.LIMIT', "scalar'8"], ['set', 'seen', 1]],
        ['when', ['state_active', 'packet'], ['set', 'seen', 1]]);
    accepts($actor, 'storage-only packed transfers and enum/package/scalar annotations');
    accepts(transaction(['set', 'seen', 'unknown.member']), 'unknown token remains delegated');
    my $enum_pin = $parser->parse_source('(actor enum_pin (enums (mode (BUSY 1)))'
        . ' (interface (input mode) (output seen)) (transaction main (set seen mode.BUSY)))', 'enum-pin.isf');
    accepts($enum_pin, 'actual admitted enum namespace sharing a scalar pin name');
    my $shadow = transaction(['set', 'seen', 'packet.data']);
    $shadow->{enum_symbols}{local}{packet} = {data => 1};
    $shadow->{transactions}[0]{ports} = {inputs => [], outputs => [{name => 'packet', width => 3}]};
    refuses($shadow, qr/member_on_non_record/,
        'enum token cannot supply a shadowed actor aggregate member');
    my $before = $json->encode($original);
    my $lowered = $json->encode(FSM::Scheduler::ISF->new->lower(dclone($original)));
    validate_actor_record_contexts(actor => $original);
    is($json->encode($original), $before, 'complete actual parsed actor unchanged');
    is($json->encode(FSM::Scheduler::ISF->new->lower(dclone($original))), $lowered,
        'complete scheduled object and emitted source bytes unchanged');
};

done_testing;

source_snapshots.t/1989-isf-record-port-root-classificati:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Storable qw(dclone);
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Adapter::ISF;
use FSM::Support::ISFRecordPortScopes qw(record_context_scope record_reference_root_kind);
use FSM::Support::ISFRecordPortValues qw(record_value_reference);
use FSM::Support::ISFRecordPortContexts qw(validate_actor_record_contexts);

my $parser = FSM::Adapter::ISF->new;
my $json = JSON::PP->new->canonical;
my $actor = $parser->parse_source(<<'ISF', 'root-controls.isf');
(actor roots
  (params (W 8)) (constants (K 1))
  (types (type frame (record (flag bit) (payload (bits 7)))) (type alias frame))
  (enums (mode (BUSY 1)) (packet (payload 1)))
  (interface (input start) (input mode) (output seen (width W)) (output done))
  (storage (var packet (type frame)) (var held (type alias)))
  (drive (publish packet) (seen packet))
  (transaction worker (ports (output packet (width 3)))
    (local count (width 2)) (set packet 1))
  (transaction main (on start) (set seen packet.payload) (complete done)))
ISF

sub classify {
    my ($context, $token) = @_;
    return record_reference_root_kind(context => $context, token => $token);
}
sub refuses {
    my ($run, $pattern, $name) = @_;
    my $ok = eval {$run->(); 1};
    my ($line) = split /\n/, $@;
    ok(!$ok, "$name refuses");
    like($line // '', $pattern, "$name names its first-line cause");
}

subtest 'actual declarations produce one coherent consumer projection' => sub {
    my $context = record_context_scope(actor => $actor);
    is_deeply([sort keys %$context], [qw(aggregate_roots enum_exclusion_roots namespaces roots rule_declared_roots scalar_parameter_roots)],
        'complete projection has only the selected consumer maps');
    is_deeply($context->{scalar_parameter_roots}, {}, 'outer actor statics do not invent lexical drive masks');
    is_deeply([sort keys %{$context->{roots}}], [qw(done held mode packet seen start)],
        'values are declarations rather than inferred assignment/constant names');
    is_deeply([sort keys %{$context->{aggregate_roots}}], [qw(held packet)], 'actor aggregates retain resolved identities');
    is_deeply($context->{enum_exclusion_roots}, {held => 1, packet => 1},
        'aggregate roots prevent namespace interpretation');
    is_deeply($context->{namespaces}, {mode => 1, packet => 1}, 'actual local enum families remain namespaces');
    is_deeply([sort keys %{$context->{rule_declared_roots}}], [qw(K W clk done held mode packet rst_n seen start)],
        'independent rule-declaration witness includes actor statics and system pins');
    is(classify($context, 'mode.BUSY'), 'namespace', 'scalar pin can share enum family name');
    is(classify($context, 'packet.payload'), 'declaration', 'declared record wins over same-named enum family');
    is(classify($context, 'packet.missing'), 'declaration', 'unknown member remains with declared path validator');
    is(classify($context, 'mode.MISSING'), 'namespace', 'unknown enum member remains with enum validator');
    is(classify($context, 'seen[3:0]'), 'declaration', 'scalar bit/slice root retains declaration');
    is(classify($context, 'not_declared.member'), undef, 'unknown namespace does not invent a declaration');
    is(classify($context, 17), undef, 'literal is not a declaration reference');
};

subtest 'nearest formal and local scopes suppress borrowed aggregate namespaces' => sub {
    my $context = record_context_scope(actor => $actor, transaction => $actor->{transactions}[0]);
    is_deeply([sort keys %{$context->{aggregate_roots}}], ['held'], 'scalar formal removes outer aggregate from traversal roots');
    is_deeply($context->{enum_exclusion_roots}, {held => 1, packet => 1},
        'shadowed outer record remains excluded from enum fallback');
    is(classify($context, 'packet.payload'), 'declaration', 'formal path is not borrowed enum token');
    refuses(sub {record_value_reference(scope => $context->{roots}, token => 'packet.payload',
        access => 'read', context => 'formal path')}, qr/member_on_non_record/, 'scalar formal member access');
    is_deeply([@{record_value_reference(scope => $context->{roots}, token => 'packet[2:1]',
        access => 'read', context => 'formal slice')}{qw(width low high)}], [2, 1, 2],
        'formal slice uses its independent local width');
    ok(exists($context->{roots}{count}) && !exists($context->{rule_declared_roots}{count}),
        'transaction local cannot become an actor rule read operand');
    my $unknown = dclone($actor->{transactions}[0]);
    $unknown->{ports}{outputs}[0] = {name => 'packet', width => 1, type => 'unresolved'};
    $context = record_context_scope(actor => $actor, transaction => $unknown);
    is($context->{roots}{packet}{type_spec}, undef, 'unresolved type stays unknown');
    is(classify($context, 'packet.payload'), 'declaration', 'unresolved formal still masks namespace and outer layout');
    is(record_value_reference(scope => $context->{roots}, token => 'packet.payload', access => 'read',
        context => 'unknown formal'), undef, 'unknown fact is delegated without invented type');
};

subtest 'drive and supplied record pin scopes retain real declaration roles' => sub {
    my $context = record_context_scope(actor => $actor, drive => $actor->{drives}{publish});
    is_deeply($context->{scalar_parameter_roots}, {packet => 1}, 'explicit drive formal supplies its exact scalar mask');
    is_deeply($context->{roots}{packet}, {role => 'local', type_spec => undef}, 'parameter masks outer record');
    is(classify($context, 'packet.payload'), 'declaration', 'untyped parameter cannot borrow enum member');
    my $prepared = dclone($actor);
    my $packet = shift @{$prepared->{storage}};
    push @{$prepared->{interface}{inputs}}, {map {$_ => $packet->{$_}} qw(name width type type_spec)};
    $context = record_context_scope(actor => $prepared);
    is($context->{roots}{packet}{role}, 'input', 'supplied record declaration keeps input role');
    is_deeply([sort keys %{$context->{aggregate_roots}}], [qw(held packet)], 'record pins and storage share resolved traversal facts');
    refuses(sub {record_value_reference(scope => $context->{roots}, token => 'packet.payload',
        access => 'write', context => 'input field')}, qr/cannot write declared input/, 'declared input field');
};

subtest 'package namespace and named-domain rules retain existing owners' => sub {
    my $supplied = dclone($actor);
    $supplied->{enum_symbols}{packages} = {shared => {mode => {BUSY => 1}}};
    $supplied->{constant_symbols}{packages} = {limits => {MAX => {kind => 'scalar', payload => 8}}};
    push @{$supplied->{interface}{inputs}}, {name => 'shared', width => 1}, {name => 'limits', width => 1};
    my $context = record_context_scope(actor => $supplied);
    is(classify($context, 'shared.mode.BUSY'), 'namespace', 'package enum is not a scalar-pin member');
    is(classify($context, 'limits.MAX'), 'namespace', 'package constant remains with existing static/value validator');
    my $work = tempdir(CLEANUP => 1);
    open my $file, '>', "$work/shared.fsm" or die $!;
    print {$file} '(?pkg:shared (+types (type frame (record (flag bit) (payload (bits 7)))))'
        . ' (+enums (mode (BUSY 1))) (+constants (MAX 8)))';
    close $file or die $!;
    my $imported = $parser->parse_source('(actor imported (imports (package shared))'
        . ' (interface (input shared) (output done)) (storage (var frame (type shared.frame)))'
        . ' (transaction main (complete done)))', "$work/imported.isf");
    $context = record_context_scope(actor => $imported);
    is(classify($context, 'shared.mode.BUSY'), 'namespace', 'actual imported enum remains in package namespace');
    is(classify($context, 'shared.MAX'), 'namespace', 'actual imported constant retains its package owner');
    is_deeply($context->{aggregate_roots}{frame}, record_context_scope(actor => $actor)->{aggregate_roots}{packet},
        'actual imported aggregate retains equivalent resolved traversal facts');
    my $named = $parser->parse_source('(actor named (clock-domains'
        . ' (domain core (clock core_clk) (reset (core_rst async active_low)) :default)'
        . ' (domain aux (clock aux_clk) (reset (aux_rst sync active_high))))'
        . ' (interface (input start) (output done)) (transaction main (on start) (complete done)))',
        'named-rule-roots.isf');
    $context = record_context_scope(actor => $named);
    is_deeply([sort keys %{$context->{rule_declared_roots}}], [qw(aux_clk aux_rst core_clk core_rst done start)],
        'independent named-domain clock/reset declaration witness');
    is_deeply([sort keys %{$context->{roots}}], [qw(done start)], 'system names are not invented value/type roots');
};

subtest 'fresh copied facts stay detached across every consumer map' => sub {
    for my $kind (qw(actor transaction drive)) {
        my $fresh = dclone($actor);
        my %selection;
        $selection{transaction} = $fresh->{transactions}[0] if $kind eq 'transaction';
        $selection{drive} = $fresh->{drives}{publish} if $kind eq 'drive';
        my $before = $json->encode($fresh);
        my $context = record_context_scope(actor => $fresh, %selection);
        is($json->encode($fresh), $before, 'first complete projection preserves caller JSON kinds');
        $context->{aggregate_roots}{held}{members}{payload}{width} = 999;
        $context->{rule_declared_roots}{invented} = 1;
        $context->{namespaces}{invented} = 1;
        is($json->encode($fresh), $before, 'mutating any projection leaves source facts unchanged');
        is($context->{roots}{held}{type_spec}{members}{payload}{width}, 7,
            'traversal map is detached from value map within projection');
    }
};

subtest 'closed context selection and current source admission remain unchanged' => sub {
    refuses(sub {record_context_scope(actor => $actor, transaction => $actor->{transactions}[0],
        drive => $actor->{drives}{publish})}, qr/cannot select both transaction and drive/, 'ambiguous lexical selection');
    refuses(sub {record_context_scope(actor => $actor, extra => 1)}, qr/unknown scope argument/, 'unknown context argument');
    refuses(sub {record_reference_root_kind(context => {}, token => 'packet')},
        qr/requires declaration context/, 'missing classification maps');
    my $before = $json->encode($actor);
    ok(validate_actor_record_contexts(actor => $actor), 'existing contextual consumer uses common projection');
    is($json->encode($actor), $before, 'complete parsed source unchanged');
    refuses(sub {$parser->parse_source('(actor refused (types (type frame (record (data bit))))'
        . ' (interface (output packet (type frame))) (transaction main (set packet.data 1)))', 'refused.isf')},
        qr/record output field writes are not yet admitted/, 'authored record output field writer still refused');
};

done_testing;

source_snapshots.t/1990-isf-record-port-sample-facts.t:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Storable qw(dclone);
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Support::ISFRecordPortSamples qw(record_transaction_samples record_sample_type_products);

my $parser = FSM::Adapter::ISF->new;
my $json = JSON::PP->new->canonical;
my $source = <<'ISF';
(actor samples
  (types
    (type leaf (record (count (four_state (signed (bits 3)))) (ready (two_state bit))))
    (type frame (record (tag (bits 2)) (nested leaf) (lanes (list bit (bits 2)))))
    (type alias frame))
  (enums (mode (BUSY 1)))
  (interface (input start) (input mode) (output seen (width 3)) (output done))
  (storage (var packet (type frame) (reset 0)) (var held (type alias)))
  (transaction worker (ports (output packet (width 2)))
    (local count (width 3)) (set packet 1))
  (transaction main (on start) (set seen packet.nested.count) (complete done)))
ISF
my $actor = $parser->parse_source($source, 'sample-facts.isf');

sub sample_plan {
    my ($a, $clauses, $tx) = @_;
    $tx = dclone($tx || $a->{transactions}[1]);
    $tx->{clauses} = $clauses;
    return record_transaction_samples(actor => $a, transaction => $tx);
}
sub sample { ['sample', $_[0], 'as', $_[1]] }
sub refuses {
    my ($run, $pattern, $name) = @_;
    my $ok = eval {$run->(); 1};
    my ($line) = split /\n/, $@;
    ok(!$ok, "$name refuses");
    like($line // '', $pattern, "$name names the first-line cause");
}
sub render {
    my ($value) = @_;
    return ref($value) eq 'ARRAY' ? '(' . join(' ', map {render($_)} @$value) . ')' : $value;
}

subtest 'independent packed-layout and scalar-property witnesses' => sub {
    my $p = sample_plan($actor, [
        ['on', 'start', sample('packet.nested.count', 'count_q')],
        sample('packet.nested.ready', 'ready_q'),
        ['when', 'mode', sample('packet.lanes[1][1:0]', 'lane_q')],
        ['switch', 'mode', [1, sample('packet.tag', 'tag_q')]],
        ['repeat', 2, sample('count_q', 'again_q')],
    ]);
    is_deeply([map {[$_->{source}, $_->{alias}, $_->{record_derived}]} @{$p->{samples}}],
        [['packet.nested.count','count_q',1], ['packet.nested.ready','ready_q',1],
         ['packet.lanes[1][1:0]','lane_q',1], ['packet.tag','tag_q',1], ['count_q','again_q',1]],
        'entry/body/branches preserve authored order and chained record-leaf provenance');
    is_deeply([map {[@{$_->{reference}}{qw(width low high)}]} @{$p->{samples}}[0..3]],
        [[3,4,6], [1,3,3], [2,0,1], [2,7,8]], 'independent nine-bit packed layout');
    is_deeply($p->{bindings}{count_q}, {role=>'local', type_spec=>{kind=>'bits',width=>3,signed=>1,state_model=>'four_state'}},
        'signed four-state scalar facts survive sampling');
    is_deeply($p->{bindings}{ready_q}, {role=>'local', type_spec=>{kind=>'bit',width=>1,signed=>0,state_model=>'two_state'}},
        'bit kind and explicit two-state property survive');
    is_deeply($p->{bindings}{again_q}, $p->{bindings}{count_q}, 'explicit sampled alias has the same detached scalar type');
    ok(!exists($p->{bindings}{lane_q}{type_spec}{state_model}), 'unspecified state model stays unspecified');
};

subtest 'actual lexical masks and namespaces do not lend a record layout' => sub {
    my $p = sample_plan($actor, [['local','count',['width',3]], sample('packet[1:0]', 'p_q'), sample('count', 'c_q')], $actor->{transactions}[0]);
    is_deeply([map {$_->{reference}{width}} @{$p->{samples}}], [2,3], 'formal and explicit local widths are nearest');
    is_deeply($p->{record_aliases}, {}, 'scalar shadows do not invent record provenance');
    refuses(sub {sample_plan($actor, [sample('packet.nested.count','q')], $actor->{transactions}[0])},
        qr/member_on_non_record/, 'scalar formal member');
    my $unknown = dclone($actor->{transactions}[0]);
    $unknown->{ports}{outputs}[0] = {name=>'packet',width=>1,type=>'unresolved'};
    $p = sample_plan($actor, [sample('packet.nested.count','q')], $unknown);
    is($p->{bindings}{q}{type_spec}, undef, 'unknown formal masks outer record without placeholder inference');
    $p = sample_plan($actor, [sample('mode.BUSY','enum_q'), sample('not_declared','packet'), sample('packet.nested.count','q')]);
    is($p->{bindings}{enum_q}{type_spec}, undef, 'enum token retains existing namespace/static validation owner');
    is($p->{bindings}{q}{type_spec}, undef, 'explicit unknown sample alias masks old record facts');
};

subtest 'whole aggregates paths roles and inconsistent aliases fail precisely' => sub {
    for my $case (
        ['packet', qr/whole record/], ['packet.nested', qr/requires a scalar leaf/],
        ['packet.lanes', qr/requires a scalar leaf/], ['packet.missing', qr/unknown_member/],
        ['packet.lanes[2]', qr/index_out_of_range/],
    ) {
        refuses(sub {sample_plan($actor, [sample($case->[0],'q')])}, $case->[1], $case->[0]);
    }
    for my $alias (qw(packet held seen count)) {
        my $tx = dclone($actor->{transactions}[1]);
        unshift @{$tx->{clauses}}, ['local','count',['width',3]];
        refuses(sub {sample_plan($actor, [@{$tx->{clauses}},sample('packet.nested.count',$alias)],$tx)},
            qr/collides with a declaration/, "private alias $alias");
    }
    refuses(sub {sample_plan($actor, [sample('packet.tag','start')])}, qr/cannot write declared input/, 'input alias');
    my $prepared = dclone($actor);
    my $packet = shift @{$prepared->{storage}};
    push @{$prepared->{interface}{inputs}}, {map {$_=>$packet->{$_}} qw(name width type type_spec)};
    my $read = sample_plan($prepared, [sample('packet.nested.count','q')]);
    is($read->{samples}[0]{reference}{role}, 'input', 'supplied record input retains readable declared role');
    refuses(sub {sample_plan($prepared, [sample('packet.nested.count','packet')])},
        qr/cannot write declared input/, 'supplied record input target');
    refuses(sub {sample_plan($actor, [sample('packet.tag','q'),sample('packet.nested.count','q')])},
        qr/requires the same resolved scalar type/, 'different width/type repeated sample');
    refuses(sub {sample_plan($actor, [sample('packet.nested.count','q'),sample('not_declared','q')])},
        qr/requires the same resolved scalar type/, 'unknown repeated sample');
    my $collision = dclone($actor);
    push @{$collision->{interface}{inputs}}, {name=>'scalar',width=>2};
    refuses(sub {sample_plan($collision, [sample('scalar','held'),sample('packet.tag','held')])},
        qr/collides with a declaration/, 'prior scalar sample cannot erase an authored storage collision');
    my $p = sample_plan($actor, [sample('packet.tag','q'),sample('held.tag','q')]);
    is(scalar(@{$p->{samples}}), 2, 'same resolved scalar type permits repeated explicit captures');
    refuses(sub {sample_plan($actor, [['sample','packet.tag','as',['q']]])}, qr/requires '\(sample scalar as identifier\)'/, 'malformed sample');
};

subtest 'private core scalar type products are deterministic and collision-safe' => sub {
    my $p = sample_plan($actor, [sample('packet.nested.count','count_q'),sample('packet.nested.ready','ready_q'),sample('packet.tag','tag_q')]);
    my %args = (bindings=>$p->{bindings}, record_aliases=>$p->{record_aliases}, reserved_names=>['_isf_sample_count_q','_isf_sample_count_q_1']);
    my $types = record_sample_type_products(%args);
    is_deeply($types, {
        type_declarations=>[
            ['type','_isf_sample_count_q_2',['four_state',['signed',['bits',3]]]],
            ['type','_isf_sample_ready_q',['two_state','bit']],
            ['type','_isf_sample_tag_q',['bits',2]],
        ],
        signal_type_refs=>{count_q=>'_isf_sample_count_q_2',ready_q=>'_isf_sample_ready_q',tag_q=>'_isf_sample_tag_q'},
        signal_widths=>{count_q=>3,ready_q=>1,tag_q=>2},
    }, 'independently authored complete carrier product has no reset/default leakage');
    is_deeply(record_sample_type_products(%args), $types, 'same reserved names produce the same declaration identity');
    my $declarations = join(' ', map {render($_)} @{$types->{type_declarations}});
    my $storage = join(' ', map {'(var '.$_.' (type '.$types->{signal_type_refs}{$_}.'))'} sort keys %{$types->{signal_type_refs}});
    my $a = $parser->parse_source('(actor type_contract (types '.$declarations.') (storage '.$storage.') (transaction main (wait 1)))', 'private-type-contract.isf');
    for my $entry (@{$a->{storage}}) {
        is_deeply($entry->{type_spec}, $p->{bindings}{$entry->{name}}{type_spec}, 'actual public type resolver reconstructs the exact selected scalar facts');
    }
    refuses(sub {record_sample_type_products(%args, extra=>1)}, qr/unknown sample argument/, 'unknown type-product argument');
    refuses(sub {record_sample_type_products(%args, record_aliases=>{count_q=>[]})}, qr/requires a local sample binding/, 'malformed record-alias fact');
};

subtest 'imported aliases and first-read caller facts are detached' => sub {
    my $work = tempdir(CLEANUP=>1);
    open my $f, '>', "$work/shared.fsm" or die $!;
    print {$f} '(?pkg:shared (+types (type frame (record (data (four_state (signed (bits 3))))))))';
    close $f or die $!;
    my $a = $parser->parse_source('(actor imported (imports (package shared)) (storage (var packet (type shared.frame))) (transaction main (wait 1)))', "$work/imported.isf");
    my $p = sample_plan($a, [sample('packet.data','q')], $a->{transactions}[0]);
    is_deeply($p->{bindings}{q}{type_spec}, {kind=>'bits',width=>3,signed=>1,state_model=>'four_state'}, 'actual imported leaf has exact scalar properties');
    my $fresh = dclone($actor);
    my $tx = dclone($fresh->{transactions}[1]);
    $tx->{clauses} = [sample('packet.nested.count','q')];
    my $before = $json->encode([$fresh,$tx]);
    $p = record_transaction_samples(actor=>$fresh,transaction=>$tx);
    is($json->encode([$fresh,$tx]), $before, 'first plan preserves complete copied caller JSON kinds');
    $p->{record_aliases}{q} = '1';
    $p->{bindings}{q}{type_spec}{width} = '3';
    $before = $json->encode($p);
    my $products = record_sample_type_products(bindings=>$p->{bindings},record_aliases=>$p->{record_aliases},reserved_names=>[]);
    is($json->encode($p), $before, 'first type projection preserves string-valued width and provenance facts');
    $products->{type_declarations}[0][2][1][1][1] = 999;
    is($json->encode($p), $before, 'mutating generated declaration does not mutate facts');
    $p->{samples}[0]{reference}{type_spec}{width} = 999;
    is($p->{bindings}{q}{type_spec}{width}, '3', 'sample reference and binding are detached sibling maps');
};

subtest 'preparation does not mutate complete currently admitted products' => sub {
    my $a = $parser->parse_source($source, 'sample-facts.isf');
    my $before = $json->encode($a);
    my $lowered = $json->encode(FSM::Scheduler::ISF->new->lower($a));
    record_transaction_samples(actor=>$a,transaction=>$a->{transactions}[1]);
    is($json->encode($a), $before, 'complete parsed object unchanged');
    is($json->encode(FSM::Scheduler::ISF->new->lower($a)), $lowered, 'complete scheduled object and emitted bytes unchanged');
    refuses(sub {$parser->parse_source('(actor refused (types (type frame (record (data bit)))) (interface (output packet (type frame))) (transaction main (set packet.data 1)))', 'field-refused.isf')},
        qr/record output field writes are not yet admitted/, 'authored record output field writer remains refused');
};

done_testing;

source_snapshots.t/1991-isf-record-port-sample-contexts.t:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Storable qw(dclone);
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Support::ISFRecordPortContexts qw(validate_actor_record_contexts);
use FSM::Support::ISFRecordPortSamples qw(actor_has_record_input record_transaction_samples);

my $parser = FSM::Adapter::ISF->new;
my $json = JSON::PP->new->canonical;
my $source = <<'ISF';
(actor contexts
  (types (type frame (record (count (four_state (signed (bits 3)))) (ready bit))))
  (interface (input start) (output seen (width 3)) (output done))
  (storage (var packet (type frame)) (var held (type frame)))
  (transaction main (on start) (set seen packet.count) (complete done)))
ISF
my $ordinary = $parser->parse_source($source, 'sample-contexts.isf');
my $prepared = dclone($ordinary);
my $packet = shift @{$prepared->{storage}};
push @{$prepared->{interface}{inputs}}, {map {$_=>$packet->{$_}} qw(name width type type_spec)};

sub sample { ['sample',$_[0],'as',$_[1]] }
sub actor_with {
    my ($clauses) = @_;
    my $a = dclone($prepared);
    $a->{transactions}[0]{clauses} = $clauses;
    return $a;
}
sub accepts {
    my ($a, $label) = @_;
    my $before = $json->encode($a);
    my $ok = eval {validate_actor_record_contexts(actor=>$a); 1};
    ok($ok, $label) or diag($@);
    is($json->encode($a), $before, "$label preserves the complete actor");
}
sub refuses {
    my ($a, $pattern, $label) = @_;
    my $before = $json->encode($a);
    my $ok = eval {validate_actor_record_contexts(actor=>$a); 1};
    my ($line) = split /\n/, $@;
    ok(!$ok, "$label refuses");
    like($line // '', $pattern, "$label has the correct first-line cause");
    is($json->encode($a), $before, "$label preserves the complete actor");
}

subtest 'selector refuses malformed facts without autovivifying callers' => sub {
    my $empty = {};
    is(actor_has_record_input(actor=>$empty), 0, 'absent interface has no known record input');
    is_deeply($empty, {}, 'selection never invents an interface');
    for my $entry (undef, 'not_a_map', []) {
        my $a = {interface=>{inputs=>[$entry]}};
        my $before = $json->encode($a);
        my $ok = eval {actor_has_record_input(actor=>$a); 1};
        ok(!$ok, 'malformed declared entry refuses');
        like((split /\n/,$@)[0] // '', qr/record-input selection requires declared input maps/, 'failure names the entry shape');
        is($json->encode($a), $before, 'first selection preserves complete malformed caller JSON');
    }
    my $a = {interface=>{inputs=>[dclone($prepared->{interface}{inputs}[1]), undef]}};
    my $before = $json->encode($a);
    my $ok = eval {actor_has_record_input(actor=>$a); 1};
    ok(!$ok, 'a valid record prefix cannot hide a malformed remaining declaration');
    like((split /\n/,$@)[0], qr/record-input selection requires declared input maps/, 'complete input inventory is validated');
    is($json->encode($a), $before, 'failed suffix validation leaves the complete caller unchanged');
};

subtest 'selected explicit entry body and control samples feed real scalar bindings' => sub {
    ok(!actor_has_record_input(actor=>$ordinary), 'ordinary scalar/storage source is outside the input consumer');
    ok(actor_has_record_input(actor=>$prepared), 'actual supplied record-input role selects the consumer');
    for my $clauses (
        [['on','start',sample('packet.count','q')],['set','seen','q']],
        [sample('packet.count','q'),['update','seen','q[2:1]']],
        [['when','start',sample('packet.count','q'),['set','seen','q']]],
        [['switch','start',[1,sample('packet.count','q'),['set','seen','q']]]],
        [['while','start',sample('packet.ready','q'),['set','done','q']]],
        [['until','start',sample('packet.ready','q'),['set','done','q']]],
        [['repeat',2,sample('packet.count','q'),['drive','inline',['seen','q']]]],
        [sample('packet.count','q'),sample('q','again'),['set','seen','again']],
    ) {
        accepts(actor_with($clauses), 'selected explicit scalar sample context');
    }
};

subtest 'sample aliases cannot erase declaration roles or invalid scalar shapes' => sub {
    refuses(actor_with([sample('packet.count','q'),['set','seen','q.member']]),
        qr/member_on_non_record/, 'sample alias is a scalar rather than an inferred record');
    refuses(actor_with([sample('packet.count','q'),['set','seen','q[3]']]),
        qr/scalar_index_out_of_range/, 'sample alias has exact leaf width');
    refuses(actor_with([sample('packet','q')]), qr/whole record/, 'whole record snapshot');
    refuses(actor_with([sample('packet.count','packet')]), qr/cannot write declared input/, 'input target');
    refuses(actor_with([sample('packet.count','held')]), qr/collides with a declaration/, 'storage target');
    refuses(actor_with([sample('packet.missing','q')]), qr/unknown_member/, 'missing input member');
    refuses(actor_with([sample('packet.count','q'),sample('packet.ready','q')]),
        qr/requires the same resolved scalar type/, 'inconsistent repeated captures');
    refuses(actor_with([sample('q','earlier'),sample('packet.count','q')]),
        qr/uses record-derived alias 'q' before its declaration/, 'unresolved forward sample chain');
};

subtest 'nearest formals locals and explicit unknown aliases mask input layouts' => sub {
    my $a = actor_with([sample('packet[1:0]','q'),['set','seen','q']]);
    $a->{transactions}[0]{ports} = {inputs=>[],outputs=>[{name=>'packet',width=>2}]};
    accepts($a, 'scalar formal has its own sampled width and writable role');
    $a->{transactions}[0]{clauses} = [sample('packet.count','q')];
    refuses($a, qr/member_on_non_record/, 'scalar formal cannot borrow input layout');
    $a->{transactions}[0]{ports}{outputs}[0] = {name=>'packet',width=>1,type=>'unresolved'};
    accepts($a, 'unknown formal remains delegated');
    $a = actor_with([['local','local_word',['width',2]],sample('local_word','q'),['set','seen','q[1:0]']]);
    accepts($a, 'explicit local AST has its own sampled width');
    $a = actor_with([sample('not_declared','held'),sample('held.member','q')]);
    accepts($a, 'unknown sampled alias masks outer storage rather than borrowing its record type');
};

subtest 'port consumer delegates established packed storage and namespace samples' => sub {
    my $a = actor_with([sample('held','packed_q'),['set','held','packed_q']]);
    my $p = record_transaction_samples(actor=>$a,transaction=>$a->{transactions}[0],port_only=>1);
    is($p->{bindings}{packed_q}{type_spec}, undef, 'packed storage width/inference remains with its existing owner');
    is_deeply($p->{record_aliases}, {}, 'storage sampling gains no new record-input type carrier');
    accepts($a, 'existing storage-only packed sample and transfer context remains delegated');
    $a->{enum_symbols}{local} = {mode=>{BUSY=>1}};
    $a->{transactions}[0]{clauses} = [sample('mode.BUSY','enum_q')];
    accepts($a, 'enum sample remains with namespace/static-value validation');
    my $before = $json->encode($a);
    my $ok = eval {record_transaction_samples(actor=>$a,transaction=>$a->{transactions}[0],port_only=>[]); 1};
    ok(!$ok, 'malformed selection refuses');
    like((split /\n/,$@)[0], qr/port-only selection must be binary/, 'closed selection diagnostic');
    is($json->encode($a), $before, 'failed selection is detached');
};

subtest 'complete ordinary products and source admission remain unchanged' => sub {
    my $a = $parser->parse_source($source, 'sample-contexts.isf');
    my $before = $json->encode($a);
    my $lowered = $json->encode(FSM::Scheduler::ISF->new->lower($a));
    accepts($a, 'currently admitted scalar/storage actor');
    is($json->encode($a), $before, 'first context consumer preserves current source facts');
    is($json->encode(FSM::Scheduler::ISF->new->lower($a)), $lowered, 'complete scheduled object and actual emitted bytes unchanged');
    my $ok = eval {$parser->parse_source('(actor refused (types (type frame (record (data bit)))) (interface (output packet (type frame))) (transaction main (sample packet as q)))', 'whole-sample-refused.isf'); 1};
    ok(!$ok, 'whole record-output inferred sample remains refused');
    like((split /\n/,$@)[0], qr/whole record/, 'whole-value sample boundary remains exact');
};

done_testing;

use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Storable qw(dclone);
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;

my $parser = FSM::Adapter::ISF->new;
my $scheduler = FSM::Scheduler::ISF->new;
my $json = JSON::PP->new->canonical;
my $work = tempdir(CLEANUP=>1);

sub authored {
    my ($transactions, $rules) = @_;
    return $parser->parse_source(<<"ISF", 'sample-ownership.isf');
(actor sample_owners
 (types (type frame (record (data (four_state (signed (bits 3)))) (ready (two_state bit)))))
 (interface (input start) (input alternate) (input scalar (width 3))
  (output seen (width 3)) (output done))
 (storage (var packet (type frame) (reset 0)))
 (drive (publish value) (seen value))
 $transactions
 ${\($rules // '')})
ISF
}
sub prepared {
    my ($actor) = @_;
    $actor = dclone($actor);
    my $packet = shift @{$actor->{storage}};
    push @{$actor->{interface}{inputs}}, {map {$_=>$packet->{$_}} qw(name width type type_spec)};
    return $actor;
}
sub sample { ['sample',$_[0],'as',$_[1]] }
sub reject {
    my ($actor,$pattern,$label) = @_;
    my $before = $json->encode($actor);
    my $ok = eval {$scheduler->lower($actor); 1};
    my ($line) = split /\n/,$@;
    ok(!$ok, "$label refuses before emission");
    like($line // '', $pattern, "$label first diagnostic identifies ownership");
    is($json->encode($actor),$before,"$label leaves caller facts unchanged");
}
sub strict_carrier {
    my ($name,$text) = @_;
    open my $f,'>',"$work/$name" or die $!;
    print {$f} $text;
    close $f or die $!;
    open my $cli,'-|','./bin/fsmgen','--quiet','--strict','--check','--json',"$work/$name" or die $!;
    my $out = do {local $/; <$cli>};
    close $cli;
    is($? >> 8,0,"$name strictly replays");
    ok($json->decode($out)->{success},"$name replay reports success");
}

subtest 'actual drive and dynamic-counter products reserve sample identities' => sub {
    for my $case (
        ['drive_request','(drive publish scalar)','packet.ready'],
        ['drive_payload','(drive publish scalar)','packet.data'],
        ['dynamic_wait_counter','(wait scalar)','packet.data'],
    ) {
        my ($role,$operation,$source) = @$case;
        my $ordinary = authored("(transaction main (on start) $operation (complete done))");
        my $ir = $scheduler->{ir}->build_module($ordinary);
        my @helpers = sort grep {($ir->{storage_roles}{$_}//'') eq $role} keys %{$ir->{storage_roles}};
        is(scalar(@helpers),1,"ordinary production has one actual $role helper");
        next unless @helpers==1;
        my $helper = $helpers[0];
        ok(exists $ir->{counters}{$helper},"actual $role helper has a real declaration");
        my $actor = prepared($ordinary);
        push @{$actor->{transactions}[0]{clauses}[0]}, sample($source,$helper);
        reject($actor,qr/record-derived sample alias '\Q$helper\E'.*collides with a generated (?:declaration|storage role)/,
            "actual $role $helper collision");
    }
};

subtest 'actual spawn handoff ports reserve private sample identities' => sub {
    my $ordinary = authored('(transaction main (on start) (spawn worker as job) (await_all done) (complete done))
        (transaction worker (wait 1))');
    my $ir = $scheduler->{ir}->build_module($ordinary);
    for my $role (qw(activation_start_handoff activation_done_handoff)) {
        my @helpers = sort grep {($ir->{storage_roles}{$_}//'') eq $role} keys %{$ir->{storage_roles}};
        is(scalar(@helpers),1,"ordinary production has one $role declaration");
        next unless @helpers==1;
        my $helper = $helpers[0];
        ok((grep {$_->{name} eq $helper} @{$ir->{ports}}),"actual $role is a module handoff port");
        my $actor = prepared($ordinary);
        push @{$actor->{transactions}[0]{clauses}[0]},sample('packet.ready',$helper);
        reject($actor,qr/record-derived sample alias '\Q$helper\E'.*collides with (?:a module port|a generated declaration)/,
            "actual spawn $role collision");
    }
};

subtest 'private samples cannot share a transaction owner or accept other writers' => sub {
    my $a = prepared(authored('(transaction first (on start) (complete done))
        (transaction second (on alternate) (wait 1))'));
    push @{$a->{transactions}[0]{clauses}[0]},sample('packet.data','q');
    push @{$a->{transactions}[1]{clauses}[0]},sample('packet.data','q');
    reject($a,qr/record-derived sample alias 'q' has multiple transaction owners/,'two record sample owners');
    $a = prepared(authored('(transaction first (on start) (complete done))
        (transaction second (on alternate) (wait 1))'));
    push @{$a->{transactions}[0]{clauses}[0]},sample('packet.data','q');
    push @{$a->{transactions}[1]{clauses}[0]},sample('scalar','q');
    reject($a,qr/record-derived sample alias 'q' has multiple sample owners/,'record and ordinary sample owners');
    $a = prepared(authored('(transaction first (on start) (complete done))
        (transaction second (on alternate) (set q scalar))'));
    push @{$a->{transactions}[0]{clauses}[0]},sample('packet.data','q');
    reject($a,qr/record-derived sample alias 'q' has a different state writer/,'different transaction writer');
    $a = prepared(authored('(transaction first (on start) (complete done))',
        '(rule overwrite alternate (set q scalar))'));
    push @{$a->{transactions}[0]{clauses}[0]},sample('packet.data','q');
    reject($a,qr/record-derived sample alias 'q' has a decision-tree writer/,'actor rule writer');
};

subtest 'repeated private captures and separate generated module owners are valid' => sub {
    my $a = prepared(authored('(transaction main (on start) (set seen scalar) (complete done))'));
    push @{$a->{transactions}[0]{clauses}[0]},sample('packet.data','q');
    splice @{$a->{transactions}[0]{clauses}},1,0,sample('packet.data','q');
    my $before = $json->encode($a);
    my $result = $scheduler->lower($a);
    is($json->encode($a),$before,'repeated same-owner captures preserve caller facts');
    my $fsm = $result->{files}{'sample_owners.fsm'};
    is(scalar(()=$fsm =~ /\(type _isf_sample_q /g),1,'same-owner scalar type declared once');
    like($fsm,qr/\(internal q\)/,'unused sampled value remains private');
    unlike($fsm,qr/\((?:input|output) q\)/,'unused sample creates no authored pin');
    strict_carrier('sample_owners.fsm',$fsm);

    $a = prepared(authored('(transaction main (on start) (spawn worker as job) (await_all done) (complete done))
        (transaction worker (wait 1))'));
    push @{$a->{transactions}[0]{clauses}[0]},sample('packet.data','q');
    unshift @{$a->{transactions}[1]{clauses}},sample('packet.data','q');
    $before=$json->encode($a);
    $result=$scheduler->lower($a);
    is($json->encode($a),$before,'separate physical owners preserve caller facts');
    for my $name ('sample_owners.fsm','worker.fsm') {
        like($result->{files}{$name},qr/\(q _isf_sample_q\)/,"$name owns its own typed sample");
        strict_carrier($name,$result->{files}{$name});
    }
};

done_testing;

source_snapshots.t/1998-isf-record-input-source-admission:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;

my $parser = FSM::Adapter::ISF->new;
my $scheduler = FSM::Scheduler::ISF->new;
my $json = JSON::PP->new->canonical;
my $work = tempdir(CLEANUP => 1);
my $header = <<'ISF';
(actor records
 (types (type frame (record (kind (bits 2))
   (payload (record (data (signed (four_state (bits 5))))
    (flags (list bit (two_state (bits 2))))))))
  (type alias frame)
  (type other (record (kind (bits 2))
   (payload (record (data (four_state (bits 5))) (flags (list bit (two_state (bits 2)))))))))
 (enums (packet (OTHER 1)) (mode (ON 1)))
 (interface (input start) (input scalar (width 5)) (input mode)
  (input packet (type frame)) (output seen (width 5)) (output sliced (width 3)) (output tag (width 2)) (output done))
 (storage (var held (type alias)) (var mismatch (type other)))
ISF
my $fields = [
    {path => 'kind', width => 2, lsb => 8, msb => 9, signed => 0},
    {path => 'payload.data', width => 5, lsb => 3, msb => 7, signed => 1, state_model => 'four_state'},
    {path => 'payload.flags[0]', width => 1, lsb => 2, msb => 2, signed => 0},
    {path => 'payload.flags[1]', width => 2, lsb => 0, msb => 1, signed => 0, state_model => 'two_state'},
];
sub write_file {
    my ($path, $text) = @_;
    open my $file, '>', $path or die $!;
    print {$file} $text;
    close $file or die $!;
}
sub source { return $header . $_[0] . ')'; }
sub qualify {
    my ($name, $text, $type) = @_;
    my $path = "$work/$name.isf";
    write_file($path, $text);
    my $actor;
    my $ok = eval { $actor = $parser->parse_source($text, $path); 1 };
    my ($error) = split /\n/, $@;
    ok($ok, "$name actual authored source parses") or diag($error // '');
    return unless $ok;
    my $before = $json->encode($actor);
    my ($port) = grep { $_->{name} eq 'packet' } @{$actor->{interface_port_metadata}};
    is_deeply($port, {name => 'packet', direction => 'input', width => 10,
        type => $type, type_kind => 'record', fields => $fields}, "$name complete independently expected input declaration");
    my $result;
    $ok = eval { $result = $scheduler->lower($actor); 1 };
    ($error) = split /\n/, $@;
    ok($ok, "$name actual authored source lowers") or diag($error // '');
    is($json->encode($actor), $before, "$name complete caller JSON stays unchanged");
    return unless $ok;
    my $report = $json->decode($scheduler->report($actor));
    is_deeply([grep {$_->{name} eq 'packet'} @{$report->{interface_ports}}], [$port], "$name actual schedule retains exact record declaration");
    my $dir = "$work/$name";
    mkdir $dir or die $!;
    write_file("$dir/$_", $result->{files}{$_}) for sort keys %{$result->{files}};
    for my $file (sort keys %{$result->{files}}) {
        my $fsm = $result->{files}{$file};
        open my $native, '-|', './bin/fsmgen', '--quiet', '--strict', '--check', '--json', "$dir/$file" or die $!;
        my $output = do {local $/; <$native>};
        close $native;
        my $exit = $? >> 8;
        is($exit, 0, "$name actual $file strictly replays") or diag($output);
        ok($json->decode($output)->{success}, "$name $file reports strict success");
        like($fsm, qr/\(packet \Q$type\E\)/, "$name typed record input reuses the authored alias")
            if $file eq 'records.fsm';
    }
    # Check the authored source too; carrier success alone cannot prove ingress.
    open my $native, '-|', './bin/fsmgen', '--quiet', '--strict', '--check', '--json', $path or die $!;
    my $output = do {local $/; <$native>};
    close $native;
    is($? >> 8, 0, "$name original authored source succeeds natively") or diag($output);
    my $native_report = $json->decode($output);
    ok($native_report->{success}, "$name native source reports complete success");
    is_deeply([grep {$_->{name} eq 'packet'} @{$native_report->{source}{interface_ports}}], [$port],
        "$name native source retains independently expected full metadata");
}
sub refuses {
    my ($text, $pattern, $label) = @_;
    my $ok = eval {
        my $actor = $parser->parse_source($text, 'record-input-negative.isf');
        $scheduler->lower($actor);
        1;
    };
    my ($error) = split /\n/, $@;
    ok(!$ok, "$label refuses before successful lowering");
    like($error // '', $pattern, "$label names the first contextual cause");
}

subtest 'authored local record input contexts use exact packed facts' => sub {
    qualify('copy', source('(transaction main (on start) (set held packet) (set seen packet.payload.data) (complete done))'), 'frame');
    qualify('leaves', source('(transaction main (on start) (when mode.ON (set sliced packet.payload.data[3:1]))'
        . ' (when packet.payload.flags[1] (update tag packet.kind)) (complete done))'), 'frame');
    qualify('sample', source('(transaction main (on start (sample packet.payload.data as held_leaf))'
        . ' (set seen held_leaf) (complete done))'), 'frame');
    qualify('rule', source('(rule observe packet.payload.flags[0] (seen packet.payload.data))'), 'frame');
    qualify('drive', source('(drive publish (seen packet.payload.data))'
        . ' (transaction main (on start) (drive publish) (complete done))'), 'frame');
    qualify('generated', source('(transaction worker (ports (output result (width 5))) (set result packet.payload.data) (complete done))'
        . ' (transaction main (on start) (spawn worker as job (bind (output result seen))) (await_all done) (complete done))'), 'frame');
    qualify('unused', source('(transaction main (on start) (set seen scalar) (complete done))'), 'frame');
};

subtest 'actual imported aliases preserve the same resolved identity' => sub {
    write_file("$work/shared.fsm", '(?pkg:shared (+types (type frame (record (kind (bits 2))'
        . ' (payload (record (data (signed (four_state (bits 5)))) (flags (list bit (two_state (bits 2))))))))))');
    my $text = $header;
    my $start = index($text, ' (types');
    my $end = index($text, ' (enums');
    substr($text, $start, $end - $start, ' (imports (package shared))' . "\n");
    $text =~ s/\(type (?:frame|alias|other)\)/(type shared.frame)/g;
    qualify('imported', $text . '(transaction main (on start) (set held packet) (set seen packet.payload.data) (complete done)))', 'shared.frame');
};

subtest 'first authored source admission has every mandatory negative gate' => sub {
    for my $case (
        ['unknown member', '(set seen packet.missing)', qr/unknown_member/],
        ['out of range', '(set seen packet.payload.flags[1][2])', qr/scalar_index_out_of_range/],
        ['subaggregate scalar', '(set seen packet.payload)', qr/requires a scalar leaf.*resolves to record/],
        ['input field target', '(set packet.payload.data 1)', qr/cannot write declared input/],
        ['input whole target', '(set packet held)', qr/cannot write declared input/],
        ['equal width mismatch', '(set mismatch packet)', qr/requires the same resolved record type/],
        ['whole to scalar', '(set seen packet)', qr/whole record port copy requires declared record roots/],
        ['whole arithmetic', '(set seen (+ packet 1))', qr/requires a scalar value.*whole record port/],
        ['whole condition', '(when packet (set seen 1))', qr/requires a scalar value.*whole record port/],
        ['member operator', '(set seen (packet.payload.data 1))', qr/operator cannot use declared aggregate reference/],
        ['whole sample', '(sample packet as q)', qr/scalar.*whole record|whole record.*scalar/],
        ['input alias', '(sample scalar as packet)', qr/cannot write declared input/],
        ['unsupported trigger', '(await packet.payload.flags[0])', qr/does not admit record port reference/],
    ) {
        refuses(source('(transaction main (on start) ' . $case->[1] . ')'), $case->[2], $case->[0]);
    }
    my $foreign = $header;
    $foreign =~ s/\(actor records/\(actor records (clock-domains (domain core (clock clk) :default) (domain aux (clock aux_clk)))/;
    $foreign =~ s/\(input packet \(type frame\)\)/\(input packet (type frame) (domain aux)\)/;
    refuses($foreign . '(transaction main (on start) (set seen packet.payload.data)))',
        qr/clock-domain violation: .* read signal 'packet.payload.data' owned by domain 'aux' from domain 'core'/,
        'authored foreign record leaf');
};

subtest 'unbound generated outputs remain closed for record and ordinary sources' => sub {
    my $unbound = source('(transaction worker (set seen packet.payload.data) (complete done))'
        . ' (transaction main (on start) (spawn worker as job) (await_all done) (complete done))');
    my $ordinary = $unbound;
    $ordinary =~ s/\(input packet \(type frame\)\)/(input packet (width 10))/;
    $ordinary =~ s/packet\.payload\.data/scalar/g;
    for my $case (['record', $unbound], ['ordinary', $ordinary]) {
        my $path = "$work/unbound-$case->[0].isf";
        write_file($path, $case->[1]);
        open my $native, '-|', './bin/fsmgen', '--quiet', '--strict', '--check', '--json', $path or die $!;
        my $output = do {local $/; <$native>};
        close $native;
        is($? >> 8, 1, "$case->[0] unbound generated output refuses natively");
        my $report = $json->decode($output);
        ok(!$report->{success}, "$case->[0] unbound output cannot report source success");
        ok(!$report->{generated_output}{emitted}, "$case->[0] unbound output emits no HDL");
        like($report->{diagnostics}[0]{message}, qr/leaves child port 'job.seen' unconnected/,
            "$case->[0] first native diagnostic retains existing explicit child binding contract");
    }
};

subtest 'unqualified aggregate carriers and unknown aliases stay closed' => sub {
    for my $case (
        ['output field', '(actor refused (types (type frame (record (flag bit)))) (interface (output packet (type frame))) (transaction main (set packet.flag 1)))', qr/record output field writes are not yet admitted/],
        ['root list', '(actor refused (types (type lanes (list bit bit))) (interface (input packet (type lanes))))', qr/interface port 'packet' references aggregate type/],
        ['transaction', '(actor refused (types (type frame (record (flag bit)))) (transaction main (ports (input packet (type frame)))))', qr/transaction 'main' port 'packet' references aggregate type/],
        ['unknown alias', '(actor refused (interface (input packet (type missing))))', qr/interface port 'packet' references unknown type 'missing'/],
        ['width and type', '(actor refused (interface (input packet (type missing) (width 8))))', qr/cannot specify both/],
    ) {
        refuses($case->[1], $case->[2], $case->[0]);
    }
};

done_testing;

use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Digest::SHA qw(sha256_hex);
use Cwd qw(abs_path);
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Test::SourceQueryRunner qw(normalize_repository_paths);
use FSM::Support::SemanticIntrospectionMCPAdapter;

my $root = abs_path('.');
my $work = tempdir(CLEANUP => 1);
my $json = JSON::PP->new->canonical->utf8;
my $api = FSM::Support::SemanticIntrospectionMCPAdapter->new(repo_root => $root, workspace_root => $root);
my %flags = (check => [qw(--strict --check --json)], semantic => [qw(--strict --emit-semantic-json)]);
my %tools = (check => 'fsmgen_check', semantic => 'fsmgen_semantic_introspect', schedule => 'fsmgen_schedule_preview');
my $header = <<'ISF';
(actor record_refused
 (types (type frame (record (kind (bits 2))
   (payload (record (data (signed (four_state (bits 5))))
    (flags (list bit (two_state (bits 2))))))))
  (type alias frame)
  (type other (record (kind (bits 2))
   (payload (record (data (four_state (bits 5))) (flags (list bit (two_state (bits 2)))))))))
 (enums (packet (OTHER 1)) (mode (ON 1)))
 (interface (input start) (input scalar (width 5)) (input mode)
  (input packet (type frame)) (output seen (width 5)) (output done))
 (storage (var held (type alias)) (var mismatch (type other)))
ISF
my @cases;
for my $case (
    ['unknown_member', '(set seen packet.missing)', qr/unknown_member/],
    ['out_of_range', '(set seen packet.payload.flags[1][2])', qr/scalar_index_out_of_range/],
    ['subaggregate_scalar', '(set seen packet.payload)', qr/requires a scalar leaf.*resolves to record/],
    ['input_field_target', '(set packet.payload.data 1)', qr/cannot write declared input/],
    ['input_root_target', '(set packet held)', qr/cannot write declared input/],
    ['equal_width_wrong_type', '(set mismatch packet)', qr/requires the same resolved record type/],
    ['record_to_scalar', '(set seen packet)', qr/whole record port copy requires declared record roots/],
    ['whole_arithmetic', '(set seen (+ packet 1))', qr/requires a scalar value.*whole record port/],
    ['whole_condition', '(when packet (set seen 1))', qr/requires a scalar value.*whole record port/],
    ['record_operator', '(set seen (packet.payload.data 1))', qr/operator cannot use declared aggregate reference/],
    ['whole_sample', '(sample packet as q)', qr/scalar.*whole record|whole record.*scalar/],
    ['sample_alias_input', '(sample scalar as packet)', qr/cannot write declared input/],
    ['unsupported_await', '(await packet.payload.flags[0])', qr/does not admit record port reference/],
) {
    push @cases, [$case->[0], $header . '(transaction main (on start) ' . $case->[1] . '))', $case->[2]];
}
push @cases,
    ['nearest_scalar_member', $header . '(transaction main (ports (input packet (width 3)))'
        . ' (on start) (set seen packet.payload.data)))', qr/member_on_non_record/],
    ['drive_parameter_member', $header . '(drive (publish packet) (seen packet.payload.data))'
        . ' (transaction main (on start) (drive publish start)))', qr/member_on_non_record/],
    ['drive_parameter_indexed_member', $header . '(drive (publish packet) (seen packet[0].payload.data))'
        . ' (transaction main (on start) (drive publish start)))', qr/member_on_non_record/],
    ['drive_parameter_sliced_member', $header . '(drive (publish packet) (seen packet[0:0].payload.data))'
        . ' (transaction main (on start) (drive publish start)))', qr/member_on_non_record/],
    ['rule_input_target', $header . '(rule observe scalar (packet.payload.data 1)))', qr/cannot write declared input/],
    ['drive_input_target', $header . '(drive publish (packet.payload.data 1)))', qr/cannot write declared input/],
    ['inline_input_target', $header . '(transaction main (on start) (drive (packet.payload.data 1))))',
        qr/cannot write declared input/];
my $foreign = $header;
$foreign =~ s/\(actor record_refused/\(actor record_refused (clock-domains (domain core (clock clk) :default) (domain aux (clock aux_clk)))/;
$foreign =~ s/\(input packet \(type frame\)\)/\(input packet (type frame) (domain aux)\)/;
push @cases, ['foreign_domain', $foreign . '(transaction main (on start) (set seen packet.payload.data)))',
    qr/clock-domain violation: .* read signal 'packet.payload.data' owned by domain 'aux' from domain 'core'/];
for my $case (
    ['record_output_field', '(types (type frame (record (flag bit)))) (interface (output packet (type frame))) (transaction main (set packet.flag 1))',
        qr/record output field writes are not yet admitted/],
    ['root_list', '(types (type lanes (list bit bit))) (interface (input packet (type lanes)))',
        qr/interface port 'packet' references aggregate type/],
    ['transaction_record', '(types (type frame (record (flag bit)))) (transaction main (ports (input packet (type frame))))',
        qr/transaction 'main' port 'packet' references aggregate type/],
    ['aggregate_bank', '(types (type frame (record (flag bit)))) (storage (bank memory (type frame) (depth 2)))',
        qr/storage.*memory.*aggregate type|bank.*type/],
    ['unknown_type', '(interface (input packet (type missing)))', qr/interface port 'packet' references unknown type 'missing'/],
    ['width_and_type', '(interface (input packet (type missing) (width 8)))', qr/cannot specify both/],
    ['unimported_alias', '(types (type alias shared.frame)) (interface (input packet (type alias)))',
        qr/malformed '\+types' entry for type 'alias'/],
) {
    push @cases, [$case->[0], '(actor record_refused ' . $case->[1] . ')', $case->[2]];
}
write_file("$work/shared.fsm", '(?pkg:shared (+types (type frame (record (flag bit)))))');
push @cases, ['missing_imported_type', '(actor record_refused (imports (package shared))'
    . ' (types (type alias shared.missing)) (interface (input packet (type alias))))',
    qr/malformed '\+types' entry for type 'alias'/];
my $package_before = sha256_hex(read_file("$work/shared.fsm"));

for my $case (@cases) {
    my ($name, $text, $message) = @$case;
    subtest "public refusal $name" => sub {
        my $path = "$work/$name.isf";
        write_file($path, $text);
        $path =~ s/^\Q$root\E\///;
        my $before = sha256_hex(read_file($path));
        for my $kind (qw(check semantic)) {
            my $native = capture([$^X, 'bin/fsmgen', @{$flags{$kind}}, $path]);
            is($native->{exit_code}, 1, "$kind actual native source refuses")
                or diag($native->{stdout} . $native->{stderr});
            is($native->{stderr}, '', "$kind machine-report stderr remains clean");
            my $report = eval { $json->decode($native->{stdout}) };
            ok(ref($report) eq 'HASH', "$kind native failure remains a complete report") or diag($native->{stdout});
            next unless ref($report) eq 'HASH';
            $report = normalize_repository_paths($report, $root);
            ok(!$report->{success}, "$kind expected compiler refusal is explicit");
            like($report->{diagnostics}[0]{message} // '', $message, "$kind independent first contextual cause");
            ok(exists($report->{diagnostics}[0]{code}), "$kind retains its nullable diagnostic code field");
            ok(!exists($report->{source}{interface_ports}), "$kind publishes no successful declaration snapshot");
            ok(!$report->{generated_output}{emitted}, "$kind emits no HDL");
            ok(!defined($report->{semantic}), "$kind publishes no partial successful semantic payload");
            is($report->{source}{input}, $path, "$kind exact refused source provenance");
            my $request = request($path, $kind);
            my $response = $api->handle_jsonrpc_request($request);
            ok(!$response->{error}, "$kind refusal retains its tool-result envelope") or diag($json->encode($response));
            next if $response->{error};
            ok($response->{result}{isError}, "$kind API preserves compiler refusal");
            same($response->{result}{structuredContent}{report}, $report, "$kind complete typed native/API failure equality");
            same($json->decode($response->{result}{content}[0]{text}), $response->{result}{structuredContent},
                "$kind complete text/structured failure equality");
            wire_equal($request, $response, $kind);
        }
        my $native = capture([$^X, 'bin/fsmgen', '--emit-schedule-json', $path]);
        isnt($native->{exit_code}, 0, 'actual native schedule refuses') or diag($native->{stdout} . $native->{stderr});
        is($native->{stdout}, '', 'no partial successful schedule product');
        like($native->{stderr}, $message, 'schedule independent contextual cause');
        my $request = request($path, 'schedule');
        my $response = $api->handle_jsonrpc_request($request);
        ok($response->{error}, 'schedule keeps its message-only error contract') or diag($json->encode($response));
        if ($response->{error}) {
            is($response->{error}{code}, -32000, 'schedule existing adapter error code');
            is($response->{error}{message}, 'FSMGen command failed without a matching public failure report',
                'schedule API preserves its existing generic message-only failure');
            ok(!exists($response->{error}{data}) && !exists($response->{result}), 'no partial schedule or error data');
        }
        wire_equal($request, $response, 'schedule');
        is(sha256_hex(read_file($path)), $before, 'all failed public queries preserve exact source bytes');
        is(sha256_hex(read_file("$work/shared.fsm")), $package_before, 'all failed public queries preserve imported bytes');
    };
}

done_testing;
sub request { return {jsonrpc => '2.0', id => 1, method => 'tools/call',
    params => {name => $tools{$_[1]}, arguments => {source_id => $_[0]}}}; }
sub same { is($json->encode($_[0]), $json->encode($_[1]), $_[2]); }
sub wire_equal {
    my ($request, $response, $kind) = @_;
    my $wire = capture([$^X, 'bin/fsmgen-mcp', '--workspace-root', '.'], $json->encode($request) . "\n");
    is($wire->{exit_code}, 0, "$kind actual newline transport succeeds");
    is($wire->{stderr}, '', "$kind actual newline stderr clean");
    like($wire->{stdout}, qr/\A[^\n]+\n\z/, "$kind exactly one compact response per newline");
    my $decoded = eval { $json->decode($wire->{stdout}) };
    ok(ref($decoded) eq 'HASH', "$kind newline response is complete JSON") or diag($wire->{stdout});
    same($decoded, $response, "$kind complete typed API/newline refusal equality") if ref($decoded) eq 'HASH';
}
sub capture { return FSM::Test::SourceQueryRunner::_capture($_[0], $_[1] // ''); }
sub read_file { open my $fh, '<:raw', $_[0] or die $!; local $/; return <$fh>; }
sub write_file {
    open my $fh, '>:raw', $_[0] or die $!;
    print {$fh} $_[1] or die $!;
    close $fh or die $!;
}

