use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use Digest::SHA qw(sha256_hex);
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Test::SourceQueryRunner;
use FSM::Pipeline::HDLGenerator;

my $work = tempdir(CLEANUP => 1);
my $direct_prefix = '[VHDL.pm][direct scaffold] Unsupported generated SystemVerilog shape for direct VHDL backend: ';
my $mixed_member = qr/^Error generating HDL: \Q$direct_prefix\Eunsupported packed struct member 'logic signed \[4:0\] data; struct packed \{ bit item_0; '/;
my $record_input = qr/^Error generating HDL: \Q$direct_prefix\Eunsupported generated port declaration 'input fsmgen_m[1-9][0-9]*_link_rx_lmp_t_fsmgen_t lmp_in'/;
my @refusals = (
    ['t/data/isf_record_input_runtime.isf', $mixed_member],
    ['t/data/isf_record_input_generated_domains_runtime.isf', composition_reason('packed_input_generated_domains_top')],
    ['t/data/isf_record_input_generated_blocking_runtime.isf', composition_reason('packed_input_generated_blocking_top')],
    ['docs/audits/specforge-aggregate-intake-20260930/record-port.isf', $record_input],
    ['docs/audits/specforge-aggregate-intake-20260930/record-port-field-guard.isf', $record_input],
);
my @controls = (
    ['docs/audits/specforge-aggregate-intake-20260930/baseline-good.isf',
        qr/entity link_rx is/, qr/subtype_in\s+:\s+in std_logic_vector\(3 downto 0\)/],
    ['t/corpus/direct_aggregate_constant_target_autogrowth.fsm',
        qr/entity direct_aggregate_constant_target_autogrowth is/,
        qr/OUT_FRAME\s+:\s+out std_logic_vector\(4 downto 0\)/],
);
my @paths = (map {$_->[0]} @refusals, @controls);
push @paths, qw(bin/fsmgen perl/FSM/Pipeline/HDLGenerator.pm
    perl/FSM/HDL/FlattenedDT/Backend/VHDL.pm
    perl/FSM/Backend/VHDL/StructuralRTLIREmitter.pm
    perl/FSM/Composition/PlanBuilder.pm
    perl/FSM/Adapter/ISF/Parser.pm perl/FSM/Scheduler/ISF/LoweringIR.pm
    perl/FSM/Support/ISFPublicInterfaceContract.pm);
my $before = {map {$_ => sha256_hex(read_file($_))} @paths};
my @observed;

for my $i (0..$#refusals) {
    my ($source,$reason) = @{$refusals[$i]};
    subtest "VHDL profile refuses $source before publication" => sub {
        my $existing = "$work/existing_$i.vhd";
        write_file($existing, "EXISTING DESTINATION\n");
        my $native = capture([$^X,'bin/fsmgen','--strict','--quiet','--language','vhdl',
            '--output',$existing,$source]);
        ok(refused($native,$reason),'native exit, signal and first diagnostic establish exact refusal')
            or diag($native->{stdout},$native->{stderr});
        is(read_file($existing),"EXISTING DESTINATION\n",'existing destination remains byte-exact');
        unlike($native->{stdout},qr/\b(?:entity|architecture|module|typedef)\b/,
            'native failure publishes no HDL payload');
        my $missing = "$work/missing_$i.vhd";
        my $absent = capture([$^X,'bin/fsmgen','--strict','--quiet','--language','vhdl',
            '--output',$missing,$source]);
        ok(refused($absent,$reason),'same profile refuses absent destination') or diag($absent->{stderr});
        ok(!-e $missing,'failure creates no destination');
        my ($product,$error);
        eval {$product=FSM::Pipeline::HDLGenerator->new(debug_level=>0,target_language=>'vhdl',quiet=>1)
            ->generate_hdl_from_file($source);1} or $error=$@;
        ok(!defined($product),'public pipeline returns no partial successful product');
        like(primary_diagnostic($error // ''),$reason,'public pipeline retains the same precise primary reason');
        push @observed, [$native,$reason];
    };
}

for my $i (0..$#controls) {
    my ($source,$entity,$port) = @{$controls[$i]};
    subtest "supported VHDL control $source remains admitted" => sub {
        my $output = "$work/control_$i.vhd";
        my $native=capture([$^X,'bin/fsmgen','--strict','--quiet','--language','vhdl','--output',$output,$source]);
        is($native->{exit_code},0,'native control emits successfully') or diag($native->{stderr});
        is($native->{signal},0,'native control ends normally');
        is($native->{stderr},'','native control stderr is clean');
        my $text=read_file($output);
        like($text,$entity,'independently named entity emitted');
        like($text,$port,'independently sized scalar or packed-vector declaration emitted');
        unlike($text,qr/\b(?:module|typedef|always_ff|always_comb)\b/,'control emits VHDL scaffold syntax');
        my $product=FSM::Pipeline::HDLGenerator->new(debug_level=>0,target_language=>'vhdl',quiet=>1)
            ->generate_hdl_from_file($source);
        like($product->{hdl_code},$entity,'public pipeline admits supported control');
        like($product->{hdl_code},$port,'public pipeline preserves independent declaration');
        if ($i == 1) {
            like($text,qr/OUT_LANES\s+<=\s+"10101";/,'existing packed-output constant keeps exact literal');
        }
    };
}

subtest 'refusal oracle rejects false success and stack-only expected text' => sub {
    for my $row (@observed) {
        my ($native,$reason)=@$row;
        ok(refused($native,$reason),'actual selected negative calibrates oracle');
        ok(!refused({%$native,exit_code=>0},$reason),'zero exit never qualifies refusal');
        ok(!refused({%$native,signal=>9},$reason),'signal failure never qualifies profile refusal');
        ok(!refused({%$native,stderr=>"Error generating HDL: unrelated failure\n\t".primary_diagnostic($native->{stderr})},$reason),
            'expected reason only in later stack text never qualifies');
        ok(!refused({%$native,stderr=>''},$reason),'missing diagnostic never qualifies');
    }
};

is_deeply({map {$_ => sha256_hex(read_file($_))} @paths},$before,
    'complete selected sources and named producer bytes remain unchanged');
done_testing;

sub composition_reason {
    my ($top)=@_;
    return qr/^Composition source '\?top:\Q$top\E' .*Target language 'vhdl' is not implemented for this composition shape yet: generated-child composition VHDL is outside the bounded C2 scalar-autowire\/scalar-bitstring-one-bit-aggregate-generic and APB\/C4 generated-FSM structural-top leaves\. See docs\/COMPOSITION_SCOPE\.md and docs\/COMPOSITION_LEGACY_MAPPING\.md\.\z/;
}
sub primary_diagnostic {
    my ($error)=@_;
    my @lines=split /\n/,$error;
    shift @lines if @lines && $lines[0] =~ /^Source file: /;
    return $lines[0] // '';
}
sub refused { my($result,$reason)=@_; return $result->{exit_code} == 1 && $result->{signal} == 0
    && primary_diagnostic($result->{stderr}) =~ $reason ? 1 : 0; }
sub capture { FSM::Test::SourceQueryRunner::_capture($_[0],''); }
sub read_file {open my $fh,'<:raw',$_[0] or die $!;local $/;my $s=<$fh>;close $fh or die $!;return $s;}
sub write_file {open my $fh,'>:raw',$_[0] or die $!;print {$fh} $_[1] or die $!;close $fh or die $!;}

use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use Digest::SHA qw(sha256_hex);
use File::Temp qw(tempdir);
use JSON::PP;
use FSM::Test::ProjectDataLocality;
use FSM::Test::SourceQueryRunner;
use FSM::Pipeline::HDLGenerator;

my $work = tempdir(CLEANUP => 1);
my $json = JSON::PP->new->canonical;
write_file("$work/shared.fsm", '(?pkg:shared (+types (type frame (record (flag bit) (data (bits 3))))))');
write_file("$work/imported.isf", '(actor imported_record_profile (imports (package shared)) (types (type alias shared.frame)) (clock clk) (interface (input start) (input packet (type alias)) (output done)) (transaction main (on start) (complete done)))');
write_file("$work/unused.isf", '(actor unused_record_profile (clock clk) (types (type frame (record (flag bit) (data (bits 3))))) (interface (input start) (input packet (type frame)) (output done)) (transaction main (on start) (complete done)))');
my @cases = (
    ["$work/imported.isf", 'imported_record_profile', 'packet', 'alias'],
    ["$work/unused.isf", 'unused_record_profile', 'packet', 'frame'],
    ['t/data/isf_record_input_runtime.isf', 'packed_input_runtime', 'packet', 'frame', 'direct'],
    ['t/data/isf_record_input_generated_domains_runtime.isf', 'packed_input_generated_domains', 'packet', 'frame', 'domains'],
    ['t/data/isf_record_input_generated_blocking_runtime.isf', 'packed_input_generated_blocking', 'packet', 'frame', 'blocking'],
    ['docs/audits/specforge-aggregate-intake-20260930/record-port.isf', 'link_rx', 'lmp_in', 'lmp_t'],
    ['docs/audits/specforge-aggregate-intake-20260930/record-port-field-guard.isf', 'link_rx', 'lmp_in', 'lmp_t'],
);
my @sources = ("$work/shared.fsm", map {$_->[0]} @cases);
push @sources, qw(bin/fsmgen perl/FSM/Pipeline/HDLGenerator.pm
    perl/FSM/Adapter/ISF/Parser.pm perl/FSM/Scheduler/ISF/LoweringIR.pm
    perl/FSM/Support/ISFHDLProfile.pm perl/FSM/Support/ISFInterfacePortMetadata.pm
    t/data/isf_record_input_runtime_tb.sv
    t/data/isf_record_input_generated_runtime_tb.sv);
my $before = {map {$_ => sha256_hex(read_file($_))} @sources};
my @observed;

for my $index (0..$#cases) {
    my ($source,$actor,$port,$type,$old_name)=@{$cases[$index]};
    my $reason = "ISF actor '$actor' record input '$port' (type '$type') cannot generate target 'verilog': packed record inputs require SystemVerilog; use --language systemverilog. Verilog-2005 record lowering is not implemented.";
    subtest "precise record-input Verilog boundary for $source" => sub {
        for my $target (qw(verilog v)) {
            my $output = "$work/refused_${index}_$target.v";
            write_file($output,"EXISTING DESTINATION\n");
            my $native = capture([$^X,'bin/fsmgen','--strict','--quiet','--language',$target,'--output',$output,$source]);
            ok(refused($native,$reason),'normal native failure names authored actor, record port, type and supported alternative')
                or diag($native->{stdout},$native->{stderr});
            is(read_file($output),"EXISTING DESTINATION\n",'existing output is byte-exact');
            push @observed,[$native,$reason];
            unlink $output or die $!;
            my $absent = capture([$^X,'bin/fsmgen','--strict','--quiet','--language',$target,'--output',$output,$source]);
            ok(refused($absent,$reason),'absent output has the same precise normal refusal') or diag($absent->{stderr});
            ok(!-e $output,'no new destination is published');
            my ($product,$error);
            eval {$product=FSM::Pipeline::HDLGenerator->new(target_language=>$target,quiet=>1,strict_mode=>1)
                ->generate_hdl_from_file($source);1} or $error=$@;
            ok(!defined($product),'facade publishes no partial successful product');
            like($error // '',qr/^\Q$reason\E(?: at |\n|$)/,'facade retains the same primary contextual reason');
        }
        for my $kind (['check', qw(--check --json)], ['semantic', '--emit-semantic-json']) {
            my ($name,@flags)=@$kind;
            my $native=capture([$^X,'bin/fsmgen','--strict','--quiet','--language','verilog',@flags,$source]);
            is($native->{exit_code},1,"$name profile failure has normal status");
            is($native->{signal},0,"$name profile failure has no signal");
            is($native->{stderr},'',"$name machine report owns the diagnostic");
            my $report=$json->decode($native->{stdout});
            is($json->encode($report->{success}),'false',"$name exact JSON failure kind");
            is($report->{diagnostics}[0]{message},$reason,"$name precise stable message contains no implementation stack");
            ok(exists($report->{diagnostics}[0]{code}),"$name nullable diagnostic code is retained");
            ok(!exists($report->{source}{interface_ports}),"$name publishes no successful declaration snapshot");
            ok(!defined($report->{semantic}),"$name publishes no partial semantic product");
        }
        my $schedule = capture([$^X,'bin/fsmgen','--strict','--quiet','--language','verilog','--emit-schedule-json',$source]);
        is($schedule->{exit_code},0,'target-neutral schedule preview remains available');
        ok($json->decode($schedule->{stdout})->{interface_ports},'preview retains declared interface metadata');
        if (defined $old_name) {
            my $output = "$work/supported_$index.sv";
            my $native=capture([$^X,'bin/fsmgen','--strict','--quiet','--language','systemverilog','--output',$output,$source]);
            is($native->{exit_code},0,'SystemVerilog source generation remains supported') or diag($native->{stderr});
            is(normalize_date(read_file($output)),normalize_date(read_file("docs/audits/record-input-language-profile-20261001/${old_name}_systemverilog.hdl.source")),
                'complete SystemVerilog HDL equals committed predecessor except dated banners');
        }
    };
}

subtest 'scalar Verilog and SystemVerilog storage controls remain supported' => sub {
    for my $case (
        ['docs/audits/specforge-aggregate-intake-20260930/baseline-good.isf','verilog','link_rx'],
        ['isf/storage_fields.isf','systemverilog','storage_fields'],
    ) {
        my ($source,$target,$module)=@$case;
        my $output="$work/control_$target.sv";
        my $native=capture([$^X,'bin/fsmgen','--strict','--quiet','--language',$target,'--output',$output,$source]);
        is($native->{exit_code},0,'unchanged supported control generates HDL') or diag($native->{stderr});
        like(read_file($output),qr/\bmodule \Q$module\E\b/,'independently named module remains');
    }
};

subtest 'refusal oracle rejects false success, signal and secondary diagnostic' => sub {
    for my $row (@observed) {
        my ($native,$reason)=@$row;
        ok(!refused({%$native,exit_code=>0},$reason),'successful emission cannot qualify a refusal');
        ok(!refused({%$native,signal=>9},$reason),'signal failure cannot qualify a profile refusal');
        ok(!refused({%$native,stderr=>"Error generating HDL: unrelated failure\n$reason\n"},$reason),
            'later expected text cannot replace primary diagnostic');
        ok(!refused({%$native,stderr=>''},$reason),'missing diagnostic cannot qualify');
    }
};
is_deeply({map {$_ => sha256_hex(read_file($_))} @sources},$before,'source, bench and named producer bytes remain unchanged during qualification');
done_testing;

sub refused {
    my ($result,$reason)=@_;
    my $first=(split /\n/,$result->{stderr})[0] // '';
    return $result->{exit_code}==1 && $result->{signal}==0
        && $first =~ /^(?:Error generating HDL: )?\Q$reason\E(?: at |$)/ ? 1 : 0;
}
sub normalize_date {my ($text)=@_;$text =~ s{^// Date:[^\n]*$}{// Date: omitted}mg;return $text;}
sub capture { FSM::Test::SourceQueryRunner::_capture($_[0],''); }
sub read_file {open my $fh,'<:raw',$_[0] or die $!;local $/;my $s=<$fh>;close $fh or die $!;return $s;}
sub write_file {open my $fh,'>:raw',$_[0] or die $!;print {$fh} $_[1] or die $!;close $fh or die $!;}

source_snapshots.t/2030-isf-record-output-writer-admissio:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Storable qw(dclone);
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Test::SourceQueryRunner;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Scheduler::ISF::FormalLowering;
use FSM::Support::ISFInterfacePortMetadata qw(capture_interface_port_metadata);
use FSM::Scheduler::ISF::RecordOutputWriters;

my $json = JSON::PP->new->canonical;
my $work = tempdir(CLEANUP => 1);
my $definition = '(record (tag (bits 2)) (payload (signed (four_state (bits 3)))))';
write_file('shared.fsm', '(?pkg:shared (+types (type frame '.$definition.')))');

subtest 'sole writers and ordered states retain the complete unpruned inventory' => sub {
    for my $case (
        ['unused', '', 0],
        ['sole', '(transaction main (on start) (set packet held))', 1],
        ['ordered', '(transaction main (on start) (set packet held) (wait 1) (set packet held))', 2],
        ['rule', '(rule publish (when start) (set packet held))', 1],
        ['drive', '(drive publish (packet held)) (transaction main (on start) (drive publish))', 1],
    ) {
        my ($name,$body,$count) = @$case;
        for my $type ('frame','shared.frame') {
            my ($actor,$ir) = fixture($name,$body,$type);
            my ($a,$i) = map {$json->encode($_)} ($actor,$ir);
            my $expected = FSM::Scheduler::ISF::RecordOutputWriters->inventory(actor=>$actor,ir=>$ir);
            my $admitted = admit($actor,$ir);
            is_deeply($admitted,$expected,"$name/$type admission returns every original inventory fact");
            is(scalar @{$admitted->{writers}},$count,"$name/$type independent actual writer count");
            is($json->encode($actor),$a,"$name/$type actor remains unchanged");
            is($json->encode($ir),$i,"$name/$type module remains unchanged");
        }
    }
};

subtest 'independent physical roots and independently resolved leaves are disjoint' => sub {
    my ($actor,$ir) = fixture('distinct_roots',
        '(transaction left (on start) (set packet held)) (transaction right (on other) (set spare held))');
    my $writers = admit($actor,$ir)->{writers};
    is_deeply([sort map {$_->{target}{root}} @$writers],['packet','spare'],
        'actual different declared output roots admit independent source owners');
    my ($member_actor,$member_ir) = fixture('distinct_leaves', competing_body());
    for my $state (@{$member_ir->{states}}) {
        for my $assignment (@{$state->{assignments}}) {
            next unless $assignment->{lhs} eq 'packet';
            $assignment->{lhs} = $state->{transaction} eq 'left' ? 'packet.tag' : 'packet.payload';
        }
    }
    my $members = admit($member_actor,$member_ir)->{writers};
    is_deeply([sort map {join(':',@{$_->{target}}{qw(low high width)})} @$members],
        ['0:2:3','3:4:2'],'literal packed field ranges establish physical disjointness');
    my ($other_actor,$other_ir) = fixture('other_module','(transaction main (on start) (set packet held))');
    is(admit($other_actor,$other_ir)->{writers}[0]{target}{module},'other_module',
        'separate actual module admission retains its own identity');
};

subtest 'overlapping independent owners refuse regardless of values entry guards priority or declaration order' => sub {
    for my $case (
        ['equal_values', competing_body()],
        ['different_values', '(transaction left (on start) (set held.payload 1) (set packet held)) (transaction right (on other) (set alternate.payload 2) (set packet alternate))'],
        ['complementary_conditions', '(transaction left (when start (sample start as accepted_left)) (set packet held)) (transaction right (when (! start) (sample start as accepted_right)) (set packet held))'],
        ['priority', competing_body().' (priority left over right)'],
    ) {
        my ($name,$body) = @$case;
        my ($actor,$ir) = fixture($name,$body);
        for my $reverse (0,1) {
            my $ordered = dclone($ir);
            @{$ordered->{states}} = reverse @{$ordered->{states}} if $reverse;
            my ($a,$i) = map {$json->encode($_)} ($actor,$ordered);
            my $error = refusal($actor,$ordered);
            like($error,qr/record output 'packet' cannot admit overlapping writers/,"$name/$reverse primary output reason");
            like($error,qr/transaction\/left\/state:/,"$name/$reverse explicit left owner");
            like($error,qr/transaction\/right\/state:/,"$name/$reverse explicit right owner");
            is($json->encode($actor),$a,"$name/$reverse failed admission preserves actor");
            is($json->encode($ordered),$i,"$name/$reverse failed admission preserves module");
        }
    }
};

subtest 'whole-member overlap and duplicate point-active writes stay closed' => sub {
    my ($actor,$ir) = fixture('whole_member',competing_body());
    my ($right) = grep {($_->{transaction}//'') eq 'right' && grep {$_->{lhs} eq 'packet'} @{$_->{assignments}}} @{$ir->{states}};
    $right->{assignments}[0]{lhs} = 'packet.tag';
    like(refusal($actor,$ir),qr/to 'packet' and 'packet.tag'/,
        'distinct spellings cannot hide whole-root versus member physical overlap');
    my ($one_actor,$one_ir) = fixture('same_state','(transaction main (on start) (set packet held))');
    my ($state) = grep {grep {$_->{lhs} eq 'packet'} @{$_->{assignments}}} @{$one_ir->{states}};
    push @{$state->{assignments}},dclone($state->{assignments}[0]);
    like(refusal($one_actor,$one_ir),qr/cannot admit overlapping writers/,
        'same active state does not acquire unqualified assignment precedence');
    my ($dt_actor,$dt_ir) = fixture('same_dt','(rule publish (when start) (set packet held) (set packet held))');
    like(refusal($dt_actor,$dt_ir),qr/rule\/publish\/dt:/,
        'repeated same DT output assignments do not acquire inferred precedence');
    my ($aux_actor,$aux_ir) = fixture('aux_dt',
        '(transaction main (on start) (set packet held) (latency (min 1) (max 9)))');
    my ($aux) = grep {$_->{kind} eq 'latency_counter'} @{$aux_ir->{dt_blocks}};
    push @{$aux->{assignments}},{lhs=>'packet',rhs=>'held',op=>'<-',guard=>{port=>'1'}};
    like(refusal($aux_actor,$aux_ir),qr/transaction\/main\/dt:/,
        'a transaction-owned auxiliary DT is not a mutually exclusive transaction state');
    my ($timed_actor,$timed_ir) = fixture('timed_state',
        '(transaction main (on start) (set packet held) (set packet held))');
    my ($timed) = grep {grep {$_->{lhs} eq 'packet'} @{$_->{assignments}}} @{$timed_ir->{states}};
    $timed->{assignments}[0]{op} = '<1';
    like(refusal($timed_actor,$timed_ir),qr/cannot admit overlapping writers/,
        'timed operators do not inherit ordinary set point-active exclusion');
};

subtest 'malformed unknown generated or caller-pruned writer facts refuse before admission' => sub {
    my ($actor,$ir) = fixture('bad_facts','(transaction main (on start) (set packet held))');
    for my $case (
        ['generated',sub {$_[1]{children}={worker=>{}}},qr/generated record-output mappings/],
        ['unknown owner',sub {delete $_->{transaction} for @{$_[1]{states}}},qr/explicit source identity/],
        ['missing assignments',sub {delete $_[1]{states}[0]{assignments}},qr/complete 'assignments'/],
        ['missing declaration',sub {$_[1]{ports}=[grep {$_->{name} ne 'packet'} @{$_[1]{ports}}]},qr/lacks its realized output port/],
        ['mixed module',sub {$_[1]{domain_partition}={kind=>'multi_domain'}},qr/actual realized clock-domain/],
    ) {
        my ($name,$mutate,$reason) = @$case;
        my ($a,$i) = map {dclone($_)} ($actor,$ir);
        $mutate->($a,$i);
        like(refusal($a,$i),$reason,"$name remains a precise closed boundary");
    }
    eval {FSM::Scheduler::ISF::RecordOutputWriters->assert_admitted(actor=>$actor,ir=>$ir,inventory=>{writers=>[]})};
    like((split /\n/,$@)[0],qr/requires resolved actor and realized module maps/,
        'caller cannot omit actual writers with a supplied prefiltered inventory');
    for my $calls ('(spawn worker as one)', '(spawn worker as one) (spawn worker as two)') {
        my ($generated_actor,$generated_ir) = fixture('generated_output',
            '(transaction main (on start) '.$calls.' (complete done))'
            .' (transaction worker (set packet held))');
        ok(keys %{$generated_ir->{children}},'actual source lowers to generated child modules');
        like(refusal($generated_actor,$generated_ir),qr/generated record-output mappings/,
            'actual sole or reused generated output writer mapping stays closed');
    }
};

subtest 'authored output public boundary and existing scalar inputs remain unchanged' => sub {
    my $path = write_file('authored_output.isf','(actor closed (types (type frame '.$definition.'))'
        .' (interface (output packet (type frame))) (transaction main (set packet.payload 1)))');
    my $checked = FSM::Test::SourceQueryRunner::_capture([$^X,'bin/fsmgen','--strict','--check','--json',$path],'');
    is($checked->{exit_code},1,'whole-output admission does not silently admit authored field writes');
    my $report = $json->decode($checked->{stdout});
    ok(!$report->{success},'public check remains a failed product');
    like($checked->{stdout},qr/record output field writes are not yet admitted/,
        'existing primary declaration diagnostic remains visible');
    my $actor = FSM::Adapter::ISF->new->parse_source('(actor scalar (clock clk)'
        .' (interface (input start) (output packet (width 3)))'
        .' (transaction main (on start) (set packet 1)))','scalar.isf');
    my $ir = FSM::Scheduler::ISF->new->{ir}->build_module($actor);
    is_deeply(admit($actor,$ir),{module=>'scalar',output_declarations=>[],writers=>[]},
        'scalar-only actors have no invented record admission facts');
};

done_testing;

sub fixture {
    my ($name,$body,$type) = @_;
    $type //= 'frame';
    my $types = $type eq 'shared.frame' ? '(imports (package shared))' : '(types (type frame '.$definition.'))';
    my $path = write_file("$name.isf","(actor $name (clock clk) $types"
        .' (interface (input start) (input other) (output packet (width 5)) (output spare (width 5)) (output done))'
        ." (storage (var held (type $type)) (var alternate (type $type))) $body)");
    my $actor = FSM::Adapter::ISF->new->parse_file($path);
    # Private resolved-output prototypes, not authored output grammar admission.
    for my $port (grep {$_->{name} eq 'packet' || $_->{name} eq 'spare'} @{$actor->{interface}{outputs}}) {
        $port->{type} = $type;
        $port->{type_spec} = dclone($actor->{storage}[0]{type_spec});
    }
    $actor->{interface_port_metadata} = capture_interface_port_metadata($actor->{interface});
    my $scheduler = FSM::Scheduler::ISF->new;
    my $formal = FSM::Scheduler::ISF::FormalLowering->prepare($scheduler->{ir},$actor);
    $actor = $formal->{actor} if $formal;
    return ($actor,$scheduler->{ir}->build_module($actor));
}
sub competing_body {'(transaction left (on start) (set packet held)) (transaction right (on other) (set packet held))'}
sub admit {FSM::Scheduler::ISF::RecordOutputWriters->assert_admitted(actor=>$_[0],ir=>$_[1])}
sub refusal {
    my ($actor,$ir) = @_;
    my $ok = eval {admit($actor,$ir);1};
    ok(!$ok,'unsafe or unsupported combination refuses');
    return (split /\n/,$@)[0] // '';
}
sub write_file {
    my ($name,$text) = @_;
    my $path = "$work/$name";
    open my $fh,'>:raw',$path or die $!;
    print {$fh} $text or die $!;
    close $fh or die $!;
    return $path;
}

use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use Cwd qw(abs_path);
use Digest::SHA qw(sha256_hex);
use File::Temp qw(tempdir);
use JSON::PP;
use Storable qw(dclone);
use FSM::Test::ProjectDataLocality;
use FSM::Test::SourceQueryRunner qw(normalize_repository_paths);
use FSM::Support::SemanticIntrospectionMCPAdapter;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;

my $root = abs_path('.');
my $work = tempdir(CLEANUP => 1);
my $json = JSON::PP->new->canonical->utf8->allow_nonref;
my $adapter = FSM::Support::SemanticIntrospectionMCPAdapter->new(
    repo_root => $root, workspace_root => $root);
my %flags = (check => [qw(--strict --check --json)],
    semantic => [qw(--strict --emit-semantic-json)], schedule => ['--emit-schedule-json']);
my %tools = (check => 'fsmgen_check', semantic => 'fsmgen_semantic_introspect',
    schedule => 'fsmgen_schedule_preview');
my @producers = qw(bin/fsmgen bin/fsmgen-mcp
    perl/FSM/Support/SemanticIntrospectionMCPAdapter.pm
    perl/FSM/Adapter/ISF/Parser.pm perl/FSM/Scheduler/ISF.pm);
my $producer_before = fingerprints(@producers);
# The literal oracle is independent of the compiler's metadata/layout helpers.
my $definition = '(record (kind (bits 2)) (payload (record'
    . ' (data (signed (four_state (bits 5))))'
    . ' (flags (list bit (two_state (bits 2)))))))';
my $spec = {kind => 'record', width => 10, signed => 0, member_order => [qw(kind payload)], members => {
    kind => {kind => 'bits', width => 2, signed => 0},
    payload => {kind => 'record', width => 8, signed => 0, member_order => [qw(data flags)], members => {
        data => {kind => 'bits', width => 5, signed => 1, state_model => 'four_state'},
        flags => {kind => 'list', width => 3, signed => 0, items => [
            {kind => 'bit', width => 1, signed => 0},
            {kind => 'bits', width => 2, signed => 0, state_model => 'two_state'}]},
    }},
}};
my $fields = [
    {path => 'kind', width => 2, msb => 9, lsb => 8, signed => 0},
    {path => 'payload.data', width => 5, msb => 7, lsb => 3, signed => 1, state_model => 'four_state'},
    {path => 'payload.flags[0]', width => 1, msb => 2, lsb => 2, signed => 0},
    {path => 'payload.flags[1]', width => 2, msb => 1, lsb => 0, signed => 0, state_model => 'two_state'},
];
my $package = '(?pkg:shared (+types (type frame ' . $definition . ')))';
write_file("$work/shared.fsm", $package);
my $package_before = sha256_hex($package);
my $local = '(types (type frame ' . $definition . ') (type alias frame))';
my $ordinary = '(transaction main (on start) (set packet held)'
    . ' (set seen packet.payload.data) (wait 1) (set packet held) (complete done))';
my @cases = (
    ['local', $local, 'frame', 'frame', $ordinary],
    ['forward_alias', '(types (type alias frame) (type frame ' . $definition . '))', 'alias', 'frame', $ordinary],
    ['imported', '(imports (package shared))', 'shared.frame', 'shared.frame', $ordinary],
    ['imported_alias', '(imports (package shared)) (types (type alias shared.frame))', 'alias', 'shared.frame', $ordinary],
    ['mixed', $local, 'alias', 'frame',
        '(transaction main (on start) (set held incoming) (set packet held) (complete done))', 'mixed'],
    ['reverse', $local, 'frame', 'alias',
        '(transaction main (on start) (set held packet) (set echo packet) (complete done))', 'reverse'],
    ['unused', $local, 'alias', 'frame', '', 'unused'],
);

for my $case (@cases) {
    my ($name, $types, $output_type, $storage_type, $body, $variant) = @$case;
    subtest "complete public output source $name" => sub {
        my $text = '(actor public_output_' . $name . ' (clock clk) ' . $types
            . ' (interface (output packet (type ' . $output_type . ')) (input start)'
            . (($variant // '') eq 'mixed' ? ' (input incoming (type frame))' : '')
            . ' (output seen (width 5)) (output done)'
            . (($variant // '') eq 'reverse' ? ' (output echo (type frame))' : '') . ')'
            . ' (storage (var held (type ' . $storage_type . '))) ' . $body . ')';
        my $ports = [scalar_port('start', 'input', 1),
            (($variant // '') eq 'mixed' ? record_port('incoming', 'input', 'frame') : ()),
            record_port('packet', 'output', $output_type), scalar_port('seen', 'output', 5),
            scalar_port('done', 'output', 1),
            (($variant // '') eq 'reverse' ? record_port('echo', 'output', 'frame') : ())];
        my $path = "$work/$name.isf";
        write_file($path, $text);
        my $actor = FSM::Adapter::ISF->new->parse_file($path);
        my $before = $json->encode($actor);
        same($actor->{interface_port_metadata}, $ports, 'actual declarations follow inputs then outputs with authored order');
        my ($output) = grep {$_->{name} eq 'packet'} @{$actor->{interface}{outputs}};
        same($output->{type_spec}, $spec, 'exact independent recursive output identity');
        for my $kind (qw(check semantic schedule)) {
            my $observation = query($path, $kind);
            my $report = qualify_success($observation, $kind, $ports, 'public_output_' . $name);
            if ($kind eq 'semantic' && ref($report->{semantic}) eq 'HASH') {
                my ($signal) = grep {$_->{name} eq 'packet'}
                    @{$report->{semantic}{forward_ir}{intent_hir}{signal_analysis}{outputs}};
                ok(ref($signal) eq 'HASH', 'semantic output retains the authored endpoint');
                if (ref($signal) eq 'HASH') {
                    is($signal->{declared_type_name}, $output_type, 'semantic output keeps authored type spelling');
                    same($signal->{declared_type_spec}, $spec, 'semantic output retains full recursive type');
                }
            }
            preserve($name . '-' . $kind, {source => $text, package => $package, expected_ports => $ports,
                expected_type => $spec, observation => $observation});
        }
        my $scheduler = FSM::Scheduler::ISF->new;
        my $first = $json->decode($scheduler->report($actor));
        $first->{interface_ports}[1]{fields}[0]{msb} = 0;
        my $second = $json->decode($scheduler->report($actor));
        same($second->{interface_ports}, $ports, 'schedule metadata is independently detached on every read');
        same($actor->{interface_port_metadata}, $ports, 'mutating a report cannot alter declaration facts');
        is($json->encode($actor), $before, 'complete actor JSON kinds remain unchanged by repeated queries');
        is(sha256_hex(read_file($path)), sha256_hex($text), 'exact source bytes remain unchanged');
        is(sha256_hex(read_file("$work/shared.fsm")), $package_before, 'exact imported package bytes remain unchanged');
    };
}

subtest 'actual domain public reports retain complete top and selected-domain output metadata' => sub {
    my $text = '(actor public_output_domains (clock-domains (domain core (clock clk) :default)'
        . ' (domain bus (clock bus_clk))) ' . $local
        . ' (interface (output packet (type alias) (domain bus)) (input start)'
        . ' (input request (domain bus)) (output seen (width 5)))'
        . ' (storage (var held (type frame) (domain bus)))'
        . ' (transaction core_work (domain core) (on start) (set seen 1))'
        . ' (transaction publish (domain bus) (on request) (set packet held)))';
    my $path = "$work/domains.isf";
    write_file($path, $text);
    my $ports = [scalar_port('start', 'input', 1, 'core'), scalar_port('request', 'input', 1, 'bus'),
        record_port('packet', 'output', 'alias', 'bus'), scalar_port('seen', 'output', 5, 'core')];
    for my $kind (qw(check semantic schedule)) {
        my $observation = query($path, $kind);
        my $report = qualify_success($observation, $kind, $ports, 'public_output_domains_top');
        if ($kind eq 'schedule') {
            my %domains = map {$_->{name} => $_} @{$report->{clock_domains} // []};
            is_deeply([sort keys %domains], [qw(bus core)], 'complete literal domain membership');
            same($domains{bus}{interface_ports}, [scalar_port('request', 'input', 1, 'bus'), record_port('packet', 'output', 'alias', 'bus')],
                'bus domain owns exactly the declared record output and request');
            same($domains{core}{interface_ports}, [scalar_port('start', 'input', 1, 'core'), scalar_port('seen', 'output', 5, 'core')],
                'core domain cannot acquire the other physical output');
        }
        preserve('domains-' . $kind, {source => $text, expected_ports => $ports, observation => $observation});
    }
};

subtest 'actual public source and writer refusals cannot publish successful declaration or semantic products' => sub {
    for my $case (
        ['competing', '(transaction left (on start) (set packet held)) (transaction right (on other) (set packet held))',
            qr/record output 'packet' cannot admit overlapping writers/],
        ['field', '(transaction main (set packet.payload.data 1))', qr/record output field writes are not yet admitted/],
        ['literal', '(transaction main (set packet 0))', qr/whole record port copy requires declared record roots/],
        ['whole_sample', '(transaction main (on start (sample packet as captured)))', qr/sample requires a scalar value; 'packet' is a whole record/],
    ) {
        my ($name, $body, $reason) = @$case;
        my $text = '(actor public_output_' . $name . ' (clock clk) ' . $local
            . ' (interface (input start) (input other) (output packet (type alias)))'
            . ' (storage (var held (type frame))) ' . $body . ')';
        my $path = "$work/refused_$name.isf";
        write_file($path, $text);
        for my $kind (qw(check semantic schedule)) {
            my $observation = query($path, $kind);
            my $native = $observation->{native};
            is($native->{exit_code}, $kind eq 'schedule' ? 255 : 1, "$name/$kind established native refusal status");
            is($native->{signal}, 0, "$name/$kind no native signal");
            if ($kind ne 'schedule') {
                my $report = $observation->{report};
                is($native->{stderr}, '', "$name/$kind machine report owns diagnostics");
                is($json->encode($report->{success}), 'false', "$name/$kind exact JSON failure kind");
                like($report->{diagnostics}[0]{message}, $reason, "$name/$kind precise authored primary reason");
                ok(exists($report->{diagnostics}[0]{code}), "$name/$kind retained nullable diagnostic code");
                ok(!exists($report->{source}{interface_ports}), "$name/$kind no successful declaration metadata");
                ok(!defined($report->{semantic}), "$name/$kind no partial semantic product");
                same($observation->{response}{result}{structuredContent}{report}, $report,
                    "$name/$kind complete typed native/API failure equality");
                same($json->decode($observation->{response}{result}{content}[0]{text}),
                    $observation->{response}{result}{structuredContent}, "$name/$kind complete failure text/structured equality");
                is($json->encode($observation->{response}{result}{isError}), 'true',
                    "$name/$kind exact error envelope kind");
            } else {
                like($native->{stderr}, $reason, "$name schedule retains the actual primary refusal");
                is($native->{stdout}, '', "$name schedule publishes no partial JSON product");
                is($observation->{response}{error}{code}, -32000, "$name schedule retains the established JSON-RPC error");
                is($observation->{response}{error}{message}, 'FSMGen command failed without a matching public failure report',
                    "$name schedule retains the bounded message-only public contract");
                ok(!exists($observation->{response}{result}), "$name schedule has no successful result envelope");
            }
            preserve('refused-' . $name . '-' . $kind, {source => $text, observation => $observation});
        }
        is(sha256_hex(read_file($path)), sha256_hex($text), "$name refusal preserves source bytes");
    }
};

subtest 'independent literal metadata rejects corruption shared by all transports' => sub {
    my $ports = [scalar_port('start', 'input', 1), record_port('packet', 'output', 'alias')];
    for my $change (
        sub {$_[0][1]{direction} = 'input'},
        sub {$_[0][1]{width} = '10'},
        sub {$_[0][1]{fields}[1]{signed} = 0},
        sub {delete $_[0][1]{fields}[1]{state_model}},
        sub {$_[0][1]{fields}[0]{lsb} = 0},
        sub {pop @{$_[0][1]{fields}}},
        sub {@{$_[0][1]{fields}} = reverse @{$_[0][1]{fields}}},
        sub {$_[0][1]{fields}[0]{state_model} = 'two_state'},
    ) {
        my $bad = dclone($ports); $change->($bad);
        same(dclone($bad), dclone($bad), 'shared transport equality alone cannot prove correctness');
        isnt($json->encode($bad), $json->encode($ports), 'literal oracle detects role, kind, packing, state, signedness or order corruption');
    }
};
same(fingerprints(@producers), $producer_before, 'all named public/source producer bytes remain unchanged');
done_testing;

sub scalar_port {return {name => $_[0], direction => $_[1], width => $_[2],
    defined($_[3]) ? (domain => $_[3]) : ()}}
sub record_port {return {name => $_[0], direction => $_[1], width => 10,
    type => $_[2], type_kind => 'record', fields => dclone($fields),
    defined($_[3]) ? (domain => $_[3]) : ()}}
sub same {is($json->encode($_[0]), $json->encode($_[1]), $_[2])}
sub qualify_success {
    my ($o, $kind, $ports, $module) = @_;
    is($o->{native}{exit_code}, 0, "$kind actual native source succeeds")
        or diag($o->{native}{stdout}, $o->{native}{stderr});
    is($o->{native}{signal}, 0, "$kind actual native terminates normally");
    is($o->{native}{stderr}, '', "$kind machine stderr clean");
    my $r = $o->{report};
    ok(ref($r) eq 'HASH', "$kind native publishes a complete JSON object");
    return {} unless ref($r) eq 'HASH';
    same($o->{response}{result}{structuredContent}{report}, $r, "$kind complete typed native/API equality");
    is($json->encode($o->{response}{result}{isError}), 'false', "$kind exact successful tool kind");
    same($json->decode($o->{response}{result}{content}[0]{text}), $o->{response}{result}{structuredContent},
        "$kind complete text/structured equality");
    same($kind eq 'schedule' ? $r->{interface_ports} : $r->{source}{interface_ports}, $ports,
        "$kind complete independent declaration/layout oracle");
    if ($kind ne 'schedule') {
        is($json->encode($r->{success}), 'true', "$kind exact successful report kind");
        is($json->encode($r->{generated_output}{emitted}), 'false', "$kind read-only query publishes no HDL artifact");
        same($r->{diagnostics}, [], "$kind complete empty diagnostics");
        is($kind eq 'check' ? $r->{result}{module_name} : $r->{semantic}{module}{name}, $module,
            "$kind independently named realized module");
    }
    return $r;
}
sub query {
    my ($path, $kind) = @_;
    my $source_before = sha256_hex(read_file($path));
    my $relative = $path =~ s/^\Q$root\E\///r;
    my $native = FSM::Test::SourceQueryRunner::_capture([$^X, 'bin/fsmgen', @{$flags{$kind}}, $relative], '');
    my $report = eval {$json->decode($native->{stdout})};
    $report = normalize_repository_paths($report, $root) if ref($report) eq 'HASH';
    my $request = {jsonrpc => '2.0', id => 1, method => 'tools/call', params => {
        name => $tools{$kind}, arguments => {source_id => $relative}}};
    my $response = $adapter->handle_jsonrpc_request($request);
    my $wire = FSM::Test::SourceQueryRunner::_capture([$^X, 'bin/fsmgen-mcp', '--workspace-root', '.'],
        $json->encode($request) . "\n");
    is($wire->{exit_code}, 0, "$kind actual newline process succeeds");
    is($wire->{signal}, 0, "$kind newline process terminates normally");
    is($wire->{stderr}, '', "$kind actual newline stderr clean");
    like($wire->{stdout}, qr/\A[^\n]+\n\z/, "$kind exactly one compact newline response");
    my $decoded = $json->decode($wire->{stdout});
    same($decoded, $response, "$kind complete typed in-process/newline response equality");
    my $source_after = sha256_hex(read_file($path));
    is($source_after, $source_before, "$kind every actual query preserves exact source bytes");
    return {native => $native, report => $report, request => $request, response => $response, wire => $wire,
        source_sha256_before => $source_before, source_sha256_after => $source_after};
}
sub fingerprints {return {map {$_ => sha256_hex(read_file($_))} @_}}
sub preserve {
    return unless ($ENV{FSMGEN_RECORD_OUTPUT_PUBLIC_CAPTURE} // '') eq '1';
    my ($name, $value) = @_;
    die 'invalid fixed witness name' unless $name =~ /\A[a-z_-]+\z/;
    write_file('.artifacts/record-output-public/' . $name . '.json', $json->encode($value) . "\n");
}
sub read_file {open my $fh, '<:raw', $_[0] or die $!; local $/; return <$fh>}
sub write_file {open my $fh, '>:raw', $_[0] or die $!; print {$fh} $_[1] or die $!; close $fh or die $!}

source_snapshots.t/2035-isf-record-output-target-profiles:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use Cwd qw(abs_path);
use Digest::SHA qw(sha256_hex);
use File::Temp qw(tempdir);
use JSON::PP;
use FSM::Test::ProjectDataLocality;
use FSM::Test::SourceQueryRunner;
use FSM::Pipeline::HDLGenerator;

my $root = abs_path('.');
my $work = tempdir(CLEANUP => 1);
my $json = JSON::PP->new->canonical->utf8;
my $definition = '(record (tag (bits 2)) (body (record (data (signed (four_state (bits 3)))) (flag bit))))';
my $package = '(?pkg:shared (+types (type frame ' . $definition . ')))';
write_file("$work/shared.fsm", $package);
my @producers = qw(bin/fsmgen perl/FSM/Pipeline/HDLGenerator.pm perl/FSM/Adapter/ISF/Parser.pm
    perl/FSM/Scheduler/ISF.pm perl/FSM/Support/ISFHDLProfile.pm);
my $before = fingerprints(@producers);
my $sentinel = "EXISTING DESTINATION\nkeep every byte\n";
my @observed;

for my $name (qw(local imported alias mixed unused)) {
    subtest "actual record-output target profiles $name" => sub {
        my ($types, $type) = $name eq 'imported'
            ? ('(imports (package shared))', 'shared.frame')
            : $name eq 'alias' ? ('(imports (package shared)) (types (type alias shared.frame))', 'alias')
            : ('(types (type frame ' . $definition . '))', 'frame');
        my $source = '(actor target_output_' . $name . ' (clock clk) ' . $types
            . ' (interface (output packet (type ' . $type . ')) (input start)'
            . ($name eq 'mixed' ? ' (input incoming (type frame))' : '') . ' (output done))'
            . ' (storage (var held (type ' . $type . ')))'
            . ($name eq 'unused' ? '' : ' (transaction main (on start) (set packet held) (complete done))') . ')';
        my $path = "$work/$name.isf";
        write_file($path, $source);
        my @results;
        for my $target (qw(verilog v vhdl)) {
            my $reason = reason($name, $type, $target);
            my $output = "$work/refused_${name}_$target.hdl";
            write_file($output, $sentinel);
            my $existing = capture([$^X, 'bin/fsmgen', '--strict', '--quiet', '--language', $target,
                '--output', $output, $path]);
            ok(refused($existing, $reason), "$target exact contextual primary refusal ends normally")
                or diag($existing->{stdout}, $existing->{stderr});
            is(read_file($output), $sentinel, "$target existing destination stays byte-exact");
            is($existing->{stdout}, '', "$target failure publishes no stdout HDL payload");
            my $destination_sha = sha256_hex(read_file($output));
            unlink $output or die $!;
            my $absent = capture([$^X, 'bin/fsmgen', '--strict', '--quiet', '--language', $target,
                '--output', $output, $path]);
            ok(refused($absent, $reason), "$target absent destination has the same precise normal refusal")
                or diag($absent->{stderr});
            ok(!-e $output, "$target refusal creates no destination");
            my ($product, $error);
            eval {$product = FSM::Pipeline::HDLGenerator->new(target_language => $target, quiet => 1, strict_mode => 1)
                ->generate_hdl_from_file($path); 1} or $error = $@;
            ok(!defined($product), "$target public HDL facade publishes no partial product");
            like($error // '', qr/^\Q$reason\E(?:\n| at |$)/, "$target facade retains exact contextual primary reason");
            my %machine;
            for my $kind (['check', qw(--check --json)], ['semantic', '--emit-semantic-json']) {
                my ($mode, @flags) = @$kind;
                my $native = capture([$^X, 'bin/fsmgen', '--strict', '--quiet', '--language', $target, @flags, $path]);
                is($native->{exit_code}, 1, "$target/$mode normal profile refusal status");
                is($native->{signal}, 0, "$target/$mode no signal");
                is($native->{stderr}, '', "$target/$mode machine product owns the diagnostic");
                my $report = $json->decode($native->{stdout});
                is($json->encode($report->{success}), 'false', "$target/$mode exact JSON false kind");
                is($report->{diagnostics}[0]{message}, $reason, "$target/$mode exact primary reason without stack");
                ok(exists($report->{diagnostics}[0]{code}), "$target/$mode retained nullable diagnostic code");
                ok(!exists($report->{source}{interface_ports}), "$target/$mode no successful declaration metadata");
                ok(!defined($report->{semantic}), "$target/$mode no partial semantic product");
                $machine{$mode} = {native => $native, report => $report};
            }
            my $schedule = capture([$^X, 'bin/fsmgen', '--strict', '--quiet', '--language', $target,
                '--emit-schedule-json', $path]);
            is($schedule->{exit_code}, 0, "$target target-neutral schedule remains available");
            is($schedule->{signal}, 0, "$target schedule ends normally");
            is($schedule->{stderr}, '', "$target schedule machine stderr stays clean");
            my $report = $json->decode($schedule->{stdout});
            my ($packet) = grep {$_->{name} eq 'packet'} @{$report->{interface_ports}};
            is($packet->{width}, 6, "$target schedule retains literal complete output width");
            is($packet->{type}, $type, "$target schedule retains authored output type");
            is_deeply($packet->{fields}, [
                {path => 'tag', width => 2, msb => 5, lsb => 4, signed => 0},
                {path => 'body.data', width => 3, msb => 3, lsb => 1, signed => 1, state_model => 'four_state'},
                {path => 'body.flag', width => 1, msb => 0, lsb => 0, signed => 0},
            ], "$target schedule literal nested signed/state layout survives profile refusal");
            push @observed, [$existing, $reason];
            push @results, {target => $target, reason => $reason, existing => $existing, absent => $absent,
                destination_sha256 => $destination_sha, absent_destination_exists => (-e $output ? JSON::PP::true : JSON::PP::false),
                facade_product => $product, facade_error => $error, machine => \%machine, schedule => $schedule};
        }
        my %supported;
        for my $target (qw(systemverilog sv)) {
            my $output = "$work/supported_${name}_$target.sv";
            my $native = capture([$^X, 'bin/fsmgen', '--strict', '--quiet', '--language', $target, '--output', $output, $path]);
            is($native->{exit_code}, 0, "$target source generation succeeds") or diag($native->{stderr});
            is($native->{signal}, 0, "$target generation ends normally");
            is($native->{stderr}, '', "$target supported generation stderr stays clean");
            my $hdl = read_file($output);
            like($hdl, qr/\bmodule target_output_\Q$name\E\b/, "$target independently named module remains");
            like($hdl, qr/typedef struct packed/, "$target retains packed record type declarations");
            like($hdl, qr/logic signed \[2:0\] data;/, "$target signed three-bit data remains explicit");
            like($hdl, qr/\boutput\b[^\n]*\bpacket\b/, "$target retains the authored output endpoint");
            my $product = FSM::Pipeline::HDLGenerator->new(target_language => $target, quiet => 1, strict_mode => 1)
                ->generate_hdl_from_file($path);
            like($product->{hdl_code}, qr/\bmodule target_output_\Q$name\E\b/, "$target public facade admits the same source module");
            like($product->{hdl_code}, qr/logic signed \[2:0\] data;/, "$target public facade retains exact signed leaf text");
            $supported{$target} = {native => $native, hdl => $hdl, facade => {hdl_code => $product->{hdl_code}, source_info => $product->{source_info},
                result_keys => [sort keys %$product]}};
        }
        is(normalize_date($supported{sv}{hdl}), normalize_date($supported{systemverilog}{hdl}),
            'complete native alias products are equal except dated banners');
        is(sha256_hex(read_file($path)), sha256_hex($source), 'complete profile qualification preserves source bytes');
        is(sha256_hex(read_file("$work/shared.fsm")), sha256_hex($package), 'complete profile qualification preserves package bytes');
        preserve($name, {source => $source, package => $package, type => $type, sentinel => $sentinel,
            refused => \@results, supported => \%supported});
    };
}

subtest 'profile refusal oracle rejects false success signal absent and secondary causes' => sub {
    for my $row (@observed) {
        my ($r, $reason) = @$row;
        ok(!refused({%$r, exit_code => 0}, $reason), 'false success cannot qualify refusal');
        ok(!refused({%$r, signal => 9}, $reason), 'signal failure cannot qualify precise profile refusal');
        ok(!refused({%$r, stderr => ''}, $reason), 'missing diagnostic cannot qualify refusal');
        ok(!refused({%$r, stderr => "Error generating HDL: unrelated cause\n$reason\n"}, $reason),
            'expected reason only later in stderr cannot replace the primary cause');
    }
};
is_deeply(fingerprints(@producers), $before, 'complete named producer bytes remain unchanged');
done_testing;

sub reason {
    my ($name, $type, $target) = @_;
    $target = 'verilog' if $target eq 'v';
    my $input = $name eq 'mixed' && $target eq 'verilog';
    return "ISF actor 'target_output_$name' record " . ($input ? "input 'incoming' (type 'frame')" : "output 'packet' (type '$type')")
        . " cannot generate target '$target': packed record " . ($input ? 'inputs' : 'outputs')
        . ' require SystemVerilog; use --language systemverilog. '
        . ($target eq 'verilog' ? 'Verilog-2005 record lowering is not implemented.' : 'VHDL record-output lowering is not implemented.');
}
sub refused {
    my ($r, $reason) = @_;
    my $first = (split /\n/, $r->{stderr})[0] // '';
    return $r->{exit_code} == 1 && $r->{signal} == 0
        && $first =~ /^(?:Error generating HDL: )?\Q$reason\E(?: at |$)/ ? 1 : 0;
}
sub normalize_date {my $text = $_[0]; $text =~ s{^// Date:[^\n]*$}{// Date: omitted}mg; return $text}
sub capture {FSM::Test::SourceQueryRunner::_capture($_[0], '')}
sub fingerprints {return {map {$_ => sha256_hex(read_file($_))} @_}}
sub preserve {
    return unless ($ENV{FSMGEN_RECORD_OUTPUT_PROFILE_CAPTURE} // '') eq '1';
    write_file('.artifacts/record-output-target-profiles/' . $_[0] . '.json', $json->encode($_[1]) . "\n");
}
sub read_file {open my $fh, '<:raw', $_[0] or die $!; local $/; return <$fh>}
sub write_file {open my $fh, '>:raw', $_[0] or die $!; print {$fh} $_[1] or die $!; close $fh or die $!}

source_snapshots.t/2043-isf-conditional-origin-parser.t:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use FSM::Test::DiagnosticCause qw(diagnostic_cause_matches);
use JSON::PP;
use Digest::SHA qw(sha256_hex);
use FSM::Adapter::ISF::Parser;
use FSM::Test::ConditionalOriginParser;
use FSM::Scheduler::ISF;

my $json = JSON::PP->new->canonical;
my $base = 'docs/audits/conditional-macro-intent-20261002';
my $cases = $json->decode(read_file("$base/cases.json"));
my @families = qw(select min max when_bit unless_bit when_field unless_field cond);
my @names = ((map {("first_$_", "later_$_")} @families),
    (map {("first_${_}_sample", "later_${_}_sample")} qw(when_bit unless_bit when_field unless_field cond)),
    (map {("first_proc_$_", "later_proc_$_")} qw(select when_bit cond)));
push @names, qw(first_proc_when_sample first_when_sample first_select_zero first_bit_sample_zero
    initialized_select nested_select domain_first_select domain_later_select domain_first_sample
    first_generated_select later_generated_select);
is_deeply([sort map {$_->{name}} @$cases], [sort @names], 'fixed full predecessor source membership');
for my $case (@$cases) {
    my $name = $case->{name};
    subtest "explicit actual parser origin $name" => sub {
        my $path = "$base/sources/$name.isf";
        my ($actor, $ledger, $parser) = qualify($name, read_file($path), $path);
        my $op = $case->{family};
        $op =~ tr/_/-/;
        $op = 'when' if $case->{family} eq 'authored_when';
        my @ops = map {$ledger->{catalog}[$_->{origin}{catalog_id}]{operation}} @{$ledger->{entries}};
        if ($name eq 'first_proc_cond' || $name eq 'later_proc_cond') {
            is_deeply(\@ops, [], 'inline cond remains unnormalized, never relabeled as activation');
            is_deeply([map {$ledger->{catalog}[$_->{origin}{catalog_id}]{operation}} @{$ledger->{residuals}}],
                ['cond'], 'actual unsupported inline cond has explicit residual origin');
        } else {
            my $count = $op =~ /\A(?:select|min|max|cond)\z/ ? 2 : 1;
            my @expected = (($op) x $count);
            unshift @expected, 'when' if $name eq 'nested_select';
            is_deeply(\@ops, \@expected, 'literal authored family survives all canonical rewrites');
            is_deeply($ledger->{residuals}, [], 'supported normalization has no residual conditional');
            my @ordinals = map {$_->{origin}{branch_ordinal}} @{$ledger->{entries}};
            my @expected_ordinals = $op eq 'when' ? (undef) : $count == 2 ? (0, 1) : (0);
            unshift @expected_ordinals, undef if $name eq 'nested_select';
            is_deeply(\@ordinals, \@expected_ordinals, 'literal full expansion ordinal association');
        }
        for my $entry (@{$ledger->{entries}}, @{$ledger->{residuals}}) {
            my $origin = $entry->{origin};
            my $record = $ledger->{catalog}[$origin->{catalog_id}];
            is($record->{owner}{kind}, $name =~ /proc/ ? 'procedure' : 'transaction',
                'literal original owner kind');
            is(scalar(@{$origin->{calls}}), $name =~ /proc/ ? 1 : 0, 'literal inline call depth');
        }
        mutation_controls($actor, $ledger, $parser) if @{$ledger->{entries}};
    };
}

my $header = '(actor origin_probe (interface (input start) (input allow) (input datain (width 3))'
    . ' (input other (width 3)) (output done)) (storage (var seen (width 3))) ';
my $select_source = $header . '(transaction main (on start) (select seen allow datain other) (complete done)))';
my $authored_source = $header . '(transaction main (on start) (when allow (set seen datain))'
    . ' (when (! allow) (set seen other)) (complete done)))';
subtest 'identical normalized clauses retain different source intent' => sub {
    my ($macro_actor, $macro_ledger) = qualify('twin_macro', $select_source, 'twin.isf');
    my ($authored_actor, $authored_ledger) = qualify('twin_authored', $authored_source, 'twin.isf');
    is($json->encode($macro_actor), $json->encode($authored_actor), 'complete normalized actors are identical');
    is_deeply([map {$macro_ledger->{catalog}[$_->{origin}{catalog_id}]{operation}} @{$macro_ledger->{entries}}],
        ['select', 'select'], 'macro ledger comes from actual select producer');
    is_deeply([map {$authored_ledger->{catalog}[$_->{origin}{catalog_id}]{operation}} @{$authored_ledger->{entries}}],
        ['when', 'when'], 'authored ledger comes from original when clauses');
};

my @extra = (
    ['let_select', '(transaction main (let pick allow) (select seen pick datain other) (complete done))', ['select','select'], [0,0]],
    ['for_select', '(transaction main (for (i 2) (select seen allow datain other)) (complete done))', ['select','select'], [0,0]],
    ['while_field', '(transaction main (while allow (when-field datain (bits 2 1) 1 (sample other as captured))) (complete done))', ['when-field'], [0]],
    ['repeat_bit', '(transaction main (repeat 2 (unless-bit datain 1 (sample other as captured))) (complete done))', ['unless-bit'], [0]],
    ['switch_cond', '(transaction main (switch datain (0 (cond (allow (set seen datain)) (else (set seen other))))) (complete done))', ['cond','cond'], [0,0]],
    ['nested_calls', '(proc inner (params (c)) (select seen c datain other)) (proc outer (params (c)) (call inner c)) (transaction main (call outer allow) (complete done))', ['select','select'], [2,2]],
    ['reused_calls', '(proc choose (params (c)) (when c (sample datain as captured))) (transaction main (call choose allow) (call choose start) (complete done))', ['when','when'], [1,1]],
    ['nested_cond', '(transaction main (cond (allow (cond (start (set seen datain)) (else (set seen other)))) (else (set seen 0))) (complete done))', ['cond','cond','cond','cond'], [0,0,0,0]],
);
my %extra_guards = (
    let_select => ['allow', ['!', 'allow']],
    for_select => ['allow', ['!', 'allow']],
    while_field => [['==', ['&', 'datain', "3'd6"], "3'd2"]],
    repeat_bit => [['==', ['&', 'datain', "3'd2"], "3'd0"]],
    switch_cond => ['allow', ['!', 'allow']],
    nested_calls => ['allow', ['!', 'allow']],
    reused_calls => ['allow', 'start'],
    nested_cond => ['allow', 'start', ['!', 'start'], ['!', 'allow']],
);
for my $extra (@extra) {
    my ($name, $body, $ops, $depths) = @$extra;
    subtest "source context $name" => sub {
        my ($actor, $ledger) = qualify($name, $header . $body . ')', "$name.isf");
        is_deeply([map {$ledger->{catalog}[$_->{origin}{catalog_id}]{operation}} @{$ledger->{entries}}], $ops,
            'independent exact operation order');
        is_deeply([map {scalar @{$_->{origin}{calls}}} @{$ledger->{entries}}], $depths,
            'independent exact call depths');
        is_deeply([map {$_->{target}[1]} @{$ledger->{entries}}], $extra_guards{$name},
            'independent complete normalized guard values');
        if ($name eq 'nested_calls') {
            is_deeply([map {$_->{procedure}} @{$ledger->{entries}[0]{origin}{calls}}],
                ['outer', 'inner'], 'full literal ordered nested call chain');
            is_deeply([map {$_->{context}} @{$ledger->{entries}[0]{origin}{calls}}],
                ["transaction 'main'", "transaction 'main' -> proc 'outer'"],
                'full literal actual call contexts');
        }
        if ($name eq 'reused_calls') {
            isnt($ledger->{entries}[0]{origin}{calls}[0]{catalog_id},
                $ledger->{entries}[1]{origin}{calls}[0]{catalog_id},
                'same definition retains two distinct actual source call sites');
            is_deeply([map {$_->{target}[1]} @{$ledger->{entries}}], ['allow','start'],
                'each substituted guard remains bound to its own caller');
        }
        for my $entry (@{$ledger->{entries}}) {
            my $target = $actor;
            $target = ref($target) eq 'HASH' ? $target->{$_} : $target->[$_] for @{$entry->{path}};
            is($json->encode($target), $json->encode($entry->{target}), 'direct actual-offset path resolves complete target');
        }
    };
}

subtest 'first sample-procedure cond stays publicly closed' => sub {
    my $path = 'docs/audits/procedure-cond-normalization-20261002/sources/first_samples.isf';
    my ($actor, $ledger) = qualify('first_samples', read_file($path), $path);
    is_deeply($ledger->{entries}, [], 'no fabricated when association');
    is(scalar @{$ledger->{residuals}}, 1, 'whole original cond remains explicit residual');
    my $before = $json->encode($actor);
