my $repo_root = File::Spec->rel2abs(File::Spec->catdir($FindBin::Bin, '..'));
my $fsmgen_bin = File::Spec->catfile($repo_root, 'bin', 'fsmgen');
my $tempdir = tempdir(CLEANUP => 1);
